window.READ = [{"id":"r01","lv":1,"t":"저를 소개합니다","tz":"自我介紹","k":"[안녕하세요]? 제 [이름]은 왕민지예요. 저는 대만에서 [왔어요|오다]. 지금 서울에서 [한국어]를 [공부해요|공부하다]. 한국어는 [조금] [어렵지만|어렵다] [재미있어요|재미있다].","z":"你好，我叫王敏智。我從台灣來。現在在首爾學韓語。韓語有點難，但是很有趣。","q":[{"q":"이 사람은 어디에서 왔습니까?","c":["대만","서울","한국","일본"],"e":"「대만에서 왔어요」＝從台灣來。","qt":"這個人從哪裡來？"},{"q":"이 사람은 지금 무엇을 합니까?","c":["한국어를 공부합니다","한국어를 가르칩니다","대만에서 일합니다","일본어를 공부합니다"],"e":"「지금 서울에서 한국어를 공부해요」＝現在在首爾學韓語。","qt":"這個人現在在做什麼？"}]},{"id":"r02","lv":1,"t":"우리 가족","tz":"我的家人","k":"우리 [가족]은 네 [명]이에요. [아버지]는 [회사원]이에요. [어머니]는 [선생님]이에요. [남동생]은 [고등학생]이에요. 우리 가족은 [주말]마다 [같이] [산책해요|산책].","z":"我們家有四個人。爸爸是上班族。媽媽是老師。弟弟是高中生。我們家每個週末一起散步。","q":[{"q":"어머니는 무슨 일을 합니까?","c":["선생님입니다","회사원입니다","고등학생입니다","의사입니다"],"e":"「어머니는 선생님이에요」＝媽媽是老師。","qt":"媽媽做什麼工作？"},{"q":"이 가족은 주말에 무엇을 합니까?","c":["같이 산책합니다","같이 영화를 봅니다","같이 요리합니다","같이 쇼핑합니다"],"e":"「주말마다 같이 산책해요」＝每個週末一起散步。","qt":"這家人週末做什麼？"}]},{"id":"r03","lv":1,"t":"제 방","tz":"我的房間","k":"제 [방]은 [작아요|작다]. 하지만 [깨끗해요|깨끗하다]. 방에 [침대]와 [책상]이 [있어요|있다]. 책상 [위]에 [컴퓨터]가 있어요. 저는 제 방을 [좋아해요|좋아하다].","z":"我的房間很小。但是很乾淨。房間裡有床和書桌。書桌上有電腦。我喜歡我的房間。","q":[{"q":"방에 무엇이 없습니까?","c":["소파","침대","책상","컴퓨터"],"e":"房間裡有床、書桌、電腦，沒有提到沙發。","qt":"房間裡沒有什麼？"},{"q":"이 사람의 방은 어떻습니까?","c":["작지만 깨끗합니다","크고 깨끗합니다","작고 더럽습니다","크지만 더럽습니다"],"e":"「작아요. 하지만 깨끗해요」＝很小，但是很乾淨。","qt":"這個人的房間怎麼樣？"}]},{"id":"r04","lv":1,"t":"오늘 날씨","tz":"今天的天氣","k":"오늘은 [날씨]가 [좋아요|좋다]. [하늘]이 [맑아요|맑다]. [바람]도 [시원해요|시원하다]. 그래서 [친구]와 [공원]에 [가요|가다]. 공원에서 [자전거]를 [탈|타다] 거예요.","z":"今天天氣很好。天空很晴朗。風也很涼爽。所以要和朋友去公園。要在公園騎腳踏車。","q":[{"q":"오늘 날씨는 어떻습니까?","c":["맑고 시원합니다","비가 옵니다","눈이 옵니다","춥고 흐립니다"],"e":"天空晴朗（맑아요）、風很涼爽（시원해요）。","qt":"今天天氣怎麼樣？"},{"q":"이 사람은 공원에서 무엇을 할 겁니까?","c":["자전거를 탑니다","축구를 합니다","책을 읽습니다","사진을 찍습니다"],"e":"「자전거를 탈 거예요」＝要騎腳踏車。","qt":"這個人要在公園做什麼？"}]},{"id":"r05","lv":1,"t":"나의 아침","tz":"我的早上","k":"저는 [아침] [일곱] [시]에 [일어나요|일어나다]. [세수]를 하고 [아침밥]을 [먹어요|먹다]. [보통] [빵]과 [우유]를 먹어요. [여덟] 시에 [버스]를 [타고|타다] [학교]에 가요.","z":"我早上七點起床。洗臉後吃早餐。通常吃麵包和牛奶。八點搭公車去學校。","q":[{"q":"이 사람은 몇 시에 일어납니까?","c":["일곱 시","여덟 시","아홉 시","여섯 시"],"e":"「아침 일곱 시에 일어나요」＝早上七點起床；八點是去學校的時間。","qt":"這個人幾點起床？"},{"q":"이 사람은 아침에 보통 무엇을 먹습니까?","c":["빵과 우유","밥과 김치","과일과 주스","라면"],"e":"「보통 빵과 우유를 먹어요」＝通常吃麵包和牛奶。","qt":"這個人早上通常吃什麼？"}]},{"id":"r06","lv":1,"t":"친구의 메시지","tz":"朋友的訊息","k":"수미 씨, [내일] [시간] [있어요|있다]? [같이] [영화]를 [봐요|보다]. [세] [시]에 [극장] [앞]에서 [만나요|만나다]. [답장] [주세요|주다]. - 민수 -","z":"秀美，明天有時間嗎？一起看電影吧。三點在電影院前面見。請回覆我。— 民秀 —","q":[{"q":"두 사람은 어디에서 만납니까?","c":["극장 앞","학교 앞","공원","카페"],"e":"「극장 앞에서 만나요」＝在電影院前面見。","qt":"兩個人在哪裡見面？"},{"q":"민수 씨는 무엇을 하고 싶어 합니까?","c":["영화를 보고 싶어 합니다","공부하고 싶어 합니다","쇼핑하고 싶어 합니다","운동하고 싶어 합니다"],"e":"「같이 영화를 봐요」＝一起看電影吧。","qt":"民秀想做什麼？"}]},{"id":"r07","lv":1,"t":"시장에 갔어요","tz":"去了市場","k":"오늘 [어머니]와 [시장]에 [갔어요|가다]. 시장에는 [사람]이 [많았어요|많다]. 우리는 [사과]와 [딸기]를 [샀어요|사다]. [과일]이 [싸고|싸다] [맛있었어요|맛있다].","z":"今天和媽媽去了市場。市場人很多。我們買了蘋果和草莓。水果又便宜又好吃。","q":[{"q":"무엇을 샀습니까?","c":["사과와 딸기","사과와 배","포도와 딸기","수박과 사과"],"e":"「사과와 딸기를 샀어요」＝買了蘋果和草莓。","qt":"買了什麼？"},{"q":"시장은 어땠습니까?","c":["사람이 많았습니다","사람이 없었습니다","과일이 비쌌습니다","문을 닫았습니다"],"e":"「사람이 많았어요」＝人很多；水果是便宜的。","qt":"市場怎麼樣？"}]},{"id":"r08","lv":1,"t":"제 취미","tz":"我的興趣","k":"제 [취미]는 [요리]예요. [주말]에 [한국] [음식]을 [만들어요|만들다]. [김치찌개]를 [제일] [잘] 만들어요. [친구]들이 [맛있다고|맛있다] 해요.","z":"我的興趣是做菜。週末會做韓國菜。泡菜鍋做得最好。朋友們都說很好吃。","q":[{"q":"이 사람의 취미는 무엇입니까?","c":["요리","운동","독서","여행"],"e":"「제 취미는 요리예요」＝我的興趣是做菜。","qt":"這個人的興趣是什麼？"},{"q":"이 사람은 무엇을 제일 잘 만듭니까?","c":["김치찌개","불고기","비빔밥","김밥"],"e":"「김치찌개를 제일 잘 만들어요」＝泡菜鍋做得最好。","qt":"這個人最會做什麼？"}]},{"id":"r09","lv":2,"t":"등산","tz":"爬山","k":"지난 [주말]에 [친구]와 [등산]을 [갔어요|가다]. [아침] [일찍] [출발했어요|출발하다]. [산]은 [높았지만|높다] [경치]가 [정말] [아름다웠어요|아름답다]. 산 [위]에서 [김밥]을 [먹었어요|먹다]. [다리]가 [아팠지만|아프다] [기분]이 [좋았어요|좋다].","z":"上週末和朋友去爬山。一大早就出發了。山很高，但風景真的很美。在山上吃了海苔飯捲。腿很痛，但心情很好。","q":[{"q":"산 위에서 무엇을 먹었습니까?","c":["김밥","라면","빵","과일"],"e":"「산 위에서 김밥을 먹었어요」。","qt":"在山上吃了什麼？"},{"q":"이 글의 내용과 같은 것은?","c":["아침 일찍 출발했습니다","혼자 등산을 갔습니다","산이 낮았습니다","기분이 나빴습니다"],"e":"和朋友去、山很高、心情很好，只有「一大早出發」正確。","qt":"下列哪一項和內容相同？"}]},{"id":"r10","lv":2,"t":"생일 파티","tz":"生日派對","k":"[어제]는 제 [생일]이었어요. [친구]들이 우리 [집]에 [왔어요|오다]. [어머니]가 [맛있는|맛있다] [음식]을 많이 [만드셨어요|만들다]. 친구들은 [케이크]와 [선물]을 [가져왔어요|가져오다]. 우리는 [노래]를 [부르고|부르다] [사진]도 [찍었어요|찍다]. [정말] [즐거운|즐겁다] 생일이었어요.","z":"昨天是我的生日。朋友們來我家。媽媽做了很多好吃的菜。朋友們帶了蛋糕和禮物來。我們唱歌也拍了照。真是愉快的生日。","q":[{"q":"음식은 누가 만들었습니까?","c":["어머니","친구들","저","아버지"],"e":"「어머니가 음식을 많이 만드셨어요」＝媽媽做了很多菜。","qt":"菜是誰做的？"},{"q":"친구들은 무엇을 가져왔습니까?","c":["케이크와 선물","음식과 꽃","사진과 선물","케이크와 꽃"],"e":"「케이크와 선물을 가져왔어요」。","qt":"朋友們帶了什麼來？"}]},{"id":"r11","lv":2,"t":"감기","tz":"感冒","k":"[어제]부터 [머리]가 [아프고|아프다] [열]이 [났어요|나다]. [기침]도 많이 했어요. 그래서 오늘 [아침]에 [병원]에 갔어요. [의사] 선생님이 [감기]라고 하셨어요. [약]을 먹고 [집]에서 [푹] [쉬었어요|쉬다]. 지금은 [조금] [괜찮아요|괜찮다].","z":"從昨天開始頭痛又發燒。也咳得很厲害。所以今天早上去了醫院。醫生說是感冒。吃了藥在家好好休息。現在好一點了。","q":[{"q":"이 사람은 오늘 아침에 어디에 갔습니까?","c":["병원","약국","학교","회사"],"e":"「오늘 아침에 병원에 갔어요」。","qt":"這個人今天早上去了哪裡？"},{"q":"이 사람은 지금 어떻습니까?","c":["조금 괜찮습니다","아주 아픕니다","학교에 있습니다","열이 많이 납니다"],"e":"「지금은 조금 괜찮아요」＝現在好一點了。","qt":"這個人現在怎麼樣？"}]},{"id":"r12","lv":2,"t":"한국어 공부","tz":"學韓語","k":"저는 [작년]부터 [한국어]를 [배웠어요|배우다]. [처음]에는 [한글]이 [어려웠어요|어렵다]. 하지만 [매일] [단어]를 외우고 [한국] [드라마]를 봤어요. 지금은 [간단한|간단하다] [대화]를 할 수 있어요. [내년]에 한국으로 [유학]을 가고 [싶어요|싶다].","z":"我從去年開始學韓語。一開始韓文字很難。但是我每天背單字、看韓劇。現在可以進行簡單的對話了。明年想去韓國留學。","q":[{"q":"이 사람은 언제부터 한국어를 배웠습니까?","c":["작년","올해","어제","내년"],"e":"「작년부터 한국어를 배웠어요」＝從去年開始學。","qt":"這個人從什麼時候開始學韓語？"},{"q":"이 사람은 내년에 무엇을 하고 싶어 합니까?","c":["한국에 유학을 가고 싶어 합니다","드라마를 만들고 싶어 합니다","한글을 가르치고 싶어 합니다","일본에 가고 싶어 합니다"],"e":"「내년에 한국으로 유학을 가고 싶어요」。","qt":"這個人明年想做什麼？"}]},{"id":"r13","lv":2,"t":"학교 앞 식당","tz":"學校前面的餐廳","k":"학교 [근처]에 [작은|작다] [식당]이 있어요. 이 식당은 [비빔밥]이 [유명해요|유명하다]. [값]도 [싸서|싸다] [학생]들이 많이 와요. 저는 [일주일]에 두 [번] 이 식당에 가요. 오늘도 [친구]와 [같이] [점심]을 먹었어요.","z":"學校附近有一家小餐廳。這家餐廳的拌飯很有名。價格也便宜，所以很多學生來。我一週去這家餐廳兩次。今天也和朋友一起吃了午餐。","q":[{"q":"이 식당은 무엇이 유명합니까?","c":["비빔밥","불고기","냉면","김밥"],"e":"「비빔밥이 유명해요」。","qt":"這家餐廳什麼很有名？"},{"q":"이 사람은 이 식당에 얼마나 자주 갑니까?","c":["일주일에 두 번","매일","한 달에 한 번","일주일에 한 번"],"e":"「일주일에 두 번」＝一週兩次。","qt":"這個人多常去這家餐廳？"}]},{"id":"r14","lv":2,"t":"우리 동네","tz":"我們社區","k":"우리 [동네]는 [조용하고|조용하다] [깨끗해요|깨끗하다]. 집 [앞]에 [큰|크다] [공원]이 있어요. 공원 [옆]에는 [도서관]과 [우체국]이 있어요. [지하철역]도 [가까워서|가깝다] [편해요|편하다]. 저는 우리 동네가 [정말] [좋아요|좋다].","z":"我們社區安靜又乾淨。家門前有一座大公園。公園旁邊有圖書館和郵局。地鐵站也很近，很方便。我真的很喜歡我們社區。","q":[{"q":"공원 옆에 무엇이 있습니까?","c":["도서관과 우체국","은행과 병원","학교와 시장","식당과 카페"],"e":"「공원 옆에는 도서관과 우체국이 있어요」。","qt":"公園旁邊有什麼？"},{"q":"이 동네에 대한 내용과 같은 것은?","c":["지하철역이 가깝습니다","동네가 시끄럽습니다","공원이 작습니다","교통이 불편합니다"],"e":"「지하철역도 가까워서 편해요」＝地鐵站也很近。","qt":"關於這個社區，哪一項正確？"}]},{"id":"r15","lv":2,"t":"옷을 샀어요","tz":"買了衣服","k":"[내일]은 [친구] [결혼식]이에요. 그래서 오늘 [백화점]에 [옷]을 사러 갔어요. [파란색] [원피스]가 [예뻤지만|예쁘다] 너무 [비쌌어요|비싸다]. 그래서 [하얀색] [블라우스]와 [치마]를 [샀어요|사다]. [구두]는 [집]에 있어서 사지 [않았어요|않다].","z":"明天是朋友的婚禮。所以今天去百貨公司買衣服。藍色的連身洋裝很漂亮，但是太貴了。所以買了白色的女用襯衫和裙子。家裡有皮鞋，所以沒有買。","q":[{"q":"이 사람은 무엇을 샀습니까?","c":["블라우스와 치마","원피스","구두","원피스와 구두"],"e":"「하얀색 블라우스와 치마를 샀어요」。","qt":"這個人買了什麼？"},{"q":"왜 원피스를 사지 않았습니까?","c":["너무 비싸서","색깔이 싫어서","사이즈가 작아서","집에 있어서"],"e":"「원피스가 예뻤지만 너무 비쌌어요」＝太貴了；家裡有的是皮鞋。","qt":"為什麼沒有買連身洋裝？"}]},{"id":"r16","lv":2,"t":"처음 탄 스키","tz":"第一次滑雪","k":"[겨울방학]에 [가족]과 [스키장]에 갔어요. 저는 [스키]를 [처음] [탔어요|타다]. 처음에는 [무서워서|무섭다] 많이 [넘어졌어요|넘어지다]. 하지만 [아버지]가 [친절하게|친절하다] [가르쳐|가르치다] 주셨어요. [마지막] [날]에는 [혼자] 탈 수 있었어요.","z":"寒假和家人去了滑雪場。我第一次滑雪。一開始很害怕，跌倒了很多次。但是爸爸很親切地教我。最後一天可以自己滑了。","q":[{"q":"누가 스키를 가르쳐 주었습니까?","c":["아버지","어머니","친구","선생님"],"e":"「아버지가 친절하게 가르쳐 주셨어요」。","qt":"誰教他滑雪？"},{"q":"이 글의 내용과 같은 것은?","c":["처음에 많이 넘어졌습니다","스키를 자주 탔습니다","혼자 스키장에 갔습니다","마지막 날에도 못 탔습니다"],"e":"第一次滑雪、和家人去、最後一天會滑了，只有「一開始跌倒很多次」正確。","qt":"下列哪一項和內容相同？"}]},{"id":"r17","lv":3,"t":"회사원의 하루","tz":"上班族的一天","k":"저는 [회사원]이에요. [아침] [여덟] [시]에 [지하철]을 [타고|타다] [회사]에 가요. [오전]에는 [회의]가 많아서 [바빠요|바쁘다]. [점심]은 회사 [근처] [식당]에서 먹어요. [오후]에는 [컴퓨터]로 일을 해요. [여섯] 시에 [퇴근해요|퇴근하다]. [저녁]에는 [집]에서 [요리]를 하고 [텔레비전]을 봐요. [피곤하지만|피곤하다] [행복해요|행복하다].","z":"我是上班族。早上八點搭地鐵去公司。上午會議很多，很忙。午餐在公司附近的餐廳吃。下午用電腦工作。六點下班。晚上在家做菜、看電視。雖然累，但是很幸福。","q":[{"q":"이 사람은 오전에 왜 바쁩니까?","c":["회의가 많아서","일찍 일어나서","지하철이 늦어서","점심을 안 먹어서"],"e":"「오전에는 회의가 많아서 바빠요」。","qt":"這個人上午為什麼很忙？"},{"q":"이 사람은 저녁에 무엇을 합니까?","c":["요리를 하고 텔레비전을 봅니다","회사에서 일합니다","친구를 만납니다","운동을 합니다"],"e":"「저녁에는 집에서 요리를 하고 텔레비전을 봐요」。","qt":"這個人晚上做什麼？"}]},{"id":"r18","lv":3,"t":"제주도 여행","tz":"濟州島旅行","k":"[지난달]에 [친구]와 [제주도]로 [여행]을 갔어요. [비행기]로 한 [시간][쯤] [걸렸어요|걸리다]. [첫째] 날에는 [바다]에서 [수영]을 했어요. [둘째] 날에는 [산]에 [올라갔어요|올라가다]. [날씨]가 [좋아서|좋다] [경치]가 아주 [아름다웠어요|아름답다]. [저녁]에는 [생선] [요리]를 먹었어요. [다음]에는 [부모님]과 같이 오고 [싶어요|싶다].","z":"上個月和朋友去濟州島旅行。搭飛機大約花了一個小時。第一天在海邊游泳。第二天去爬山。天氣很好，所以風景非常美。晚上吃了魚料理。下次想和爸媽一起來。","q":[{"q":"둘째 날에는 무엇을 했습니까?","c":["산에 올라갔습니다","바다에서 수영했습니다","생선 요리를 만들었습니다","비행기를 탔습니다"],"e":"「둘째 날에는 산에 올라갔어요」；游泳是第一天。","qt":"第二天做了什麼？"},{"q":"이 사람은 다음에 누구와 오고 싶어 합니까?","c":["부모님","친구","동생","선생님"],"e":"「다음에는 부모님과 같이 오고 싶어요」。","qt":"這個人下次想和誰來？"}]},{"id":"r19","lv":3,"t":"이사","tz":"搬家","k":"저는 [다음] [주]에 [이사]를 해요. 지금 사는 [집]은 [학교]에서 [멀어서|멀다] [불편해요|불편하다]. [버스]로 한 [시간]이 [걸려요|걸리다]. 새 집은 학교 [근처]에 있어서 [걸어서|걷다] 십 [분]이면 가요. 방은 [조금] [좁지만|좁다] [창문]이 커서 [밝아요|밝다]. [월세]는 지금보다 조금 [비싸요|비싸다]. 하지만 [시간]이 많아져서 [좋아요|좋다].","z":"我下週要搬家。現在住的房子離學校很遠，很不方便。搭公車要一個小時。新房子在學校附近，走路十分鐘就到。房間有點小，但窗戶很大，很明亮。月租比現在貴一點。但是多出很多時間，很好。","q":[{"q":"새 집에서 학교까지 어떻게 갑니까?","c":["걸어서 갑니다","버스로 갑니다","지하철로 갑니다","자전거로 갑니다"],"e":"「걸어서 십 분이면 가요」＝走路十分鐘；搭公車是現在的家。","qt":"從新家怎麼去學校？"},{"q":"새 집에 대한 내용과 같은 것은?","c":["방이 밝습니다","월세가 쌉니다","방이 넓습니다","학교에서 멉니다"],"e":"窗戶大所以很亮；月租比較貴、房間有點小、離學校近。","qt":"關於新家，哪一項正確？"}]},{"id":"r20","lv":3,"t":"학교 도서관","tz":"學校圖書館","k":"저는 [시험] [기간]에 [도서관]에서 [공부해요|공부하다]. 우리 학교 도서관은 [아침] [아홉] 시부터 [밤] [열] 시까지 [열어요|열다]. 도서관은 [조용해서|조용하다] 공부가 잘돼요. 하지만 [음식]을 먹으면 안 돼요. 그래서 배가 [고프면|고프다] 밖에 나가서 [간식]을 먹어요. [책]은 한 번에 다섯 [권]까지 [빌릴|빌리다] 수 있어요. 저는 이 도서관을 자주 [이용해요|이용하다].","z":"考試期間我在圖書館讀書。我們學校的圖書館從早上九點開到晚上十點。圖書館很安靜，讀書效率很好。但是不可以吃東西。所以肚子餓的話就到外面吃點心。書一次最多可以借五本。我常常使用這間圖書館。","q":[{"q":"도서관에서 할 수 없는 것은?","c":["음식을 먹습니다","공부합니다","책을 빌립니다","책을 읽습니다"],"e":"「음식을 먹으면 안 돼요」＝不可以吃東西。","qt":"在圖書館不能做什麼？"},{"q":"책은 몇 권까지 빌릴 수 있습니까?","c":["다섯 권","세 권","열 권","한 권"],"e":"「한 번에 다섯 권까지」＝一次最多五本。","qt":"書最多可以借幾本？"}]},{"id":"r21","lv":3,"t":"내 친구 지훈","tz":"我的朋友智勳","k":"제 [친한|친하다] [친구]는 지훈 씨예요. 우리는 [고등학교] 때 [처음] [만났어요|만나다]. 지훈 씨는 [키]가 [크고|크다] [운동]을 [잘해요|잘하다]. [성격]도 [밝아서|밝다] 친구가 많아요. 지금은 다른 [도시]에 살아서 자주 못 만나요. 그래서 [주말]마다 [전화]를 해요. [방학]에 같이 [여행]을 가기로 [약속했어요|약속하다].","z":"我的好朋友是智勳。我們是高中時第一次見面的。智勳個子高、很會運動。個性也很開朗，所以朋友很多。現在住在不同城市，不能常見面。所以每個週末打電話。約好放假一起去旅行。","q":[{"q":"두 사람은 언제 처음 만났습니까?","c":["고등학교 때","대학교 때","작년에","방학에"],"e":"「고등학교 때 처음 만났어요」。","qt":"兩個人什麼時候第一次見面？"},{"q":"이 글의 내용과 같은 것은?","c":["주말마다 전화합니다","같은 도시에 삽니다","자주 만납니다","지훈 씨는 운동을 못합니다"],"e":"住在不同城市、不能常見面，所以每週末打電話。","qt":"下列哪一項和內容相同？"}]},{"id":"r22","lv":3,"t":"한국의 계절","tz":"韓國的季節","k":"[한국]은 [사계절]이 있어요. [봄]에는 [꽃]이 많이 [피어요|피다]. [여름]은 [덥고|덥다] [비]가 많이 와요. [가을]에는 [날씨]가 [시원하고|시원하다] [하늘]이 [맑아요|맑다]. [겨울]은 아주 [추워요|춥다]. [눈]도 와요. 저는 가을을 [제일] [좋아해요|좋아하다]. [산책하기|산책] 좋아요.","z":"韓國有四季。春天開很多花。夏天很熱，雨也下得很多。秋天天氣涼爽、天空晴朗。冬天非常冷。也會下雪。我最喜歡秋天。很適合散步。","q":[{"q":"여름 날씨는 어떻습니까?","c":["덥고 비가 많이 옵니다","춥고 눈이 옵니다","시원하고 맑습니다","따뜻하고 꽃이 핍니다"],"e":"「여름은 덥고 비가 많이 와요」。","qt":"夏天天氣怎麼樣？"},{"q":"이 사람은 어느 계절을 제일 좋아합니까?","c":["가을","봄","여름","겨울"],"e":"「가을을 제일 좋아해요」。","qt":"這個人最喜歡哪個季節？"}]},{"id":"r23","lv":3,"t":"토요일 일기","tz":"星期六的日記","k":"오늘은 [토요일]이었어요. [오전]에 [늦잠]을 [잤어요|자다]. [오후]에는 [동생]과 [미술관]에 갔어요. [그림]이 많았는데 [정말] [멋있었어요|멋있다]. 미술관에서 나와서 [카페]에서 [커피]를 [마셨어요|마시다]. [저녁]에는 [집]에서 [가족]과 [불고기]를 먹었어요. [피곤했지만|피곤하다] [재미있는|재미있다] 하루였어요.","z":"今天是星期六。上午睡了懶覺。下午和弟弟（妹妹）去了美術館。畫很多，真的很棒。從美術館出來後在咖啡廳喝了咖啡。晚上在家和家人吃了烤肉。雖然很累，但是有趣的一天。","q":[{"q":"이 사람은 오후에 어디에 갔습니까?","c":["미술관","박물관","극장","시장"],"e":"「오후에는 동생과 미술관에 갔어요」。","qt":"這個人下午去了哪裡？"},{"q":"이 사람은 저녁에 무엇을 먹었습니까?","c":["불고기","커피","비빔밥","김밥"],"e":"「저녁에는 가족과 불고기를 먹었어요」；咖啡是在咖啡廳喝的。","qt":"這個人晚上吃了什麼？"}]},{"id":"r24","lv":3,"t":"내가 좋아하는 한국 음식","tz":"我喜歡的韓國食物","k":"저는 [한국] [음식]을 아주 [좋아해요|좋아하다]. [처음]에는 [김치]가 너무 [매웠어요|맵다]. 그런데 지금은 [매일] 먹어요. 제가 [제일] 좋아하는 음식은 [떡볶이]예요. [조금] [맵지만|맵다] [달고|달다] [맛있어요|맛있다]. [요즘]에는 [집]에서 한국 [요리]를 [배우고|배우다] 있어요. [다음] [달]에는 [친구]들을 [초대해서|초대하다] [불고기]를 만들어 줄 거예요.","z":"我非常喜歡韓國食物。一開始泡菜太辣了。可是現在每天都吃。我最喜歡的食物是辣炒年糕。有點辣，但是甜甜的很好吃。最近在家學做韓國料理。下個月要邀請朋友們，做烤肉給他們吃。","q":[{"q":"이 사람이 제일 좋아하는 음식은 무엇입니까?","c":["떡볶이","김치","불고기","비빔밥"],"e":"「제일 좋아하는 음식은 떡볶이예요」。","qt":"這個人最喜歡的食物是什麼？"},{"q":"다음 달에 무엇을 할 겁니까?","c":["친구들에게 불고기를 만들어 줍니다","한국에 여행을 갑니다","김치를 삽니다","요리 학원에 갑니다"],"e":"「친구들을 초대해서 불고기를 만들어 줄 거예요」。","qt":"下個月要做什麼？"}]},{"id":"r25","t":"우리 교실","tz":"我們的教室","k":"[우리] [교실]은 [삼] [층]에 [있어요|있다]. 교실 [앞]에 [큰|크다] [칠판]이 있고 [뒤]에 [책장]이 있어요. [학생]들은 [책상] [위]에 [교과서]와 [공책]을 [놓아요|놓다]. [제가] 쓰는 [필통]에는 [연필], [볼펜], [지우개]가 [들어|들다] 있어요. [수업]이 [끝나면|끝나다] [선생님]이 칠판을 [지우세요|지우다].","z":"我們的教室在三樓。教室前面有一塊大黑板，後面有書櫃。學生們把課本和筆記本放在書桌上。我用的鉛筆盒裡有鉛筆、原子筆和橡皮擦。下課後老師會把黑板擦乾淨。","q":[{"q":"교실은 몇 층에 있습니까?","c":["삼 층","이 층","사 층","일 층"],"e":"「교실은 삼 층에 있어요」＝教室在三樓。","qt":"教室在幾樓？"},{"q":"필통에 없는 것은?","c":["공책","연필","볼펜","지우개"],"e":"鉛筆盒裡有鉛筆、原子筆、橡皮擦；筆記本放在書桌上。","qt":"鉛筆盒裡沒有什麼？"}],"lv":1},{"id":"r26","t":"한국어 수업","tz":"韓語課","k":"[월요일]과 [수요일]에 [한국어] [수업]이 있어요. 수업 [시간]에 [선생님]이 [문장]을 [설명해|설명하다] 주세요. [모르는|모르다] [단어]가 있으면 [손]을 [들고|들다] [질문해요|질문하다]. 선생님은 [친절하게|친절하다] [대답해|대답하다] 주세요. [숙제]는 [매일] [조금]씩 있어요. [말하기]는 [쉽지만|쉽다] [쓰기]는 [어려워요|어렵다].","z":"星期一和星期三有韓語課。上課時老師會說明句子。有不懂的單字就舉手發問。老師會很親切地回答。每天都有一點作業。口說很容易，但是寫作很難。","q":[{"q":"수업은 무슨 요일에 있습니까?","c":["월요일과 수요일","화요일과 목요일","월요일과 금요일","매일"],"e":"「월요일과 수요일에 수업이 있어요」。","qt":"課在星期幾？"},{"q":"이 사람에게 어려운 것은?","c":["쓰기","말하기","질문하기","대답하기"],"e":"「말하기는 쉽지만 쓰기는 어려워요」＝寫作很難。","qt":"對這個人來說什麼很難？"}],"lv":2},{"id":"r27","t":"시험 공부","tz":"準備考試","k":"[다음 주|다음주] [목요일]에 [시험]이 있어요. [그래서] [요즘] [독서실]에서 [공부해요|공부하다]. [시간표]를 [만들어서|만들다] [매일] [계획]대로 공부해요. [듣기]와 [읽기]를 [열심히] [연습해요|연습하다]. [어제]는 [새벽] [한] [시]까지 공부해서 [너무] [피곤했어요|피곤하다]. 시험에서 좋은 [점수]를 [받고|받다] [싶어요|싶다].","z":"下週四有考試。所以最近在 K 書中心讀書。做了時間表，每天照計畫讀書。認真練習聽力和閱讀。昨天讀到凌晨一點，非常累。想在考試拿到好分數。","q":[{"q":"시험은 언제 있습니까?","c":["다음 주 목요일","이번 주 목요일","다음 주 화요일","내일"],"e":"「다음 주 목요일에 시험이 있어요」。","qt":"考試是什麼時候？"},{"q":"이 글의 내용과 같은 것은?","c":["계획대로 공부합니다","도서관에서 공부합니다","어제 일찍 잤습니다","쓰기를 연습합니다"],"e":"在 K 書中心讀書、讀到凌晨、練習聽力和閱讀，並照計畫讀書。","qt":"下列哪一項和內容相同？"}],"lv":2},{"id":"r28","t":"대학 생활","tz":"大學生活","k":"저는 [대학교] [이] [학년]이에요. [기숙사]에 [살아서|살다] [학교]까지 [걸어서|걷다] 오 [분]이면 가요. 이번 [학기]에는 다섯 과목 수업을 들어요. [수업]이 없는 [시간]에는 [사진] [동아리]에서 활동해요. [선배]들이 [잘] [도와줘서|도와주다] [대학] [생활]이 [재미있어요|재미있다]. [졸업]하면 [대학원]에 가고 싶어요.","z":"我是大學二年級。住在宿舍，走路五分鐘就到學校。這學期修五門課。沒課的時間在攝影社活動。學長姊們很照顧我，所以大學生活很有趣。畢業後想讀研究所。","q":[{"q":"이 사람은 몇 학년입니까?","c":["이 학년","일 학년","삼 학년","사 학년"],"e":"「대학교 이 학년이에요」。","qt":"這個人幾年級？"},{"q":"이 사람은 졸업 후에 무엇을 하고 싶어 합니까?","c":["대학원에 가고 싶어 합니다","취직하고 싶어 합니다","사진작가가 되고 싶어 합니다","여행을 가고 싶어 합니다"],"e":"「졸업하면 대학원에 가고 싶어요」。","qt":"這個人畢業後想做什麼？"}],"lv":2},{"id":"r29","t":"우리 할머니","tz":"我的奶奶","k":"[우리] [할머니]는 [시골]에 [사세요|살다]. [연세]가 [여든]이 [넘으셨지만|넘다] [아주] [건강하세요|건강하다]. 할머니 [댁]에는 [닭]과 [강아지]가 있어요. [방학]이 되면 저는 할머니 댁에 [가요|가다]. 할머니는 [맛있는|맛있다] [음식]을 [많이] [만들어|만들다] 주세요. 할머니와 [같이] 있으면 [마음]이 [편해요|편하다].","z":"我奶奶住在鄉下。雖然年紀超過八十歲了，但是非常健康。奶奶家有雞和小狗。一放假我就去奶奶家。奶奶會做很多好吃的菜給我吃。和奶奶在一起心裡很自在。","q":[{"q":"할머니는 어디에 사십니까?","c":["시골","서울","부산","우리 집"],"e":"「할머니는 시골에 사세요」。","qt":"奶奶住在哪裡？"},{"q":"할머니에 대한 내용과 같은 것은?","c":["아주 건강하십니다","여든 살이 안 되셨습니다","강아지가 없습니다","요리를 안 하십니다"],"e":"「연세가 여든이 넘으셨지만 아주 건강하세요」。","qt":"關於奶奶，哪一項正確？"}],"lv":2},{"id":"r30","t":"설날","tz":"春節","k":"[설날]에는 [친척]들이 [할아버지] [댁]에 [모여요|모이다]. [아침]에 [한복]을 [입고|입다] [어른]들께 [절]을 해요. 그리고 [가족]이 [함께] [떡국]을 먹어요. [떡국]을 먹으면 [한] [살]을 더 먹는다고 해요. [오후]에는 [사촌]들과 윷놀이를 하고 [놀아요|놀다]. [작은아버지]와 [큰아버지]도 [오셔서|오다] [집]이 아주 [시끄러워요|시끄럽다].","z":"春節時親戚們會聚到爺爺家。早上穿上韓服向長輩行禮。然後全家一起吃年糕湯。據說吃了年糕湯就長一歲。下午和堂兄弟姊妹們玩擲柶遊戲。叔叔和伯父也會來，所以家裡非常熱鬧。","q":[{"q":"설날 아침에 무엇을 합니까?","c":["한복을 입고 절을 합니다","떡을 만듭니다","여행을 갑니다","윷놀이를 합니다"],"e":"早上穿韓服向長輩行禮；擲柶是下午。","qt":"春節早上做什麼？"},{"q":"설날에 먹는 음식은?","c":["떡국","냉면","삼계탕","김밥"],"e":"「가족이 함께 떡국을 먹어요」。","qt":"春節吃什麼？"}],"lv":2},{"id":"r31","t":"추석","tz":"中秋節","k":"[추석]은 한국의 큰 [명절]이에요. [추석] [연휴]에는 [사람]들이 [고향]에 가서 [부모님]을 [만나요|만나다]. 그래서 [고속버스]와 [기차]가 [아주] [복잡해요|복잡하다]. [길]도 [많이] [막혀요|막히다]. [고향]에 가면 [가족]들과 송편을 만들고 [밤]에는 [달]을 봐요. 저는 [올해] [처음]으로 한국 [친구] [집]에서 [추석]을 [보냈어요|보내다].","z":"中秋節是韓國的重要節日。中秋連假時人們會回故鄉見父母。所以客運和火車都非常擁擠。路上也很塞。回到故鄉就和家人一起做松餅，晚上賞月。我今年第一次在韓國朋友家過中秋節。","q":[{"q":"추석 연휴에 사람들은 무엇을 합니까?","c":["고향에 가서 부모님을 만납니다","해외여행을 갑니다","회사에 갑니다","이사를 합니다"],"e":"「고향에 가서 부모님을 만나요」。","qt":"中秋連假人們做什麼？"},{"q":"이 사람은 올해 추석을 어디에서 보냈습니까?","c":["한국 친구 집","고향","기숙사","호텔"],"e":"「한국 친구 집에서 추석을 보냈어요」。","qt":"這個人今年在哪裡過中秋節？"}],"lv":2},{"id":"r32","t":"우리 이모","tz":"我的阿姨","k":"[어머니]의 [여동생]은 제 [이모]예요. [이모]는 [은행원]이고 [이모부]는 [의사]세요. 두 [분]은 [결혼]한 지 [십] [년]이 됐어요. [아들] 하나와 [딸] 하나가 있어요. [외삼촌]과 [외숙모]는 [부산]에 사셔서 [자주] 못 [만나요|만나다]. 하지만 [외할머니] [생신]에는 [모두] [모여요|모이다].","z":"媽媽的妹妹是我的阿姨。阿姨是銀行行員，姨丈是醫生。兩位結婚十年了。有一個兒子和一個女兒。舅舅和舅媽住在釜山，所以不常見面。但是外婆生日時大家都會聚在一起。","q":[{"q":"이모부의 직업은 무엇입니까?","c":["의사","은행원","선생님","회사원"],"e":"「이모부는 의사세요」；銀行行員是阿姨。","qt":"姨丈的職業是什麼？"},{"q":"가족이 모두 모이는 날은?","c":["외할머니 생신","설날","추석","이모 결혼식"],"e":"「외할머니 생신에는 모두 모여요」。","qt":"家人全部聚在一起的日子是？"}],"lv":2},{"id":"r33","t":"우리 오빠","tz":"我的哥哥","k":"저는 [오빠]가 한 [명] 있어요. [오빠]는 [서른] [살]이고 [자동차] [회사]에 [다녀요|다니다]. [키]가 [크고|크다] [잘생겼어요|잘생기다]. [오빠]는 [어렸을|어리다] 때 [저]와 [자주] [싸웠어요|싸우다]. 하지만 지금은 [사이]가 [아주] [좋아요|좋다]. [주말]에는 [같이] [운동]을 하거나 [영화]를 봐요.","z":"我有一個哥哥。哥哥三十歲，在汽車公司上班。個子高又帥。哥哥小時候常常和我吵架。但是現在感情非常好。週末會一起運動或看電影。","q":[{"q":"오빠는 어디에서 일합니까?","c":["자동차 회사","은행","학교","병원"],"e":"「자동차 회사에 다녀요」。","qt":"哥哥在哪裡工作？"},{"q":"이 글의 내용과 같은 것은?","c":["지금은 오빠와 사이가 좋습니다","지금도 자주 싸웁니다","오빠는 키가 작습니다","주말에는 만나지 않습니다"],"e":"「지금은 사이가 아주 좋아요」。","qt":"下列哪一項和內容相同？"}],"lv":2},{"id":"r34","t":"우리 아기","tz":"我們家的寶寶","k":"우리 [집]에 [아기]가 [태어났어요|태어나다]. [언니]의 [아들]이에요. 저는 [이모]가 됐어요. [아기]는 [눈]이 [크고|크다] [귀여워요|귀엽다]. [밤]에 [자주] [울어서|울다] [언니]와 형부가 [잠]을 잘 못 자요. 그래도 [아기]가 [웃으면|웃다] [모두] [행복해요|행복하다].","z":"我們家有寶寶出生了。是姊姊的兒子。我當阿姨了。寶寶眼睛大大的很可愛。晚上常常哭，所以姊姊和姊夫都睡不好。即使這樣，寶寶一笑大家都很幸福。","q":[{"q":"아기는 누구의 아들입니까?","c":["언니","이모","오빠","어머니"],"e":"「언니의 아들이에요」。","qt":"寶寶是誰的兒子？"},{"q":"언니가 잠을 잘 못 자는 이유는?","c":["아기가 밤에 자주 울어서","일이 많아서","집이 시끄러워서","아파서"],"e":"「밤에 자주 울어서 잠을 잘 못 자요」。","qt":"姊姊為什麼睡不好？"}],"lv":2},{"id":"r35","t":"부모님께 쓴 편지","tz":"寫給父母的信","k":"[아버님], [어머님], [안녕하세요]? 저는 [서울]에서 [잘] [지내고|지내다] 있어요. [처음]에는 [외로웠지만|외롭다] 지금은 [친구]도 [많이] [생겼어요|생기다]. [한국] [음식]도 [잘] 먹고 [건강해요|건강하다]. [걱정하지|걱정하다] [마세요|말다]. [방학]에 [집]에 [돌아가면|돌아가다] [선물]을 [드릴게요|드리다]. [보고|보다] 싶어요.","z":"爸爸、媽媽，你們好嗎？我在首爾過得很好。一開始很寂寞，但是現在也交了很多朋友。韓國食物也吃得很好，很健康。請不要擔心。放假回家的時候會送你們禮物。好想你們。","q":[{"q":"이 사람은 지금 어떻게 지냅니까?","c":["잘 지냅니다","아직 외롭습니다","아픕니다","친구가 없습니다"],"e":"「서울에서 잘 지내고 있어요」，現在也交了很多朋友。","qt":"這個人現在過得怎麼樣？"},{"q":"방학에 무엇을 할 겁니까?","c":["집에 돌아가서 선물을 드립니다","한국 여행을 합니다","부모님을 초대합니다","한국 음식을 만듭니다"],"e":"「방학에 집에 돌아가면 선물을 드릴게요」。","qt":"放假時要做什麼？"}],"lv":3},{"id":"r36","t":"새 친구","tz":"新朋友","k":"[지난주]에 [학교]에서 [새] [친구]를 사귀었어요. [이름]은 마리아예요. 마리아 [씨]는 [멕시코] [사람]이고 [스페인어]를 [잘해요|잘하다]. 우리는 [서로] 언어를 [가르쳐|가르치다] 주기로 했어요. 저는 [한국어]를 가르쳐 주고 마리아 씨는 [스페인어]를 가르쳐 줘요. [다음]에는 [같이] [멕시코] [음식]을 [만들기로|만들다] 했어요.","z":"上週在學校交了新朋友。她叫瑪莉亞。瑪莉亞是墨西哥人，西班牙語很好。我們決定互相教對方語言。我教她韓語，瑪莉亞教我西班牙語。我們約好下次一起做墨西哥菜。","q":[{"q":"마리아 씨는 어느 나라 사람입니까?","c":["멕시코","스페인","브라질","미국"],"e":"「마리아 씨는 멕시코 사람이고」。","qt":"瑪莉亞是哪國人？"},{"q":"두 사람은 무엇을 하기로 했습니까?","c":["서로 언어를 가르쳐 줍니다","같이 여행을 갑니다","같이 살기로 했습니다","한국 음식을 만듭니다"],"e":"「서로 언어를 가르쳐 주기로 했어요」；下次要做的是墨西哥菜。","qt":"兩個人決定做什麼？"}],"lv":2},{"id":"r95","t":"전화","tz":"打電話","k":"\"[여보세요]? [거기] 민수 씨 [댁]이지요?\" \"[네], 그런데요. [누구]세요?\" \"저는 민수 씨 [친구] 지영이에요. 민수 씨 [계세요|계시다]?\" \"[아니요], 지금 [외출했어요|외출하다]. [이따가] [다시] [전화해|전화하다] 주시겠어요?\" \"[그럼] [메시지]를 [전해|전하다] 주세요. [내일] [약속] [장소]가 [바뀌었다고|바뀌다] [알려|알리다] 주세요.\" \"[네], [알았습니다].\"","z":"「喂？那裡是民秀家吧？」「是的，有什麼事？請問是哪位？」「我是民秀的朋友智英。民秀在嗎？」「不在，他現在出門了。可以等一下再打來嗎？」「那麼請幫我轉達訊息。請告訴他明天約定的地點換了。」「好，知道了。」","q":[{"q":"민수 씨는 지금 어디에 있습니까?","c":["외출했습니다","집에 있습니다","회사에 있습니다","학교에 있습니다"],"e":"「지금 외출했어요」。","qt":"民秀現在在哪裡？"},{"q":"지영 씨가 전하고 싶은 말은?","c":["약속 장소가 바뀌었습니다","약속 시간이 바뀌었습니다","약속을 취소합니다","전화해 주세요"],"e":"「내일 약속 장소가 바뀌었다고 알려 주세요」。","qt":"智英想轉達的話是？"}],"lv":1},{"id":"r96","t":"감사 인사","tz":"道謝","k":"[지난번]에 [제가] [아팠을|아프다] 때 [선배]님이 [많이] [도와주셨어요|도와주다]. [약]도 사다 주시고 [죽]도 [만들어|만들다] 주셨어요. [정말] [감사드립니다]. 선배님 [덕분]에 [빨리] 나았어요. [그동안] [고마웠습니다]. [다음]에는 제가 [맛있는|맛있다] [음식]을 대접할게요. 선배님이 [좋아하시는|좋아하다] [한식]으로 [준비하겠습니다|준비하다].","z":"上次我生病的時候學長幫了我很多。幫我買了藥，還煮了粥給我。真的非常感謝您。託學長的福，我很快就好了。這段時間謝謝您了。下次我請您吃好吃的東西。會準備學長喜歡的韓式料理。","q":[{"q":"선배는 무엇을 해 주었습니까?","c":["약을 사 주고 죽을 만들어 주었습니다","병원에 데려가 주었습니다","한식을 사 주었습니다","숙제를 해 주었습니다"],"e":"「약도 사다 주시고 죽도 만들어 주셨어요」。","qt":"學長為他做了什麼？"},{"q":"이 사람은 다음에 무엇을 할 겁니까?","c":["선배에게 음식을 대접합니다","선배와 병원에 갑니다","선배에게 약을 삽니다","선배와 여행을 갑니다"],"e":"「다음에는 제가 맛있는 음식을 대접할게요」。","qt":"這個人下次要做什麼？"}],"lv":3},{"id":"r97","t":"사과하기","tz":"道歉","k":"\"[선생님], [죄송합니다|죄송하다]. [늦었어요|늦다].\" \"[왜] 늦었어요?\" \"[버스]가 [안] 와서 [정류장]에서 [오래] [기다렸어요|기다리다]. [그리고] [길]도 [많이] [밀렸어요|밀리다].\" \"[괜찮습니다]. [하지만] [다음]에는 [조금] [일찍] [출발하세요|출발하다].\" \"[네], [미안합니다]. [앞]으로 [지각]하지 [않을게요|않다].\"","z":"「老師，對不起，我遲到了。」「為什麼遲到？」「公車一直不來，在公車站等了很久。而且路上也很塞。」「沒關係。不過下次請早一點出發。」「好的，對不起。以後不會再遲到了。」","q":[{"q":"이 사람이 늦은 이유는?","c":["버스가 안 오고 길이 밀려서","늦잠을 자서","아파서","길을 잃어버려서"],"e":"「버스가 안 와서 정류장에서 오래 기다렸어요. 그리고 길도 많이 밀렸어요」。","qt":"這個人遲到的原因是？"},{"q":"선생님은 무엇이라고 했습니까?","c":["다음에는 일찍 출발하세요","다시는 오지 마세요","버스를 타지 마세요","괜찮지 않습니다"],"e":"「다음에는 조금 일찍 출발하세요」。","qt":"老師說了什麼？"}],"lv":1},{"id":"r98","t":"축하해요","tz":"恭喜你","k":"[오늘]은 제 [친구] 수진 씨가 [대학교]에 합격한 날이에요. 수진 씨는 일 년 [동안] [열심히] [공부했어요|공부하다]. [합격] [소식]을 [듣고|듣다] [모두] [깜짝] [놀랐어요|놀라다]. [친구]들이 [모여서|모이다] [축하] [파티]를 했어요. \"[합격] [축하합니다]!\" [우리]는 [케이크]에 [초]를 [켜고|켜다] [노래]를 불렀어요. 수진 씨는 [행복]한 [얼굴]로 [웃었어요|웃다].","z":"今天是我朋友秀真考上大學的日子。秀真一整年都很認真讀書。聽到合格的消息，大家都嚇了一跳。朋友們聚在一起辦了慶祝派對。「恭喜考上！」我們在蛋糕上點了蠟燭，唱了歌。秀真帶著幸福的表情笑了。","q":[{"q":"오늘은 무슨 날입니까?","c":["친구가 대학교에 합격한 날","친구 생일","졸업식","결혼식"],"e":"「대학교에 합격한 날이에요」。","qt":"今天是什麼日子？"},{"q":"친구들은 무엇을 했습니까?","c":["축하 파티를 했습니다","같이 공부했습니다","여행을 갔습니다","선물을 샀습니다"],"e":"「친구들이 모여서 축하 파티를 했어요」。","qt":"朋友們做了什麼？"}],"lv":2},{"id":"r99","t":"무엇을 할까요?","tz":"要做什麼呢？","k":"\"[이번] [주말]에 [뭐] 할까요?\" \"[글쎄요]. [어떤] 걸 하고 [싶어요|싶다]?\" \"[날씨]가 좋으면 [한강]에 가서 [자전거]를 타면 어때요?\" \"[좋아요|좋다]. [그런데] [일기예보]를 보니까 [토요일]에 [비]가 [올|오다] 수도 있대요.\" \"[그러면] [일요일]에 가요. [몇] 시에 만날까요?\" \"[오후] [두] 시 [어때요|어떻다]?\" \"[네], [좋아요|좋다].\"","z":"「這個週末要做什麼呢？」「這個嘛。你想做什麼樣的事？」「天氣好的話去漢江騎腳踏車怎麼樣？」「好啊。不過看天氣預報說星期六可能會下雨。」「那麼星期天去吧。幾點見面？」「下午兩點怎麼樣？」「好，可以。」","q":[{"q":"두 사람은 언제 만납니까?","c":["일요일 오후 두 시","토요일 오후 두 시","일요일 오전","토요일 저녁"],"e":"「일요일에 가요」「오후 두 시 어때요?」「네, 좋아요」。","qt":"兩個人什麼時候見面？"},{"q":"토요일에 가지 않는 이유는?","c":["비가 올 수도 있어서","시간이 없어서","자전거가 없어서","한강이 멀어서"],"e":"「토요일에 비가 올 수도 있대요」。","qt":"不在星期六去的原因是？"}],"lv":1},{"id":"r100","t":"우산을 잃어버렸어요","tz":"弄丟了雨傘","k":"[아까] [지하철]에서 [우산]을 [잃어버렸어요|잃어버리다]. [노란색] [우산]인데 [자리] [옆]에 [두고|두다] [내렸어요|내리다]. [역] [직원]에게 [물어봤지만|물어보다] [아직] 없대요. [연락처]를 [적어|적다] 주고 [나왔어요|나오다]. [밖]에는 [비]가 [계속] [와서|오다] 편의점에서 [새로] 샀어요. [다음]부터는 [물건]을 [잃어버리지|잃어버리다] 않게 [조심해야겠어요|조심하다].","z":"剛才在地鐵上弄丟了雨傘。是一把黃色的雨傘，放在座位旁邊就下車了。問了車站職員，說還沒有找到。留下聯絡方式就出來了。外面雨一直下，所以在便利商店重新買了一把。以後要小心不要再弄丟東西。","q":[{"q":"우산은 어디에서 잃어버렸습니까?","c":["지하철","버스","역","편의점"],"e":"「지하철에서 우산을 잃어버렸어요」。","qt":"雨傘在哪裡弄丟的？"},{"q":"이 사람은 역 직원에게 무엇을 주었습니까?","c":["연락처","우산","돈","사진"],"e":"「연락처를 적어 주고 나왔어요」。","qt":"這個人給了車站職員什麼？"}],"lv":2},{"id":"r101","t":"왜 한국어를 배워요?","tz":"為什麼學韓語？","k":"[사람]들이 저에게 \"[왜] 한국어를 배워요?\" 하고 [자주] [물어요|묻다]. [처음]에는 [한국드라마]가 [재미있어서|재미있다] 시작했어요. [그런데] [공부]를 하면서 한국 [문화]와 [역사]에도 [관심]이 [생겼어요|생기다]. [지금]은 [한국] [회사]에서 [일하는|일하다] 것이 [목적]이에요. [왜냐하면] 한국 [회사]가 [세계]에서 [유명하기|유명하다] 때문이에요. [그래서] [매일] [조금]씩 [열심히] [공부해요|공부하다].","z":"人們常問我：「你為什麼學韓語？」一開始是因為韓劇很好看才開始的。可是在學習的過程中，也對韓國文化和歷史產生了興趣。現在的目標是在韓國公司工作。因為韓國公司在世界上很有名。所以每天一點一點認真學習。","q":[{"q":"이 사람이 처음에 한국어를 시작한 이유는?","c":["한국드라마가 재미있어서","한국 회사에서 일하고 싶어서","한국 역사를 좋아해서","한국 친구가 있어서"],"e":"「처음에는 한국드라마가 재미있어서 시작했어요」。","qt":"這個人一開始學韓語的原因是？"},{"q":"지금 이 사람의 목적은?","c":["한국 회사에서 일하기","드라마 보기","역사 공부","한국 여행"],"e":"「지금은 한국 회사에서 일하는 것이 목적이에요」。","qt":"這個人現在的目標是？"}],"lv":2},{"id":"r102","t":"경주 여행","tz":"慶州之旅","k":"지난 [공휴일]에 [가족]과 [경주]로 관광을 갔어요. [경주]는 [옛날] 신라의 [수도]였어요. [그래서] 오래된 [절]과 [건물]이 [많아요|많다]. [우리]는 [자전거]를 [빌려서|빌리다] [여기저기] [구경했어요|구경하다]. [공기]가 [맑고|맑다] [하늘]에 [구름]도 [거의] [없었어요|없다]. [서울]의 [경복궁]도 [좋지만|좋다] [경주]는 [분위기]가 [달라요|다르다]. [정말] [좋은|좋다] [경험]이었어요.","z":"上一個國定假日和家人去慶州觀光。慶州以前是新羅的首都。所以有很多古老的寺廟和建築。我們租了腳踏車到處參觀。空氣清新，天上也幾乎沒有雲。首爾的景福宮也很好，但慶州的氣氛不一樣。真是很好的經驗。","q":[{"q":"경주에 절과 건물이 많은 이유는?","c":["옛날 수도였기 때문에","관광객이 많아서","새로 지어서","서울과 가까워서"],"e":"「옛날 신라의 수도였어요. 그래서 오래된 절과 건물이 많아요」。","qt":"慶州寺廟和建築很多的原因是？"},{"q":"이 사람들은 무엇을 타고 구경했습니까?","c":["자전거","버스","택시","자동차"],"e":"「자전거를 빌려서 여기저기 구경했어요」。","qt":"這些人騎什麼參觀？"}],"lv":3},{"id":"r103","t":"고양이를 기르고 싶어요","tz":"想養貓","k":"저는 [오래]전부터 [고양이]를 [기르고|기르다] [싶었어요|싶다]. [고양이]는 [작고|작다] [가볍고|가볍다] [귀여워요|귀엽다]. [고모]와 [고모부] [댁]에도 [까만색] [고양이]가 [있어요|있다]. [눈]은 [노랗고|노랗다] 털은 [까매요|까맣다]. [하지만] [우리] [집]은 [공간]이 [좁아서|좁다] [아직] [결정]을 못 했어요. [그리고] [동물]을 [기르려면|기르다] [책임]이 [필요해요|필요하다]. [부모님]과 [다시] [이야기해|이야기하다] 볼 거예요.","z":"我很久以前就想養貓。貓小小的、輕輕的，很可愛。姑姑和姑丈家也有一隻黑貓。眼睛是黃色的，毛是黑色的。但是我們家空間很小，所以還沒有決定。而且養動物需要責任感。我會再和父母談談看。","q":[{"q":"고모 댁 고양이는 어떤 색입니까?","c":["까만색","하얀색","노란색","갈색"],"e":"「까만색 고양이가 있어요」，眼睛是黃色的。","qt":"姑姑家的貓是什麼顏色？"},{"q":"아직 결정하지 못한 이유는?","c":["집이 좁아서","고양이가 비싸서","부모님이 싫어해서","고양이가 무서워서"],"e":"「우리 집은 공간이 좁아서 아직 결정을 못 했어요」。","qt":"還沒決定的原因是？"}],"lv":3},{"id":"r104","t":"꿈 이야기","tz":"夢的故事","k":"[어젯밤]에 [이상한|이상하다] [꿈]을 [꿨어요|꾸다]. [꿈]에서 저는 [새]처럼 [하늘]을 [날았어요|날다]. [높은|높다] [빌딩] [위]를 [지나서|지나다] [바다]까지 갔어요. [그때] [갑자기] [큰|크다] [호랑이]가 [나타났어요|나타나다]. 저는 [깜짝] [놀라서|놀라다] [잠]에서 [깼어요|깨다]. [시계]를 보니까 [새벽] [네] 시였어요. [다시] [잠]을 [자려고|자다] 했지만 [잘] 안 됐어요.","z":"昨晚做了一個奇怪的夢。夢裡我像鳥一樣在天空飛。飛過高樓大廈，一直飛到大海。那時突然出現了一隻大老虎。我嚇了一跳，從夢中醒了過來。看了時鐘，是凌晨四點。想要再睡，但怎麼也睡不著。","q":[{"q":"꿈에서 무엇이 나타났습니까?","c":["호랑이","새","고양이","강아지"],"e":"「갑자기 큰 호랑이가 나타났어요」。","qt":"夢中出現了什麼？"},{"q":"이 사람은 몇 시에 깼습니까?","c":["새벽 네 시","새벽 두 시","아침 여섯 시","밤 열두 시"],"e":"「새벽 네 시였어요」。","qt":"這個人幾點醒來？"}],"lv":3},{"id":"r105","t":"낚시","tz":"釣魚","k":"[삼촌]은 [낚시]를 [아주] [좋아하세요|좋아하다]. [주말]마다 [강]이나 [바다]에 가서 [낚시]를 [하세요|하다]. [그저께] 저도 [처음]으로 [삼촌]을 [따라갔어요|따라가다]. [아침] [일찍] [출발해서|출발하다] [나흘] [동안] [강] [근처]에서 [지냈어요|지내다]. [처음]에는 물고기를 [한] [마리]도 [못] [잡았어요|잡다]. [그렇지만] [마지막] [날]에 [큰|크다] 물고기를 [잡아서|잡다] [정말] [기뻤어요|기쁘다].","z":"叔叔非常喜歡釣魚。每個週末都去河邊或海邊釣魚。前天我也第一次跟著叔叔去了。一大早出發，在河邊待了四天。一開始連一條魚都沒釣到。但是最後一天釣到一條大魚，真的很開心。","q":[{"q":"이 사람은 며칠 동안 강 근처에서 지냈습니까?","c":["나흘","이틀","사흘","일주일"],"e":"「나흘 동안 강 근처에서 지냈어요」。","qt":"這個人在河邊待了幾天？"},{"q":"이 글의 내용과 같은 것은?","c":["마지막 날에 큰 물고기를 잡았습니다","처음부터 많이 잡았습니다","삼촌은 낚시를 싫어합니다","바다에 갔습니다"],"e":"「마지막 날에 큰 물고기를 잡아서 정말 기뻤어요」。","qt":"下列哪一項和內容相同？"}],"lv":2},{"id":"r106","t":"눈 오는 날","tz":"下雪的日子","k":"[어제] [저녁]부터 [눈]이 [많이] [왔어요|오다]. [아침]에 [일어나니까|일어나다] [밖]이 [하얗게|하얗다] 변했어요. [기온]이 [영하] [십] 도까지 [내려가서|내려가다] [아주] [추웠어요|춥다]. [아이]들은 [공원]에서 [눈사람]을 [만들고|만들다] [눈싸움]을 했어요. 저는 [길]이 미끄러워서 [천천히] [걸어갔어요|걸어가다]. [집]에 [돌아와서|돌아오다] [따뜻한|따뜻하다] [차]를 [마셨어요|마시다].","z":"從昨天晚上開始下了很多雪。早上起床一看，外面變得白茫茫一片。氣溫降到零下十度，非常冷。孩子們在公園堆雪人、打雪仗。路很滑，所以我慢慢走過去。回到家後喝了熱茶。","q":[{"q":"기온은 몇 도까지 내려갔습니까?","c":["영하 십 도","영하 오 도","영상 십 도","영하 이십 도"],"e":"「기온이 영하 십 도까지 내려가서」。","qt":"氣溫降到幾度？"},{"q":"아이들은 무엇을 했습니까?","c":["눈사람을 만들고 눈싸움을 했습니다","스키를 탔습니다","집에서 차를 마셨습니다","학교에 갔습니다"],"e":"「아이들은 공원에서 눈사람을 만들고 눈싸움을 했어요」。","qt":"孩子們做了什麼？"}],"lv":2},{"id":"r107","t":"냄새","tz":"氣味","k":"[집]에 [들어오니까|들어오다] [부엌]에서 [좋은|좋다] [냄새]가 [났어요|나다]. [어머니]가 [갈비]를 [굽고|굽다] [계셨어요|계시다]. [식탁]에는 [김]과 [고추], [달걀] [반찬]이 [있었어요|있다]. \"[엄마], [배고파요|배고프다]!\" 하고 [말하니까|말하다] \"[손] [먼저] [씻어라|씻다].\" 하고 [말씀하셨어요|말씀하다]. [손]을 [씻고|씻다] [그릇]에 [밥]을 담았어요. [오늘] [저녁]은 [정말] [맛있었어요|맛있다].","z":"一進家門，廚房就飄來好香的味道。媽媽正在烤排骨。餐桌上有海苔、辣椒和雞蛋小菜。我說「媽，我肚子好餓！」，媽媽說「先去洗手。」洗好手後把飯盛到碗裡。今天的晚餐真的很好吃。","q":[{"q":"어머니는 무엇을 만들고 계셨습니까?","c":["갈비","김치찌개","불고기","떡국"],"e":"「어머니가 갈비를 굽고 계셨어요」。","qt":"媽媽在做什麼？"},{"q":"어머니는 무엇이라고 말씀하셨습니까?","c":["손을 먼저 씻어라","밥을 먹어라","숙제를 해라","기다려라"],"e":"「손 먼저 씻어라」。","qt":"媽媽說了什麼？"}],"lv":2},{"id":"r108","t":"우리 집 규칙","tz":"我們家的規則","k":"우리 [집]에는 [몇] [가지] [규칙]이 있어요. [첫째], [밤] [열] 시 [후]에는 [게임]을 하면 안 돼요. [둘째], [방]에서 [나갈|나가다] 때는 [불]을 [꼭] [꺼야|끄다] 해요. [셋째], [밥]을 [남기지|남기다] 말아야 해요. [넷째], [외출할|외출하다] 때는 [가족]에게 [말해야|말하다] 해요. [처음]에는 귀찮았지만 지금은 [습관]이 됐어요.","z":"我們家有幾條規則。第一，晚上十點以後不可以玩遊戲。第二，離開房間時一定要關燈。第三，不可以剩飯。第四，出門時要告訴家人。一開始覺得很麻煩，現在已經變成習慣了。","q":[{"q":"방에서 나갈 때 해야 하는 것은?","c":["불을 끕니다","문을 닫습니다","게임을 합니다","청소를 합니다"],"e":"「방에서 나갈 때는 불을 꼭 꺼야 해요」。","qt":"離開房間時要做什麼？"},{"q":"밤 열 시 후에 하면 안 되는 것은?","c":["게임","공부","샤워","독서"],"e":"「밤 열 시 후에는 게임을 하면 안 돼요」。","qt":"晚上十點後不可以做什麼？"}],"lv":2},{"id":"r109","t":"우체국에서","tz":"在郵局","k":"[고향]에 있는 [부모]님께 [소포]를 [부치러|부치다] [우체국]에 갔어요. [상자]에 [옷]과 [과자]를 [넣고|넣다] [포장]을 했어요. [직원]이 [주소]와 [전화번호]를 [쓰라고|쓰다] 했어요. [소포]는 [사흘] [후]에 [도착한대요|도착하다]. [친구]에게 보낼 [편지]도 [봉투]에 넣고 [우표]를 [붙였어요|붙이다]. [여행]지에서 산 [엽서]도 [같이] [보냈어요|보내다].","z":"去郵局寄包裹給在故鄉的父母。在箱子裡放了衣服和餅乾，包裝好了。職員叫我寫地址和電話號碼。聽說包裹三天後會送到。要寄給朋友的信也放進信封，貼上了郵票。在旅行地買的明信片也一起寄了。","q":[{"q":"소포는 언제 도착합니까?","c":["사흘 후","이틀 후","일주일 후","내일"],"e":"「소포는 사흘 후에 도착한대요」。","qt":"包裹什麼時候到？"},{"q":"상자에 넣은 것은?","c":["옷과 과자","편지와 엽서","책과 옷","과자와 사진"],"e":"「상자에 옷과 과자를 넣고」。","qt":"箱子裡放了什麼？"}],"lv":2},{"id":"r110","t":"은행에서","tz":"在銀行","k":"[한국]에 [와서|오다] [은행]에서 [통장]을 [만들었어요|만들다]. [여권]과 [학생증]이 [필요했어요|필요하다]. [신청서]에 [이름]과 [주소]를 쓰고 [사인했어요|사인하다]. [직원]이 [천천히] [설명해|설명하다] 줘서 [이해하기|이해하다] [쉬웠어요|쉽다]. [미국] [달러]와 [일본] [엔]도 한국 돈으로 [바꿀|바꾸다] 수 있어요. [통장]을 [만든|만들다] [후]에 [카드]도 [받았어요|받다].","z":"來韓國後在銀行開了存摺。需要護照和學生證。在申請書上寫了名字和地址並簽名。職員慢慢說明，所以很容易理解。美元和日圓也可以換成韓幣。開完存摺後也拿到了卡片。","q":[{"q":"통장을 만들 때 필요했던 것은?","c":["여권과 학생증","사진과 돈","카드와 여권","주소와 사진"],"e":"「여권과 학생증이 필요했어요」。","qt":"開存摺時需要什麼？"},{"q":"이해하기 쉬웠던 이유는?","c":["직원이 천천히 설명해 줘서","친구가 도와줘서","영어로 설명해서","신청서가 간단해서"],"e":"「직원이 천천히 설명해 줘서 이해하기 쉬웠어요」。","qt":"容易理解的原因是？"}],"lv":2},{"id":"r111","t":"여행 준비","tz":"旅行準備","k":"[다음 달|다음달]에 [도쿄]로 [여행]을 가요. [여행사]에서 [비행기] [표]와 [호텔]을 [예약]했어요. [가방]에 [가져갈|가져가다] [물건]을 [준비]하고 있어요. [여권], [지갑], [휴대전화]는 [꼭] [필요해요|필요하다]. [옷]은 [짧은|짧다] [반바지]와 [티셔츠], [수영복]을 넣었어요. [날씨]가 [어떨지|어떻다] 몰라서 [우산]도 넣었어요. [빨리] [출발하고|출발하다] [싶어요|싶다].","z":"下個月要去東京旅行。在旅行社訂了機票和飯店。正在準備要帶去的東西放進包包。護照、錢包、手機一定要帶。衣服放了短褲、T恤和泳衣。不知道天氣會怎麼樣，所以也放了雨傘。好想快點出發。","q":[{"q":"비행기 표는 어디에서 예약했습니까?","c":["여행사","인터넷","공항","호텔"],"e":"「여행사에서 비행기 표와 호텔을 예약했어요」。","qt":"機票在哪裡預訂的？"},{"q":"우산을 넣은 이유는?","c":["날씨를 몰라서","비가 와서","햇빛이 강해서","선물하려고"],"e":"「날씨가 어떨지 몰라서 우산도 넣었어요」。","qt":"放雨傘的原因是？"}],"lv":3},{"id":"r112","t":"호텔","tz":"飯店","k":"[호텔]에 [도착해서|도착하다] 안내 데스크에서 [이름]을 [말했어요|말하다]. [직원]이 \"[환영합니다|환영하다].\" 하고 [인사했어요|인사하다]. [방]은 [칠] [층]이었고 [창문]으로 [바다]가 [보였어요|보이다]. [방]에는 [침대], [테이블], [에어컨]이 있었어요. [화장실]에는 [수건], [비누], [샴푸]가 [준비]되어 있었어요. [아침식사]는 [일] [층] [식당]에서 [먹을|먹다] 수 있었어요.","z":"抵達飯店後在服務台報上名字。職員說「歡迎光臨」跟我打招呼。房間在七樓，從窗戶可以看到大海。房間裡有床、桌子和冷氣。廁所裡準備了毛巾、肥皂和洗髮精。早餐可以在一樓餐廳吃。","q":[{"q":"방에서 무엇이 보였습니까?","c":["바다","산","공원","빌딩"],"e":"「창문으로 바다가 보였어요」。","qt":"從房間看得到什麼？"},{"q":"아침식사는 어디에서 합니까?","c":["일 층 식당","방","칠 층","호텔 밖"],"e":"「아침식사는 일 층 식당에서 먹을 수 있었어요」。","qt":"早餐在哪裡吃？"}],"lv":2},{"id":"r113","t":"미용실","tz":"美容院","k":"[머리]가 [너무] [길어서|길다] [미용실]에 갔어요. 미용사가 \"[어떻게] [잘라|자르다] 드릴까요?\" 하고 [물었어요|묻다]. 저는 [잡지]에 나온 [연예인] [사진]을 [보여|보이다] 줬어요. \"이렇게 [짧게|짧다] [잘라|자르다] 주세요.\" [삼십] [분] [후]에 [거울]을 보니까 [조금] [이상했어요|이상하다]. [하지만] [친구]들이 [잘] [어울린다고|어울리다] 해서 [기분]이 [좋아졌어요|좋다].","z":"頭髮太長了，所以去了美容院。美髮師問：「要怎麼剪呢？」我給他看雜誌上藝人的照片。「請幫我剪短成這樣。」三十分鐘後照鏡子，覺得有點奇怪。但是朋友們說很適合我，心情就變好了。","q":[{"q":"이 사람은 미용사에게 무엇을 보여 주었습니까?","c":["잡지에 나온 연예인 사진","자기 옛날 사진","친구 사진","인터넷 사진"],"e":"「잡지에 나온 연예인 사진을 보여 줬어요」。","qt":"這個人給美髮師看了什麼？"},{"q":"이 사람의 기분이 좋아진 이유는?","c":["친구들이 잘 어울린다고 해서","머리가 길어서","값이 싸서","미용사가 친절해서"],"e":"「친구들이 잘 어울린다고 해서 기분이 좋아졌어요」。","qt":"這個人心情變好的原因是？"}],"lv":1},{"id":"r114","t":"요즈음 나의 생활","tz":"我最近的生活","k":"[요즈음] [저]는 [아침] [여섯] [시]에 [일어나요|일어나다]. [아침식사]를 하고 [학교]에 [걸어가요|걸어가다]. [수업]이 [끝나면|끝나다] [도서관]에서 [숙제]를 해요. [저녁]에는 [한국] [친구]와 [한국어]를 [연습해요|연습하다]. [친구]는 저에게 [중국어]를 [배워요|배우다]. [서로] [도와서|돕다] [공부]가 [재미있어요|재미있다]. [밤]에는 [침대]에 [누워서|눕다] [음악]을 들어요.","z":"我最近早上六點起床。吃完早餐走路去學校。下課後在圖書館寫作業。晚上和韓國朋友練習韓語。朋友跟我學中文。互相幫忙，所以讀書很有趣。晚上躺在床上聽音樂。","q":[{"q":"이 사람은 저녁에 무엇을 합니까?","c":["한국 친구와 한국어를 연습합니다","도서관에서 숙제를 합니다","음악을 듣습니다","학교에 갑니다"],"e":"「저녁에는 한국 친구와 한국어를 연습해요」。","qt":"這個人晚上做什麼？"},{"q":"친구는 이 사람에게 무엇을 배웁니까?","c":["중국어","한국어","영어","일본어"],"e":"「친구는 저에게 중국어를 배워요」。","qt":"朋友跟這個人學什麼？"}],"lv":3},{"id":"r115","t":"물어보기","tz":"詢問","k":"\"[이것]은 [한국어]로 [뭐]라고 해요?\" \"[그것]은 '[젓가락]'이라고 해요.\" \"그럼 [이거]는요?\" \"그건 '[숟가락]'이에요. 두 [개]를 [같이] [수저]라고 해요.\" \"[아], 그렇군요. [그러면] 저 [컵]은 [한국어]로 [뭐]예요?\" \"[저것]도 그냥 '[컵]'이라고 해요. [영어]와 [똑같아요|똑같다].\" \"[한국어]는 [재미있네요|재미있다]!\"","z":"「這個用韓語怎麼說？」「那個叫做『筷子』。」「那這個呢？」「那是『湯匙』。兩個合起來叫『湯匙和筷子』。」「啊，原來是這樣。那麼那個杯子用韓語怎麼說？」「那個也直接叫『컵』。跟英文一模一樣。」「韓語真有趣！」","q":[{"q":"숟가락과 젓가락을 같이 무엇이라고 합니까?","c":["수저","컵","그릇","칼"],"e":"「두 개를 같이 수저라고 해요」。","qt":"湯匙和筷子合起來叫什麼？"},{"q":"'컵'은 어떤 말과 같습니까?","c":["영어","중국어","일본어","한자"],"e":"「영어와 똑같아요」。","qt":"「컵」和哪種語言一樣？"}],"lv":1},{"id":"r116","t":"간호사 언니","tz":"當護理師的姊姊","k":"우리 [언니]는 대학병원 [간호사]예요. [아침] [일곱] 시부터 [저녁]까지 [일해요|일하다]. [환자]들에게 [약]을 [주고|주다] [주사]도 [놓아요|놓다]. [수술하는|수술하다] [날]에는 [의사] [선생님]을 [도와요|돕다]. [가끔] [밤]에도 [일해서|일하다] [많이] [피곤해|피곤하다] 해요. 그래도 [환자]들이 \"[감사합니다].\" 하고 [인사하면|인사하다] [힘]이 [난대요|나다]. 저는 [언니]가 [정말] [멋있어요|멋있다].","z":"我姊姊是大學醫院的護理師。從早上七點工作到晚上。給病人藥，也幫忙打針。手術的日子會協助醫生。偶爾晚上也要上班，所以很累。即使這樣，病人們說「謝謝」時，她說就有力氣了。我覺得姊姊真的很帥氣。","q":[{"q":"언니가 힘이 나는 때는?","c":["환자들이 감사하다고 할 때","월급을 받을 때","밤에 일할 때","쉬는 날"],"e":"「환자들이 감사합니다 하고 인사하면 힘이 난대요」。","qt":"姊姊什麼時候會有力氣？"},{"q":"언니가 하는 일이 아닌 것은?","c":["수술을 합니다","약을 줍니다","주사를 놓습니다","의사를 돕습니다"],"e":"手術時是協助醫生，不是自己動手術。","qt":"下列哪一項不是姊姊的工作？"}],"lv":3},{"id":"r117","t":"경찰서에 갔어요","tz":"去了警察局","k":"[어제] [시내]에서 [지갑]을 [잃었어요|잃다]. [지갑] [안]에는 [돈]과 [카드]가 있었어요. [급해서|급하다] [근처] [경찰서]에 갔어요. [경찰관]이 [친절하게|친절하다] 이것저것 [물어보고|물어보다] [서류]에 [적었어요|적다]. [한] [시간] [후]에 [경찰서]에서 [전화]가 [왔어요|오다]. [어떤] [사람]이 [지갑]을 [찾아서|찾다] [가져왔대요|가져오다]. [정말] [고마웠어요|고맙다].","z":"昨天在市區弄丟了錢包。錢包裡有錢和卡片。很著急，就去了附近的警察局。警察很親切地問了很多問題，寫在文件上。一個小時後警察局打電話來。聽說有人撿到錢包送來了。真的很感謝。","q":[{"q":"지갑에 무엇이 있었습니까?","c":["돈과 카드","여권과 돈","학생증","사진과 카드"],"e":"「지갑 안에는 돈과 카드가 있었어요」。","qt":"錢包裡有什麼？"},{"q":"지갑은 어떻게 찾았습니까?","c":["어떤 사람이 경찰서에 가져왔습니다","경찰관이 찾았습니다","집에 있었습니다","가게에서 찾았습니다"],"e":"「어떤 사람이 지갑을 찾아서 가져왔대요」。","qt":"錢包是怎麼找到的？"}],"lv":3},{"id":"r118","t":"옛날 이야기","tz":"以前的故事","k":"[할아버지]께서 [옛날] [이야기]를 해 주셨어요. [할아버지]가 [어렸을|어리다] [때]는 전기도 [없고|없다] [텔레비전]도 [없었대요|없다]. [학교]까지 [한] [시간]을 [걸어서|걷다] [다니셨대요|다니다]. [공책]도 귀해서 [종이]를 아껴서 쓰셨대요. [그때]와 [지금]은 [많이] [달라요|다르다]. [할아버지]의 [이야기]를 [들으니까|듣다] [지금]의 [생활]이 [고마워졌어요|고맙다].","z":"爺爺跟我說了以前的故事。聽說爺爺小時候沒有電，也沒有電視。上學要走一個小時的路。筆記本也很珍貴，所以紙張都省著用。那時候和現在差很多。聽了爺爺的故事，讓我對現在的生活心存感激。","q":[{"q":"할아버지는 학교에 어떻게 가셨습니까?","c":["한 시간 걸어서","버스를 타고","자전거를 타고","기차를 타고"],"e":"「학교까지 한 시간을 걸어서 다니셨대요」。","qt":"爺爺怎麼去學校？"},{"q":"이 사람은 이야기를 듣고 어떻게 생각했습니까?","c":["지금의 생활이 고마워졌습니다","옛날이 더 좋다고 생각했습니다","슬퍼졌습니다","할아버지가 부러웠습니다"],"e":"「지금의 생활이 고마워졌어요」。","qt":"這個人聽了故事後怎麼想？"}],"lv":2},{"id":"r119","t":"좋아하는 가수","tz":"喜歡的歌手","k":"제가 [가장] [좋아하는|좋아하다] [가수]는 [목소리]가 [아주] [부드러워요|부드럽다]. 그 가수의 [가요]를 들으면 [마음]이 [편해져요|편하다]. [지난달]에 [새] [시디]가 나와서 [바로] [샀어요|사다]. [인터넷]에서 그 가수의 인터뷰를 봤는데 [어렸을|어리다] 때부터 [가수]가 [꿈]이었대요. [매일] [여덟] [시간]씩 [노래] [연습]을 했대요. [다음] [달]에 [공연]이 있어서 [친구]와 [같이] 갈 거예요.","z":"我最喜歡的歌手聲音非常溫柔。聽那位歌手的歌，心情就會變平靜。上個月新 CD 出了，我馬上就買了。在網路上看了那位歌手的訪問，聽說從小就夢想當歌手。聽說每天練唱八個小時。下個月有演唱會，要和朋友一起去。","q":[{"q":"그 가수는 하루에 몇 시간씩 연습했습니까?","c":["여덟 시간","세 시간","다섯 시간","열 시간"],"e":"「매일 여덟 시간씩 노래 연습을 했대요」。","qt":"那位歌手一天練習幾個小時？"},{"q":"이 사람은 다음 달에 무엇을 할 겁니까?","c":["공연에 갑니다","시디를 삽니다","가수를 인터뷰합니다","노래를 배웁니다"],"e":"「다음 달에 공연이 있어서 친구와 같이 갈 거예요」。","qt":"這個人下個月要做什麼？"}],"lv":2},{"id":"r120","t":"강아지와 산책","tz":"和小狗散步","k":"우리 [집] [강아지]는 [다섯] [살]이에요. [눈]이 [크고|크다] [귀]가 [길어요|길다]. [매일] [저녁] [동네]를 [한] 바퀴 [산책]해요. [강아지]는 [나무] [밑]에서 [냄새]를 맡는 걸 [좋아해요|좋아하다]. [다른|다르다] [강아지]를 [만나면|만나다] [반가워서|반갑다] 뛰어가요. [산책]이 [끝나면|끝나다] [발]을 [씻어|씻다] 주고 [물]을 [줘요|주다]. [강아지]와 함께 있으면 [정말] [행복해요|행복하다].","z":"我們家的小狗五歲了。眼睛大大的，耳朵長長的。每天晚上在社區散步一圈。小狗喜歡在樹下聞味道。遇到別的狗就很開心地跑過去。散步結束後幫牠洗腳、給牠水。和小狗在一起真的很幸福。","q":[{"q":"강아지는 몇 살입니까?","c":["다섯 살","세 살","일곱 살","한 살"],"e":"「우리 집 강아지는 다섯 살이에요」。","qt":"小狗幾歲？"},{"q":"산책이 끝나면 무엇을 합니까?","c":["발을 씻어 주고 물을 줍니다","밥을 줍니다","목욕을 시킵니다","같이 잡니다"],"e":"「발을 씻어 주고 물을 줘요」。","qt":"散步結束後做什麼？"}],"lv":3},{"id":"r121","t":"컴퓨터가 고장 났어요","tz":"電腦壞了","k":"[어제] [숙제]를 하다가 [컴퓨터]가 [갑자기] [고장] 났어요. 화면이 [까맣게|까맣다] 변하고 [아무] [소리]도 [안] 났어요. [급한|급하다] [숙제]라서 [걱정]이 [많았어요|많다]. [형]이 [고치려고|고치다] 했지만 [안] 됐어요. [그래서] [서비스] [센터]에 [가져갔어요|가져가다]. [직원]이 부품을 교체하면 [된다고|되다] 했어요. 다행히 [숙제]는 [친구] [컴퓨터]로 [끝냈어요|끝내다].","z":"昨天寫作業時電腦突然壞了。畫面變黑，一點聲音都沒有。是急著要交的作業，所以很擔心。哥哥想修理但修不好。所以拿去維修中心。職員說更換零件就可以了。幸好作業用朋友的電腦寫完了。","q":[{"q":"컴퓨터는 어디에 가져갔습니까?","c":["서비스 센터","형의 회사","친구 집","학교"],"e":"「서비스 센터에 가져갔어요」。","qt":"電腦拿去哪裡了？"},{"q":"숙제는 어떻게 끝냈습니까?","c":["친구 컴퓨터로","형 컴퓨터로","학교 컴퓨터로","손으로 썼습니다"],"e":"「숙제는 친구 컴퓨터로 끝냈어요」。","qt":"作業是怎麼寫完的？"}],"lv":3},{"id":"r122","t":"광고","tz":"廣告","k":"[요즘] [텔레비전]과 [인터넷]에는 [광고]가 [정말] [많아요|많다]. [광고]를 보면 [물건]을 [사고|사다] [싶어져요|싶다]. [지난주]에 [광고]에서 본 [화장품]을 [샀어요|사다]. [그런데] [써|쓰다] 보니까 [광고]와 [달랐어요|다르다]. [그래서] [조금] 실망했어요. [이제]부터는 [광고]만 믿지 않고 [사용한|사용하다] [사람]들의 [이야기]를 [먼저] [읽을|읽다] 거예요.","z":"最近電視和網路上的廣告真的很多。看了廣告就會想買東西。上週買了在廣告上看到的化妝品。可是用了之後發現和廣告不一樣。所以有點失望。從現在開始不會只相信廣告，會先讀用過的人的心得。","q":[{"q":"이 사람이 산 물건은?","c":["화장품","옷","컴퓨터","음식"],"e":"「광고에서 본 화장품을 샀어요」。","qt":"這個人買了什麼？"},{"q":"앞으로 이 사람은 어떻게 할 겁니까?","c":["사용한 사람들의 이야기를 먼저 읽습니다","광고를 믿습니다","화장품을 사지 않습니다","광고를 만듭니다"],"e":"「사용한 사람들의 이야기를 먼저 읽을 거예요」。","qt":"這個人以後會怎麼做？"}],"lv":2},{"id":"r123","t":"외할아버지 생신","tz":"外公的生日","k":"[어저께]는 [외할아버지]의 [아흔] 번째 [생신]이었어요. [큰어머니], [작은어머니], [형님]과 [조카]들까지 [모두] [모였어요|모이다]. \"[외할아버지], [오래간만입니다]. [안녕하셨어요|안녕하다]?\" [오랜만에] [뵙는|뵙다] [친척]들도 [많았어요|많다]. 저는 [인삼]을 [선물했어요|선물하다]. [외할아버지]께서 [맛있게|맛있다] [잡수시고|잡수시다] \"[고맙습니다].\" 하고 [말씀하셨어요|말씀하다]. [저녁식사] [후]에 [다]같이 [건배]를 했어요.","z":"前天是外公九十歲的生日。伯母、嬸嬸、哥哥和姪子們全都聚在一起了。「外公，好久不見。您好嗎？」也有很多好久沒見的親戚。我送了人蔘。外公吃得很開心，說了「謝謝」。晚餐後大家一起乾杯了。","q":[{"q":"외할아버지는 몇 번째 생신이었습니까?","c":["아흔 번째","여든 번째","일흔 번째","예순 번째"],"e":"「외할아버지의 아흔 번째 생신이었어요」。","qt":"外公是幾歲生日？"},{"q":"이 사람은 무엇을 선물했습니까?","c":["인삼","케이크","옷","꽃"],"e":"「저는 인삼을 선물했어요」。","qt":"這個人送了什麼？"}],"lv":3},{"id":"r124","t":"문구점과 꽃집","tz":"文具店和花店","k":"[친구] [생일] [선물]을 사러 [문구점]에 갔어요. [예쁜|예쁘다] [노트]와 [수첩], [펜]을 [골랐어요|고르다]. [포장]할 [종이]와 [가위], [풀]도 [샀어요|사다]. \"[모두] [얼마]예요?\" \"[만] 오천 [원]이에요.\" 그다음 [옆] [꽃집]에서 [장미] [다섯] [송이]를 샀어요. [천] [원]짜리 [무궁화] [그림] [카드]도 [하나] 샀어요. [친구]가 [좋아하면|좋아하다] [좋겠어요|좋다].","z":"去文具店買朋友的生日禮物。挑了漂亮的筆記本、記事本和筆。也買了包裝用的紙、剪刀和膠水。「全部多少錢？」「一萬五千韓元。」然後在旁邊的花店買了五朵玫瑰。也買了一張一千韓元的木槿花圖案卡片。希望朋友會喜歡。","q":[{"q":"문구점에서 산 것이 아닌 것은?","c":["장미","노트","가위","수첩"],"e":"玫瑰是在花店買的。","qt":"下列哪一項不是在文具店買的？"},{"q":"카드는 얼마였습니까?","c":["천 원","만 오천 원","오천 원","만 원"],"e":"「천 원짜리 무궁화 그림 카드」。","qt":"卡片多少錢？"}],"lv":2},{"id":"r125","t":"다이어트","tz":"減肥","k":"[이번] [달]부터 [다이어트]를 [시작했어요|시작하다]. [작년]보다 몸무게가 [오] [킬로그램] [늘었거든요|늘다]. [아침]에는 [토마토]와 [당근] [주스]를 [마시고|마시다] [점심식사]로 [닭고기]와 [채소]를 먹어요. [저녁]에는 [배부르게|배부르다] 먹지 않아요. [매주] [세] [번] [운동복]을 [입고|입다] [운동화]를 [신고|신다] [달려요|달리다]. [땀]을 [많이] 흘리면 [기분]이 [좋아요|좋다]. [하지만] [무리]하지 [않으려고|않다] 해요.","z":"這個月開始減肥了。因為比去年胖了五公斤。早上喝番茄和紅蘿蔔汁，午餐吃雞肉和蔬菜。晚餐不吃太飽。每週三次穿上運動服和運動鞋去跑步。流很多汗心情會很好。但是盡量不要太勉強。","q":[{"q":"이 사람은 왜 다이어트를 시작했습니까?","c":["몸무게가 오 킬로그램 늘어서","옷이 작아서","병원에서 말해서","결혼식이 있어서"],"e":"「작년보다 몸무게가 오 킬로그램 늘었거든요」。","qt":"這個人為什麼開始減肥？"},{"q":"점심에는 무엇을 먹습니까?","c":["닭고기와 채소","토마토 주스","당근","아무것도 안 먹습니다"],"e":"「점심식사로 닭고기와 채소를 먹어요」。","qt":"午餐吃什麼？"}],"lv":3},{"id":"r126","t":"장마철","tz":"梅雨季","k":"[한국]은 [유월] [말]부터 [칠월]까지 [장마]예요. [장마철]에는 [하늘]이 [흐리고|흐리다] [비]가 [매일] 와요. [햇빛]을 [보기|보다] [어려워서|어렵다] [빨래]가 [잘] [마르지|마르다] 않아요. [그래서] [방]에 [선풍기]를 [틀어|틀다] [놓아요|놓다]. [칠월] [말]이나 [팔월]에는 [태풍]이 [오기도|오다] 해요. [태풍]이 오면 [바람]이 세고 [위험해서|위험하다] [밖]에 [나가지|나가다] 않는 게 [좋아요|좋다].","z":"韓國從六月底到七月是梅雨季。梅雨季天空陰陰的，每天都下雨。很難看到陽光，所以衣服晾不乾。所以在房間開著電風扇。七月底或八月有時候會有颱風。颱風來的時候風很大、很危險，最好不要出門。","q":[{"q":"장마철에 빨래가 잘 마르지 않는 이유는?","c":["햇빛을 보기 어려워서","바람이 세서","날씨가 추워서","선풍기가 없어서"],"e":"「햇빛을 보기 어려워서 빨래가 잘 마르지 않아요」。","qt":"梅雨季衣服晾不乾的原因是？"},{"q":"태풍이 오면 어떻게 해야 합니까?","c":["밖에 나가지 않습니다","빨래를 합니다","선풍기를 틉니다","바다에 갑니다"],"e":"「밖에 나가지 않는 게 좋아요」。","qt":"颱風來時該怎麼做？"}],"lv":2},{"id":"r127","t":"설악산 단풍","tz":"雪嶽山的楓葉","k":"[시월]에 [친구]들과 [설악산]에 갔어요. [가을]이라서 [나무]의 [잎]이 [빨갛게|빨갛다] 변해서 [정말] [예뻤어요|예쁘다]. [새] [등산복]을 [입고|입다] [등산화]를 [신었어요|신다]. [산] [위]까지 [오르는|오르다] 데 [세] [시간]이 [걸렸어요|걸리다]. [길]이 [좁은|좁다] [곳]은 [위험해서|위험하다] [조심했어요|조심하다]. [산]에서 [내려올|내려오다] 때는 [다리]가 떨렸지만 [경치]를 [생각하면|생각하다] [또] 가고 싶어요.","z":"十月和朋友們去了雪嶽山。因為是秋天，樹葉變紅了，真的很漂亮。穿了新的登山服和登山鞋。爬到山頂花了三個小時。路很窄的地方很危險，所以很小心。下山時腿在發抖，但一想到風景又想再去了。","q":[{"q":"산 위까지 얼마나 걸렸습니까?","c":["세 시간","한 시간","다섯 시간","두 시간"],"e":"「산 위까지 오르는 데 세 시간이 걸렸어요」。","qt":"爬到山頂花了多久？"},{"q":"이 사람들은 언제 설악산에 갔습니까?","c":["시월","오월","칠월","십이월"],"e":"「시월에 친구들과 설악산에 갔어요」。","qt":"這些人什麼時候去雪嶽山？"}],"lv":2},{"id":"r128","t":"남대문시장","tz":"南大門市場","k":"[남대문] [근처]에 있는 [남대문시장]은 [외국] 관광객에게도 [유명해요|유명하다]. [옷], [신발], [안경], [스타킹] [등] [없는|없다] 것이 [없어요|없다]. [가게] [주인]들은 [손님]에게 \"[어서] 오세요, [아가씨]!\" 하고 [불러요|부르다]. [비슷한|비슷하다] [모양]의 [물건]이 [많아서|많다] [잘] [골라야|고르다] 해요. [값]을 [깎아|깎다] 달라고 [말하면|말하다] [조금] 깎아 [줘요|주다]. [요즘] [유행]하는 [패션]도 [싸게|싸다] [살|사다] 수 있어요.","z":"南大門附近的南大門市場對外國觀光客來說也很有名。衣服、鞋子、眼鏡、絲襪等等，應有盡有。店老闆們會對客人喊：「歡迎光臨，小姐！」形狀相似的東西很多，所以要好好挑。說請算便宜一點，就會少算一些。最近流行的時尚也能買得很便宜。","q":[{"q":"값을 깎아 달라고 하면 어떻게 됩니까?","c":["조금 깎아 줍니다","화를 냅니다","절대 안 깎아 줍니다","선물을 줍니다"],"e":"「값을 깎아 달라고 말하면 조금 깎아 줘요」。","qt":"請老闆算便宜會怎麼樣？"},{"q":"남대문시장에 대한 내용과 같은 것은?","c":["유행하는 패션도 싸게 살 수 있습니다","옷만 팝니다","외국 사람은 모릅니다","물건이 비쌉니다"],"e":"「요즘 유행하는 패션도 싸게 살 수 있어요」。","qt":"關於南大門市場，哪一項正確？"}],"lv":2},{"id":"r129","t":"일기를 쓰는 이유","tz":"寫日記的理由","k":"저는 [한국어]로 [일기]를 써요. [그날] [있었던|있다] [일]과 [느낌]을 [간단히] [적어요|적다]. [모르는|모르다] [표현]이 있으면 [전자사전]이나 [사전]에서 [뜻]을 [찾아요|찾다]. [예문]을 보면 [의미]를 [더] [잘] [이해할|이해하다] 수 있어요. [일기]를 쓰면 [단어]를 [잊어버리지|잊어버리다] 않고 [오래] [기억할|기억하다] 수 있어요. [나중]에 [읽으면|읽다] 좋은 [추억]도 돼요.","z":"我用韓語寫日記。簡單地寫下那天發生的事和感受。有不懂的說法就查電子辭典或字典找意思。看例句可以更了解意思。寫日記就不會忘記單字，可以記得很久。以後讀的時候也會變成美好的回憶。","q":[{"q":"모르는 표현이 있으면 어떻게 합니까?","c":["사전에서 뜻을 찾습니다","선생님께 물어봅니다","쓰지 않습니다","친구에게 전화합니다"],"e":"「전자사전이나 사전에서 뜻을 찾아요」。","qt":"有不懂的說法時怎麼做？"},{"q":"일기를 쓰면 좋은 점이 아닌 것은?","c":["발음이 좋아집니다","단어를 오래 기억합니다","좋은 추억이 됩니다","표현을 배웁니다"],"e":"文中沒有提到發音。","qt":"下列哪一項不是寫日記的好處？"}],"lv":2},{"id":"r130","t":"인터뷰","tz":"採訪","k":"[오늘] [학교] [신문] [기사]를 [쓰려고|쓰다] [유명한|유명하다] [소설가]를 [인터뷰했어요|인터뷰하다]. \"[선생]님은 [언제] [소설]을 [쓰기|쓰다] [시작하셨어요|시작하다]?\" \"[대학생] 때 [시작했어요|시작하다]. [그때]는 [잘] [못했지만|못하다] [오랫동안] [연습했어요|연습하다].\" \"[소설]을 쓸 때 [무엇이] [제일] [중요해요|중요하다]?\" \"[다른|다르다] [사람]의 [마음]을 [이해하는|이해하다] 거예요. [그리고] [책]을 [많이] 읽는 것도 [필요해요|필요하다].\" [좋은|좋다] [대답]을 [들을|듣다] 수 있어서 [감사했어요|감사하다].","z":"今天為了寫校刊報導，採訪了一位有名的小說家。「老師您什麼時候開始寫小說的？」「大學的時候開始的。那時候寫得不好，但是練習了很長一段時間。」「寫小說時什麼最重要？」「理解別人的心。還有，多讀書也很必要。」能聽到很好的回答，非常感謝。","q":[{"q":"소설가는 언제 소설을 쓰기 시작했습니까?","c":["대학생 때","중학생 때","회사원 때","어렸을 때"],"e":"「대학생 때 시작했어요」。","qt":"小說家什麼時候開始寫小說？"},{"q":"소설을 쓸 때 제일 중요한 것은?","c":["다른 사람의 마음을 이해하는 것","빨리 쓰는 것","여행하는 것","컴퓨터를 잘하는 것"],"e":"「다른 사람의 마음을 이해하는 거예요」。","qt":"寫小說時最重要的是？"}],"lv":1},{"id":"r131","t":"발표 준비","tz":"準備報告","k":"[다음 주|다음주] [월요일]에 [과학] [수업]에서 [발표]를 해요. [발표] 주제는 [전기자동차]예요. [인터넷]에서 [정보]와 [자료]를 [모았어요|모으다]. [친구]와 [같이] [순서]를 [정하고|정하다] [제목]도 [만들었어요|만들다]. [저]는 [전기자동차]의 [장점]과 [특징]을 [설명할|설명하다] 거예요. [친구]는 [미래]의 [자동차]에 대해서 말할 거예요. [발표]가 [끝나면|끝나다] [질문]을 [받아야|받다] 해서 [조금] [긴장돼요|긴장되다].","z":"下週一科學課要上台報告。報告的主題是電動車。在網路上收集了資訊和資料。和朋友一起決定了順序，也訂了題目。我要說明電動車的優點和特徵。朋友要講未來的汽車。報告結束後還要接受提問，所以有點緊張。","q":[{"q":"발표 주제는 무엇입니까?","c":["전기자동차","과학 수업","인터넷","자동차 회사"],"e":"「발표 주제는 전기자동차예요」。","qt":"報告的主題是什麼？"},{"q":"이 사람은 무엇을 설명할 겁니까?","c":["전기자동차의 장점과 특징","미래의 자동차","자료 찾는 방법","발표 순서"],"e":"「전기자동차의 장점과 특징을 설명할 거예요」。","qt":"這個人要說明什麼？"}],"lv":3},{"id":"r132","t":"입학과 졸업","tz":"入學和畢業","k":"[한국]의 [학교]는 [삼월]에 [입학]을 하고 [이월]에 [졸업]을 해요. [초등학교]는 [육] [년], [중학교]와 [고등학교]는 [각] [삼] 년이에요. [동생]은 [올해] [중학교]에 입학한 [중학생]이에요. [언니]는 [이월]에 [대학교]를 [졸업했어요|졸업하다]. 졸업식 [날] [가족]이 [모두] 가서 [꽃]을 주고 [축하했어요|축하하다]. [언니]는 [반년] [후]에 [대학원]에 [들어갈|들어가다] [계획]이에요.","z":"韓國的學校三月入學，二月畢業。國小六年，國中和高中各三年。弟弟（妹妹）是今年剛上國中的國中生。姊姊二月從大學畢業了。畢業典禮那天全家都去送花祝賀。姊姊打算半年後進研究所。","q":[{"q":"한국 학교는 언제 입학합니까?","c":["삼월","이월","구월","일월"],"e":"「삼월에 입학을 하고 이월에 졸업을 해요」。","qt":"韓國學校什麼時候入學？"},{"q":"언니의 계획은 무엇입니까?","c":["반년 후에 대학원에 들어갑니다","취직합니다","중학교 선생님이 됩니다","여행을 갑니다"],"e":"「반년 후에 대학원에 들어갈 계획이에요」。","qt":"姊姊的計畫是什麼？"}],"lv":2},{"id":"r133","t":"민속촌","tz":"民俗村","k":"[외국] [친구]를 [데리고|데리다] [민속촌]에 갔어요. [민속촌]에는 [옛날] [한국] [사람]들이 [살던|살다] [집]이 있어요. [안내하는|안내하다] [분]이 [집]을 [어떻게] [지었는지|짓다] [설명해|설명하다] 주셨어요. [우리]는 [한복]을 [입고|입다] [사진]도 [찍었어요|찍다]. [친구]는 한국 [문화]를 [직접] [느낄|느끼다] 수 있어서 [좋다고|좋다] 했어요. [민속촌]은 [시외]에 있어서 [버스]로 [한] [시간] [반]쯤 걸려요.","z":"帶外國朋友去了民俗村。民俗村裡有以前韓國人住過的房子。導覽的人說明了房子是怎麼蓋的。我們穿上韓服也拍了照。朋友說能親身感受韓國文化，很好。民俗村在郊外，搭公車大約要一個半小時。","q":[{"q":"민속촌에는 무엇이 있습니까?","c":["옛날 한국 사람들이 살던 집","새 아파트","큰 백화점","놀이공원"],"e":"「옛날 한국 사람들이 살던 집이 있어요」。","qt":"民俗村裡有什麼？"},{"q":"민속촌까지 얼마나 걸립니까?","c":["한 시간 반쯤","삼십 분쯤","세 시간쯤","두 시간 반쯤"],"e":"「버스로 한 시간 반쯤 걸려요」。","qt":"到民俗村要多久？"}],"lv":2},{"id":"r134","t":"슈퍼마켓","tz":"超市","k":"[집] [주변]에 [큰|크다] [슈퍼마켓]이 [생겼어요|생기다]. [매주] [수요일]에는 [채소]와 [과일]을 [할인]해 줘요. [어제]는 [쌀] [한] 포대, [쇠고기], [된장]을 샀어요. 계산대 [앞]에 [줄]이 [길어서|길다] [잠깐] [서서|서다] [기다렸어요|기다리다]. [짐]이 [많아서|많다] [가방]을 [메고|메다] [봉지]를 들고 [집]에 [왔어요|오다]. [다음]에는 [배달]을 [이용할|이용하다] 거예요.","z":"家附近開了一家大超市。每週三蔬菜和水果打折。昨天買了一袋米、牛肉和大醬。收銀台前隊伍很長，所以站著等了一下。東西很多，所以揹著包包、提著袋子回家。下次要利用外送服務。","q":[{"q":"슈퍼마켓은 언제 채소를 할인합니까?","c":["매주 수요일","매주 월요일","주말","매일"],"e":"「매주 수요일에는 채소와 과일을 할인해 줘요」。","qt":"超市什麼時候蔬菜打折？"},{"q":"이 사람은 다음에 어떻게 할 겁니까?","c":["배달을 이용합니다","가방을 삽니다","수요일에 갑니다","걸어갑니다"],"e":"「다음에는 배달을 이용할 거예요」。","qt":"這個人下次要怎麼做？"}],"lv":2},{"id":"r135","t":"우리 동네 지도","tz":"我們社區的地圖","k":"우리 [동네] [지도]를 [그려|그리다] 볼게요. [지하철역] [입구]에서 [나오면|나오다] [오른쪽]에 [은행]이 있어요. [은행] [뒤쪽]에는 [작은|작다] [골목]이 있고 [골목] [안]에 [세탁소]와 [책방]이 있어요. [역] [왼쪽]으로 [백] [미터]쯤 가면 [삼거리]가 나와요. [삼거리] [동쪽]에는 [학교] [정문]이 있고 [서쪽]에는 [공원]이 있어요. [공원] [아래]에는 [지하도]가 있어요. [이곳]이 우리 동네의 [중심]이에요.","z":"我來畫畫看我們社區的地圖。從地鐵站入口出來，右邊有銀行。銀行後面有一條小巷，巷子裡有洗衣店和書店。從車站往左走大約一百公尺，會出現三岔路口。三岔路口東邊是學校正門，西邊是公園。公園下面有地下道。這裡是我們社區的中心。","q":[{"q":"세탁소는 어디에 있습니까?","c":["은행 뒤쪽 골목 안","삼거리 동쪽","공원 아래","역 왼쪽"],"e":"「은행 뒤쪽에는 작은 골목이 있고 골목 안에 세탁소와 책방이 있어요」。","qt":"洗衣店在哪裡？"},{"q":"학교 정문은 어디에 있습니까?","c":["삼거리 동쪽","삼거리 서쪽","은행 옆","지하도 아래"],"e":"「삼거리 동쪽에는 학교 정문이 있고」。","qt":"學校正門在哪裡？"}],"lv":3},{"id":"r136","t":"목욕탕","tz":"澡堂","k":"[한국]에는 [큰|크다] 목욕탕이 [많아요|많다]. [저]는 [처음]에 [다른|다르다] [사람]들과 [같이] [목욕하는|목욕하다] 것이 [조금] [이상했어요|이상하다]. [하지만] [뜨거운|뜨겁다] [물]에 [오래] [앉아|앉다] 있으면 [몸]이 [편해져요|편하다]. [목욕]이 [끝나면|끝나다] [시원한|시원하다] [우유]나 [사이다]를 [마셔요|마시다]. [아빠]와 [같이] 가면 [아빠]가 제 [등]을 밀어 주세요. [요즘]은 [한] [달]에 [한] [번]쯤 가요.","z":"韓國有很多大澡堂。我一開始覺得和別人一起洗澡有點奇怪。但是在熱水裡坐久了身體就會很舒服。洗完澡喝冰涼的牛奶或汽水。和爸爸一起去的話，爸爸會幫我搓背。最近大約一個月去一次。","q":[{"q":"목욕이 끝나면 무엇을 마십니까?","c":["우유나 사이다","커피","맥주","뜨거운 차"],"e":"「시원한 우유나 사이다를 마셔요」。","qt":"洗完澡喝什麼？"},{"q":"요즘 얼마나 자주 갑니까?","c":["한 달에 한 번쯤","매주","매일","일 년에 한 번"],"e":"「요즘은 한 달에 한 번쯤 가요」。","qt":"最近多久去一次？"}],"lv":2},{"id":"r137","t":"저 사람은 누구예요?","tz":"那個人是誰？","k":"\"[저기] [저쪽]에 [서|서다] 있는 [저분]은 [누구]세요?\" \"[아], [그분]은 [우리] [회사] [부장]님의 [부인]이세요.\" \"[그래요|그래]? [그럼] [이분]은요?\" \"[이분]은 [저희] [팀]의 [새] [사원]이에요. [그중]에서 [한국어]를 [제일] [잘해요|잘하다].\" \"[그렇군요|그렇다]. [나]도 [인사]하고 [싶어요|싶다].\" \"[물론]이죠. [이쪽]으로 오세요.\"","z":"「那邊站著的那位是誰？」「啊，那位是我們公司部長的夫人。」「是嗎？那這位呢？」「這位是我們團隊的新員工。其中他韓語說得最好。」「原來如此。我也想打個招呼。」「當然。請往這邊走。」","q":[{"q":"저기 서 있는 사람은 누구입니까?","c":["부장님의 부인","새 사원","부장님","사장님"],"e":"「그분은 우리 회사 부장님의 부인이세요」。","qt":"站在那邊的人是誰？"},{"q":"새 사원에 대한 내용과 같은 것은?","c":["한국어를 제일 잘합니다","부장님입니다","다른 회사 사람입니다","인사를 안 했습니다"],"e":"「그중에서 한국어를 제일 잘해요」。","qt":"關於新員工，哪一項正確？"}],"lv":1},{"id":"r138","t":"쇼핑하기","tz":"購物","k":"\"[이] [가방] [얼마나] 해요?\" \"오만 [원]이에요.\" \"[좀] [비싸네요|비싸다]. [좀더] [싼|싸다] 건 [없어요|없다]?\" \"[저거]는 삼만 원이에요. [디자인]도 [비슷해요|비슷하다].\" \"음, [크기]가 [약간] [작네요|작다]. [그냥] [이거]로 할게요. [카드]로 [계산해도|계산하다] [돼요|되다]?\" \"[예], [물론]이죠. [봉투]에 [따로] 넣어 [드릴까요|드리다]?\" \"[아니요], [괜찮아요|괜찮다].\"","z":"「這個包包多少錢？」「五萬韓元。」「有點貴耶。沒有更便宜一點的嗎？」「那個是三萬韓元。設計也差不多。」「嗯，尺寸有點小。我還是買這個好了。可以刷卡嗎？」「是的，當然可以。要幫您另外裝袋嗎？」「不用，沒關係。」","q":[{"q":"손님은 어떤 가방을 샀습니까?","c":["오만 원짜리 가방","삼만 원짜리 가방","두 개 다","사지 않았습니다"],"e":"「그냥 이거로 할게요」，也就是五萬韓元的那個。","qt":"客人買了哪個包包？"},{"q":"삼만 원짜리 가방을 사지 않은 이유는?","c":["크기가 작아서","디자인이 이상해서","너무 비싸서","색깔이 싫어서"],"e":"「크기가 약간 작네요」。","qt":"為什麼沒買三萬韓元的包包？"}],"lv":1},{"id":"r139","t":"맞아요, 아니에요","tz":"對，不是","k":"\"민수 씨, [내일] [모임]에 가요?\" \"[응], 갈 거야. [너]도 가?\" \"[아뇨], 저는 [아마] 못 갈 거예요. [부업] [때문]에 [시간]이 [없어요|없다].\" \"[그래]? 아쉽다. [만일] [일]이 [일찍] [끝나면|끝나다] [와|오다].\" \"[네], [알겠습니다|알다]. [그런데] [모임]은 [몇] [시]예요?\" \"[일곱] 시야. [장소]는 [늘] 가던 [식당]이야.\" \"[아], [맞다]! [거기] [맞지요|맞다]?\" \"[맞아요], [거기]예요.\"","z":"「民秀，你明天會去聚會嗎？」「嗯，會去。你也去嗎？」「不，我大概去不了。因為兼職沒有時間。」「是嗎？好可惜。萬一工作提早結束就來吧。」「好的，知道了。不過聚會是幾點？」「七點。地點是常去的那家餐廳。」「啊，對了！是那裡對吧？」「對，就是那裡。」","q":[{"q":"이 사람이 모임에 못 가는 이유는?","c":["부업 때문에","아파서","여행을 가서","모임이 싫어서"],"e":"「부업 때문에 시간이 없어요」。","qt":"這個人不能去聚會的原因是？"},{"q":"모임 장소는 어디입니까?","c":["늘 가던 식당","민수 씨 집","회사","카페"],"e":"「장소는 늘 가던 식당이야」。","qt":"聚會地點在哪裡？"}],"lv":3},{"id":"r140","t":"나의 전공","tz":"我的主修","k":"[내] [전공]은 관광이에요. [처음]에는 [다른|다르다] [전공]을 [선택하려고|선택하다] 했어요. [그러나] [여행]을 [좋아해서|좋아하다] 이 [전공]을 [골랐어요|고르다]. [수업]에서는 [국내] [여행]과 [해외] [여행], [국제] [관계] [등]을 [배워요|배우다]. [특히] [외국어]가 [중요해서|중요하다] [영어회화]와 [일본말]을 [열심히] [공부해요|공부하다]. [졸업]하면 [여행사]나 [호텔]에서 [일하고|일하다] [싶어요|싶다].","z":"我的主修是觀光。一開始本來想選別的主修。但是因為喜歡旅行，所以選了這個主修。課堂上學國內旅遊、國外旅遊、國際關係等等。特別是外語很重要，所以認真學英語會話和日語。畢業後想在旅行社或飯店工作。","q":[{"q":"이 사람의 전공은?","c":["관광","외국어","국제 관계","호텔"],"e":"「내 전공은 관광이에요」。","qt":"這個人的主修是？"},{"q":"이 사람이 열심히 공부하는 외국어는?","c":["영어회화와 일본말","중국어","영어와 중국어","일본말만"],"e":"「영어회화와 일본말을 열심히 공부해요」。","qt":"這個人認真學的外語是？"}],"lv":2},{"id":"r141","t":"바닷가에서","tz":"在海邊","k":"[오월] [연휴]에 [가족]과 [바닷가]에 갔어요. [바다]는 [파랗고|파랗다] [하늘]에는 [구름]이 [하나]도 없었어요. [아이]들은 모래로 [성]을 [만들며|만들다] [놀았어요|놀다]. [물]이 [아직] [차가워서|차갑다] [수영]은 [못했어요|못하다]. [바다] [위]에 [오리]처럼 생긴 [배]가 [떠|뜨다] 있었어요. [밤]에는 [하늘]에 [별]이 [많고|많다] [반달]도 [떴어요|뜨다]. [정말] [아름다운|아름답다] [밤]이었어요.","z":"五月連假和家人去了海邊。大海很藍，天上一朵雲也沒有。孩子們用沙子堆城堡玩。水還很冰，所以沒辦法游泳。海上漂著一艘長得像鴨子的船。晚上天上星星很多，半月也升起來了。真是美麗的夜晚。","q":[{"q":"수영을 못한 이유는?","c":["물이 아직 차가워서","비가 와서","바다가 위험해서","수영복이 없어서"],"e":"「물이 아직 차가워서 수영은 못했어요」。","qt":"沒辦法游泳的原因是？"},{"q":"밤하늘에 무엇이 있었습니까?","c":["별과 반달","구름","비행기","해"],"e":"「하늘에 별이 많고 반달도 떴어요」。","qt":"夜空中有什麼？"}],"lv":3},{"id":"r142","t":"얼음과 수돗물","tz":"冰塊和自來水","k":"[여름]에 [한국] [식당]에 가면 [물]에 [얼음]을 넣어 줘요. [한국]에서는 [수돗물]을 [바로] [마실|마시다] 수 있다고 해요. [그렇지만] [대부분]의 [사람]들은 [끓여서|끓이다] 마시거나 [사서|사다] 마셔요. [호텔]이나 [식당]에서는 [뜨거운|뜨겁다] [물]과 [차가운|차갑다] 물을 [모두] 줘요. [겨울]에는 [더운물]이 [나오는|나오다] 기계가 [인기]가 많아요.","z":"夏天去韓國餐廳，會在水裡加冰塊。聽說在韓國自來水可以直接喝。但是大部分的人會煮開再喝，或是買水喝。飯店或餐廳熱水和冰水都會提供。冬天會出熱水的機器很受歡迎。","q":[{"q":"한국 사람들은 수돗물을 보통 어떻게 마십니까?","c":["끓여서 마시거나 사서 마십니다","바로 마십니다","얼음을 넣어 마십니다","마시지 않습니다"],"e":"「대부분의 사람들은 끓여서 마시거나 사서 마셔요」。","qt":"韓國人通常怎麼喝自來水？"},{"q":"겨울에 인기가 많은 것은?","c":["더운물이 나오는 기계","얼음","차가운 물","수돗물"],"e":"「더운물이 나오는 기계가 인기가 많아요」。","qt":"冬天很受歡迎的是？"}],"lv":1},{"id":"r143","t":"요리 강좌","tz":"烹飪講座","k":"[시민] [센터]에서 [무료] [요리] [강좌]를 [신청했어요|신청하다]. [첫] [수업]에서 [한국요리]인 [된장찌개]와 [두부찌개]를 [배웠어요|배우다]. [선생님]이 [칼]로 [채소]를 [써는|썰다] [방법]을 [설명해|설명하다] 주셨어요. [다음] [주]에는 [일식]과 [중식]을 [요리할|요리하다] 거예요. 그다음에는 [카레]를 만들 [계획]이래요. [요리하는|요리하다] 것이 [이렇게] [재미있는지|재미있다] [몰랐어요|모르다].","z":"在市民中心報名了免費的烹飪講座。第一堂課學了韓國料理大醬鍋和豆腐鍋。老師說明了用刀切蔬菜的方法。下週要做日式料理和中式料理。聽說之後還計畫要做咖哩。我不知道做菜原來這麼有趣。","q":[{"q":"첫 수업에서 배운 요리는?","c":["된장찌개와 두부찌개","일식과 중식","카레","김치찌개"],"e":"「첫 수업에서 된장찌개와 두부찌개를 배웠어요」。","qt":"第一堂課學了什麼菜？"},{"q":"요리 강좌는 어떤 강좌입니까?","c":["무료 강좌","비싼 강좌","인터넷 강좌","회사 강좌"],"e":"「무료 요리 강좌를 신청했어요」。","qt":"烹飪講座是什麼樣的講座？"}],"lv":2},{"id":"r144","t":"비행기가 늦었어요","tz":"飛機誤點了","k":"[베이징]에서 [서울]로 오는 [비행기]가 [두] [시간]이나 늦게 [출발했어요|출발하다]. [공항] 안내 [방송]에서 [날씨] [때문]이라고 했어요. [기다리는|기다리다] [동안] [잡지]를 [읽고|읽다] [이메일]도 [확인했어요|확인하다]. [비행기]가 [인천]에 [도착]한 [시간]은 [밤] 열두 시였어요. 공항버스도 끊겨서 [택시]를 탔어요. [집]에 [도착하니까|도착하다] [새벽] [한] 시였어요.","z":"從北京飛往首爾的飛機晚了兩個小時才出發。機場廣播說是因為天氣。等待的時候看了雜誌，也確認了電子郵件。飛機抵達仁川的時間是半夜十二點。機場巴士也停駛了，所以搭了計程車。到家時已經凌晨一點了。","q":[{"q":"비행기가 늦은 이유는?","c":["날씨 때문에","비행기가 고장 나서","손님이 늦어서","공항이 복잡해서"],"e":"「날씨 때문이라고 했어요」。","qt":"飛機誤點的原因是？"},{"q":"이 사람은 공항에서 집까지 무엇을 탔습니까?","c":["택시","공항버스","지하철","친구 차"],"e":"「공항버스도 끊겨서 택시를 탔어요」。","qt":"這個人從機場搭什麼回家？"}],"lv":2},{"id":"r145","t":"어린이날","tz":"兒童節","k":"[오월] [오] [일]은 어린이날이에요. [어린이]들이 [선물]을 [받는|받다] [날]이에요. [조카]가 [인형]을 [갖고|갖다] [싶다고|싶다] 해서 [백화점]에 갔어요. [사람]이 [너무] [많아서|많다] 한참 [줄]을 [서야|서다] 했어요. [조카]는 [인형]을 [안고|안다] [매우] [즐거워했어요|즐거워하다]. [조카]가 [웃는|웃다] 모습을 보니까 저도 [기분]이 [좋았어요|좋다].","z":"五月五日是兒童節。是孩子們收到禮物的日子。姪子說想要娃娃，所以去了百貨公司。人太多了，排了好久的隊。姪子抱著娃娃非常開心。看到姪子笑的樣子，我心情也很好。","q":[{"q":"조카는 무엇을 받고 싶어 했습니까?","c":["인형","자전거","옷","책"],"e":"「조카가 인형을 갖고 싶다고 해서」。","qt":"姪子想收到什麼？"},{"q":"어린이날은 언제입니까?","c":["오월 오 일","오월 일 일","유월 오 일","사월 오 일"],"e":"「오월 오 일은 어린이날이에요」。","qt":"兒童節是什麼時候？"}],"lv":2},{"id":"r146","t":"열쇠를 잃어버렸어요","tz":"弄丟了鑰匙","k":"[어제] [밤]에 [집]에 [오니까|오다] [주머니]에 [열쇠]가 [없었어요|없다]. [가방] [속]도 [찾아봤지만|찾다] [없었어요|없다]. [밖]은 [어둡고|어둡다] [추워서|춥다] [걱정]이 됐어요. 옆집 [아주머니]께 [부탁]해서 [전화기]를 [빌렸어요|빌리다]. [부동산]에 [전화했더니|전화하다] [잠시] [후]에 [아저씨]가 [다른|다르다] [열쇠]를 [가지고|가지다] [와|오다] 주셨어요. [다음]부터는 [열쇠]를 [잘] 챙겨야겠어요.","z":"昨天晚上回到家，口袋裡沒有鑰匙。也找了包包裡面，還是沒有。外面又暗又冷，很擔心。拜託隔壁阿姨借了電話。打電話給房屋仲介，過了一會兒大叔拿了另一把鑰匙來。以後一定要好好帶著鑰匙。","q":[{"q":"이 사람은 누구에게 전화기를 빌렸습니까?","c":["옆집 아주머니","부동산 아저씨","친구","경찰"],"e":"「옆집 아주머니께 부탁해서 전화기를 빌렸어요」。","qt":"這個人向誰借了電話？"},{"q":"문제는 어떻게 해결되었습니까?","c":["부동산 아저씨가 열쇠를 가져왔습니다","가방 속에서 찾았습니다","문을 부쉈습니다","친구 집에서 잤습니다"],"e":"「아저씨가 다른 열쇠를 가지고 와 주셨어요」。","qt":"問題是怎麼解決的？"}],"lv":2},{"id":"r147","t":"배탈이 났어요","tz":"吃壞肚子了","k":"[어제] [저녁]에 [맛없는|맛없다] [생선]을 먹고 [배탈]이 났어요. [밤]새 [배]가 [아파서|아프다] [잠]을 [잘] [못] [잤어요|자다]. [아침]에 [약국]에 가서 [소화제]를 [샀어요|사다]. [약사]가 [오늘]은 [죽]만 먹고 찬 [물]은 [마시지|마시다] [말라고|말다] 했어요. [오후]까지 [증세]가 나아지지 [않으면|않다] [병원]에 가래요. 다행히 [저녁]에는 [조금] [괜찮아졌어요|괜찮다].","z":"昨天晚上吃了不好吃的魚，吃壞肚子了。整晚肚子痛，沒睡好。早上去藥局買了消化藥。藥師說今天只吃粥，不要喝冰水。說如果到下午症狀還沒好轉就去醫院。幸好到晚上就好一點了。","q":[{"q":"약사는 무엇을 먹으라고 했습니까?","c":["죽","생선","찬 물","과일"],"e":"「오늘은 죽만 먹고」。","qt":"藥師叫他吃什麼？"},{"q":"이 사람은 저녁에 어땠습니까?","c":["조금 괜찮아졌습니다","병원에 입원했습니다","더 아팠습니다","생선을 먹었습니다"],"e":"「저녁에는 조금 괜찮아졌어요」。","qt":"這個人晚上怎麼樣？"}],"lv":2},{"id":"r148","t":"입원","tz":"住院","k":"[아버지]가 [허리]를 [다치셔서|다치다] [병원]에 [입원하셨어요|입원하다]. 수술은 [안] 해도 [되지만|되다] [이틀] [동안] [병원]에 [계셔야|계시다] 한대요. [어머니]와 제가 번갈아 [아버지]를 [모셨어요|모시다]. [아버지]는 [병원]에서 [잘] [주무시지|주무시다] 못하셨어요. [밤]에 [다른|다르다] [환자]들이 [떠들어서|떠들다] [시끄러웠대요|시끄럽다]. 퇴원하는 [날] [아버지]는 \"[집]이 [최고]야.\" 하고 웃으셨어요.","z":"爸爸傷到腰，住院了。聽說不用動手術，但要在醫院待兩天。媽媽和我輪流照顧爸爸。爸爸在醫院睡不好。聽說晚上其他病人很吵。出院那天，爸爸笑著說「還是家裡最好」。","q":[{"q":"아버지는 며칠 동안 병원에 계셨습니까?","c":["이틀","사흘","일주일","하루"],"e":"「이틀 동안 병원에 계셔야 한대요」。","qt":"爸爸在醫院待了幾天？"},{"q":"아버지가 잘 주무시지 못한 이유는?","c":["다른 환자들이 떠들어서","허리가 아파서","침대가 불편해서","배가 고파서"],"e":"「다른 환자들이 떠들어서 시끄러웠대요」。","qt":"爸爸睡不好的原因是？"}],"lv":2},{"id":"r149","t":"한국 사람의 일상생활","tz":"韓國人的日常生活","k":"[한국사람]의 [일상생활]은 [어떻습니까]? [주로] [아침] [일찍] [출근하고|출근하다] [저녁] 늦게 [퇴근해요|퇴근하다]. [회사원]들은 [점심]을 동료들과 [같이] 먹고 [가끔] [저녁]에 [맥주]를 마셔요. [주부]들은 [집]에서 [청소하고|청소하다] [빨래]를 해요. [주말]에는 [가족]과 [함께] [쇼핑]을 하거나 [산]에 가요. [요즘]은 [혼자] [사는|살다] [사람]도 [많아져서|많다] [생활]이 다양해요.","z":"韓國人的日常生活是什麼樣子呢？主要是一早上班，晚上很晚才下班。上班族和同事一起吃午餐，偶爾晚上喝啤酒。家庭主婦在家打掃、洗衣服。週末和家人一起購物或去爬山。最近一個人住的人也變多了，所以生活很多樣。","q":[{"q":"주부들은 집에서 무엇을 합니까?","c":["청소하고 빨래를 합니다","회사에 갑니다","맥주를 마십니다","산에 갑니다"],"e":"「주부들은 집에서 청소하고 빨래를 해요」。","qt":"家庭主婦在家做什麼？"},{"q":"요즘 생활이 다양해진 이유는?","c":["혼자 사는 사람이 많아져서","회사가 많아져서","주말이 길어져서","쇼핑을 많이 해서"],"e":"「혼자 사는 사람도 많아져서 생활이 다양해요」。","qt":"最近生活變得多樣的原因是？"}],"lv":2},{"id":"r150","t":"경기장에서","tz":"在體育場","k":"[어제] [친구]와 [야구] [경기장]에 갔어요. [표]는 [한] [장]에 [만] 오천 [원]이었어요. [우리] [팀] [운동선수]들이 [나오자|나오다] [사람]들이 [일어서서|일어서다] [박수]를 [쳤어요|치다]. [경기]가 [시작되자|시작되다] [모두] [노래]를 [부르고|부르다] [소리]를 질렀어요. [구] 회 [말]에 우리 팀이 이겨서 [정말] [즐거웠어요|즐겁다]. [경기]가 [끝나고|끝나다] [사람]들이 [한번]에 [나가서|나가다] [지하철역]이 [복잡했어요|복잡하다].","z":"昨天和朋友去了棒球場。票一張一萬五千韓元。我們隊的運動員一出場，大家就站起來拍手。比賽一開始，大家就唱歌、大聲喊叫。九局下半我們隊贏了，真的很開心。比賽結束後人們一次全部離場，地鐵站非常擁擠。","q":[{"q":"표는 얼마였습니까?","c":["한 장에 만 오천 원","한 장에 만 원","두 장에 만 오천 원","무료"],"e":"「표는 한 장에 만 오천 원이었어요」。","qt":"票多少錢？"},{"q":"경기가 끝나고 지하철역이 복잡했던 이유는?","c":["사람들이 한번에 나가서","지하철이 고장 나서","비가 와서","역이 작아서"],"e":"「사람들이 한번에 나가서 지하철역이 복잡했어요」。","qt":"比賽結束後地鐵站擁擠的原因是？"}],"lv":2},{"id":"r151","t":"사진 촬영","tz":"拍照","k":"[학교] [행사]에서 [사진]을 [촬영하는|촬영하다] [일]을 맡았어요. [카메라]와 [필름]을 [준비하고|준비하다] [일찍] [출발했어요|출발하다]. [행사]장 [위치]를 [미리] [확인해서|확인하다] [늦지|늦다] [않았어요|않다]. [학생]들이 [남녀]로 [나눠서|나누다] [줄]을 [섰어요|서다]. \"[자], [웃으세요|웃다]!\" [조용히] [있던|있다] [아이]들도 [모두] [웃었어요|웃다]. [사진]이 [잘] 나와서 [선생님]이 칭찬해 주셨어요.","z":"在學校活動上負責拍照。準備好相機和底片後很早就出發了。事先確認了活動場地的位置，所以沒有遲到。學生們分成男生女生排好隊。「來，請笑一個！」原本安靜的孩子們也都笑了。照片拍得很好，老師稱讚了我。","q":[{"q":"이 사람이 늦지 않은 이유는?","c":["행사장 위치를 미리 확인해서","택시를 타서","가까워서","친구가 데려다줘서"],"e":"「행사장 위치를 미리 확인해서 늦지 않았어요」。","qt":"這個人沒有遲到的原因是？"},{"q":"학생들은 어떻게 줄을 섰습니까?","c":["남녀로 나눠서","키 순서대로","반별로","나이 순서대로"],"e":"「학생들이 남녀로 나눠서 줄을 섰어요」。","qt":"學生們怎麼排隊？"}],"lv":2},{"id":"r152","t":"실수","tz":"失誤","k":"[오늘] [회사]에서 [큰|크다] [실수]를 했어요. [부장]님께 [드릴|드리다] [서류]에 숫자를 [틀리게|틀리다] 썼어요. [사십]을 사백으로, [칠십]을 칠백으로 [잘못] 썼어요. [부장]님이 [조금] [화나셨지만|화나다] [다시] [고칠|고치다] 수 있게 해 주셨어요. 저는 [무척] [미안해서|미안하다] \"다시는 [실수]하지 [않겠습니다|않다].\" 하고 [말씀드렸어요|말씀]. [앞]으로는 [끝]까지 [잘] [확인해야겠어요|확인하다].","z":"今天在公司犯了一個大錯。在要交給部長的文件上寫錯了數字。把四十誤寫成四百，七十誤寫成七百。部長有點生氣，但讓我重新改正。我非常抱歉，跟部長說：「我不會再犯錯了。」以後要確認到最後。","q":[{"q":"이 사람은 무엇을 잘못 썼습니까?","c":["숫자","이름","날짜","주소"],"e":"「서류에 숫자를 틀리게 썼어요」。","qt":"這個人寫錯了什麼？"},{"q":"부장님은 어떻게 했습니까?","c":["다시 고칠 수 있게 해 주셨습니다","크게 화를 내셨습니다","직접 고치셨습니다","아무 말도 안 하셨습니다"],"e":"「조금 화나셨지만 다시 고칠 수 있게 해 주셨어요」。","qt":"部長怎麼做了？"}],"lv":2},{"id":"r153","t":"비행장 옆 마을","tz":"機場旁的村子","k":"우리 [할머니] [댁]은 [비행장] [근처] [지방]에 있어요. [하루]에도 [여러] 번 [비행기]가 [낮게|낮다] [날아가서|날다] [소리]가 [아주] 커요. [창문]이 흔들리고 [유리]가 [깨질|깨지다] 것 같을 때도 있어요. [처음] [가는|가다] [사람]은 [깜짝] [놀라요|놀라다]. [하지만] [할머니]는 \"[이제] [괜찮아|괜찮다]. [오래] [살아서|살다] [잊어버렸어|잊어버리다].\" 하고 [말씀하세요|말씀하다]. [공기]가 [맑고|맑다] [자연]이 [아름다워서|아름답다] [할머니]는 [그곳]을 [좋아하세요|좋아하다].","z":"我奶奶家在機場附近的地方。一天之內飛機好幾次低空飛過，聲音非常大。有時候窗戶會搖晃，玻璃好像要碎掉一樣。第一次去的人會嚇一跳。但是奶奶說：「現在沒關係了。住久了就忘了。」空氣清新、自然很美，所以奶奶很喜歡那裡。","q":[{"q":"할머니 댁에서 무엇이 문제입니까?","c":["비행기 소리가 큽니다","공기가 나쁩니다","교통이 불편합니다","집이 작습니다"],"e":"「비행기가 낮게 날아가서 소리가 아주 커요」。","qt":"奶奶家有什麼問題？"},{"q":"할머니가 그곳을 좋아하시는 이유는?","c":["공기가 맑고 자연이 아름다워서","비행기를 좋아하셔서","시내가 가까워서","친구가 많아서"],"e":"「공기가 맑고 자연이 아름다워서」。","qt":"奶奶喜歡那裡的原因是？"}],"lv":3},{"id":"r154","t":"자기소개 발표","tz":"自我介紹發表","k":"[오늘] [한국어] [수업]에서 [자기] [소개]를 했어요. \"[안녕]하세요. 제 [이름]은 다나카예요. 저는 [일본사람]이에요. 오사카에서 [왔어요|오다]. [제가] [한국]에 온 [이유]는 한국 [문화]를 [좋아하기|좋아하다] [때문]이에요. [특별히] [한국] [배우]와 [스타]들을 [좋아해요|좋아하다]. 제 [꿈]은 [나중]에 통역사가 되는 [것]이에요.\" [발표]가 [끝나고|끝나다] [친구]들이 [박수]를 [쳐|치다] 줬어요.","z":"今天在韓語課上做了自我介紹。「大家好。我叫田中。我是日本人。我從大阪來。我來韓國的原因是因為喜歡韓國文化。特別喜歡韓國演員和明星。我的夢想是以後成為口譯員。」發表結束後朋友們為我拍手。","q":[{"q":"이 사람이 한국에 온 이유는?","c":["한국 문화를 좋아해서","한국 회사에 취직해서","가족이 한국에 있어서","한국 음식을 좋아해서"],"e":"「한국 문화를 좋아하기 때문이에요」。","qt":"這個人來韓國的原因是？"},{"q":"이 사람의 꿈은?","c":["통역사","배우","선생님","가수"],"e":"「제 꿈은 나중에 통역사가 되는 것이에요」。","qt":"這個人的夢想是？"}],"lv":3},{"id":"r155","t":"공중전화","tz":"公共電話","k":"[옛날]에는 [거리]에 [공중전화]가 [많았어요|많다]. [동전]을 넣고 [번호]를 [누르면|누르다] [전화]를 [걸|걸다] 수 있었어요. [전화]를 [오래] 하면 [동전]이 [금방] [떨어져서|떨어지다] [더] 넣어야 했어요. [요즘]은 [모두] [핸드폰]을 [가지고|가지다] 있어서 [공중전화]를 [이용하는|이용하다] [사람]이 [거의] [없어요|없다]. [그래서] [공중전화]의 [수]가 [많이] [줄었어요|줄다]. [하지만] [핸드폰]이 [없을|없다] 때를 [위해서|위하다] [아직] 남아 있어요.","z":"以前街上有很多公共電話。放入硬幣、按下號碼就能打電話。講電話講久了，硬幣很快就用完，得再投。最近大家都有手機，所以幾乎沒有人用公共電話。所以公共電話的數量減少了很多。但是為了沒有手機的時候，現在還留著。","q":[{"q":"공중전화가 줄어든 이유는?","c":["모두 핸드폰이 있어서","동전이 없어서","고장이 나서","요금이 비싸서"],"e":"「모두 핸드폰을 가지고 있어서 이용하는 사람이 거의 없어요」。","qt":"公共電話減少的原因是？"},{"q":"옛날에 전화를 오래 하면 어떻게 됐습니까?","c":["동전이 금방 떨어졌습니다","전화가 끊어지지 않았습니다","무료였습니다","번호를 다시 눌렀습니다"],"e":"「동전이 금방 떨어져서 더 넣어야 했어요」。","qt":"以前講電話講很久會怎麼樣？"}],"lv":2},{"id":"r156","t":"동양과 서양","tz":"東方和西方","k":"[동양]과 [서양]은 [식사]하는 [방법]이 [달라요|다르다]. [동양]에서는 [주로] [젓가락]을 [쓰고|쓰다] [서양]에서는 [칼]과 포크를 [써요|쓰다]. [한국]에서는 [어른]이 [먼저] [드시기|드시다] [전]에 [식사]를 [시작하지|시작하다] 않아요. [밥]을 먹을 때 [소리]를 내면서 [씹는|씹다] [것]은 예의가 [아니에요|아니다]. [나라]마다 [문화]가 [다르니까|다르다] [여행]하기 [전]에 [알아|알다] 두면 [좋아요|좋다].","z":"東方和西方用餐的方式不同。東方主要用筷子，西方用刀叉。在韓國，長輩開動前不會先開始吃。吃飯時發出聲音咀嚼是不禮貌的。每個國家的文化都不同，所以旅行前先了解會比較好。","q":[{"q":"한국에서 식사할 때 예의가 아닌 것은?","c":["소리를 내면서 씹는 것","어른이 먼저 드시는 것","젓가락을 쓰는 것","천천히 먹는 것"],"e":"「소리를 내면서 씹는 것은 예의가 아니에요」。","qt":"在韓國用餐時不禮貌的是？"},{"q":"서양에서 식사할 때 쓰는 것은?","c":["칼과 포크","젓가락","숟가락만","손"],"e":"「서양에서는 칼과 포크를 써요」。","qt":"在西方用餐時用什麼？"}],"lv":1},{"id":"r157","t":"뉴욕 여행","tz":"紐約旅行","k":"[다음해] [봄]에 [뉴욕]으로 [여행]을 가고 [싶어요|싶다]. [남미]에도 가고 [싶지만|싶다] [너무] [멀어서|멀다] [우선] [뉴욕]만 [다녀오려고|다녀오다] 해요. [뉴욕]에는 [유명한|유명하다] [미술관]과 [공연]장이 [많대요|많다]. [거기]에서 [유명한|유명하다] [음악가]의 [공연]을 [구경]하고 [싶어요|싶다]. [여행]하려면 [돈]을 [벌어야|벌다] 해서 [요즘] [열심히] [일하고|일하다] 있어요. [여행]을 [원하는|원하다] 만큼 [일]도 [열심히] 해요.","z":"明年春天想去紐約旅行。也想去南美，但太遠了，所以打算先只去紐約。聽說紐約有很多有名的美術館和表演場地。想在那裡欣賞有名音樂家的表演。要旅行就得賺錢，所以最近很努力工作。想旅行多少，就多努力工作。","q":[{"q":"이 사람은 왜 남미에 가지 않습니까?","c":["너무 멀어서","돈이 없어서","위험해서","친구가 없어서"],"e":"「남미에도 가고 싶지만 너무 멀어서」。","qt":"這個人為什麼不去南美？"},{"q":"뉴욕에서 하고 싶은 것은?","c":["유명한 음악가의 공연 구경","쇼핑","친구 만나기","영어 공부"],"e":"「유명한 음악가의 공연을 구경하고 싶어요」。","qt":"在紐約想做什麼？"}],"lv":2},{"id":"r158","t":"종로와 대사관","tz":"鍾路與大使館","k":"[종로]는 [서울]의 [중심]에 있어요. [종로] [주위]에는 [옛날] [건물]과 [새] [빌딩]이 [같이] 있어요. [여러] 나라의 [대사관]도 [이] [근처]에 있어요. 비자를 [받으러|받다] [대사관]에 가는 [외국인]이 [많아요|많다]. [종로]에서 [버스] [정거장]과 [터미널]까지는 [가까워서|가깝다] [교통]이 편리해요. [저곳]에 있는 [큰|크다] [서점]에는 [여러] [종류]의 [책]이 있어서 [자주] 가요.","z":"鍾路在首爾的中心。鍾路周圍古老建築和新大樓並存。許多國家的大使館也在這附近。很多外國人去大使館辦簽證。從鍾路到公車站和轉運站都很近，交通很方便。那邊的大書店有各式各樣的書，所以我常去。","q":[{"q":"종로 근처에 있는 것은?","c":["여러 나라의 대사관","공항","바다","산"],"e":"「여러 나라의 대사관도 이 근처에 있어요」。","qt":"鍾路附近有什麼？"},{"q":"이 사람이 자주 가는 곳은?","c":["큰 서점","대사관","터미널","빌딩"],"e":"「큰 서점에는 여러 종류의 책이 있어서 자주 가요」。","qt":"這個人常去的地方是？"}],"lv":2},{"id":"r159","t":"독서","tz":"閱讀","k":"제 [취미]는 [독서]예요. [한] [달]에 [책]을 [다섯] [권]씩 [읽어요|읽다]. [소설]도 [좋아하지만|좋아하다] [사업가]나 [과거]의 [유명한|유명하다] [사람]들 [이야기]도 [좋아해요|좋아하다]. [책]을 [펴면|펴다] [다른|다르다] 세상에 있는 [것] 같아요. [좋은|좋다] [문장]은 [수첩]에 [메모]해요. [책]을 [많이] [읽으니까|읽다] [생각]이 깊어지고 [말하기] [능력]도 [좋아졌어요|좋다]. [여러분]도 [독서]를 [해|하다] 보세요.","z":"我的興趣是閱讀。一個月讀五本書。我喜歡小說，也喜歡企業家或過去名人的故事。打開書就好像在另一個世界。好的句子會記在記事本上。書讀得多，想法變得更深，說話能力也變好了。各位也試試看閱讀吧。","q":[{"q":"이 사람은 한 달에 책을 몇 권 읽습니까?","c":["다섯 권","세 권","열 권","한 권"],"e":"「한 달에 책을 다섯 권씩 읽어요」。","qt":"這個人一個月讀幾本書？"},{"q":"좋은 문장은 어떻게 합니까?","c":["수첩에 메모합니다","친구에게 말합니다","외웁니다","사진을 찍습니다"],"e":"「좋은 문장은 수첩에 메모해요」。","qt":"好的句子怎麼處理？"}],"lv":3},{"id":"r37","t":"김치찌개 만들기","tz":"做泡菜鍋","k":"[오늘]은 [제가] [김치찌개]를 [만들었어요|만들다]. [먼저] [돼지고기]와 [김치]를 [기름]에 [볶았어요|볶다]. [그리고] [냄비]에 [물]을 [넣고|넣다] [끓였어요|끓이다]. [두부]와 [양파], [파]를 [썰어서|썰다] 넣었어요. [마지막]에 [고추장]을 [조금] 넣었어요. [맛]을 보니까 [조금] [싱거워서|싱겁다] [소금]을 넣었어요. [가족]들이 [맛있게|맛있다] [먹었어요|먹다].","z":"今天我做了泡菜鍋。首先用油炒豬肉和泡菜。然後在鍋子裡加水煮滾。把豆腐、洋蔥和蔥切一切放進去。最後加了一點辣椒醬。嚐了味道有點淡，所以加了鹽。家人們吃得很開心。","q":[{"q":"처음에 무엇을 했습니까?","c":["돼지고기와 김치를 볶았습니다","물을 끓였습니다","두부를 썰었습니다","소금을 넣었습니다"],"e":"「먼저 돼지고기와 김치를 기름에 볶았어요」。","qt":"一開始做了什麼？"},{"q":"소금을 왜 넣었습니까?","c":["싱거워서","짜서","매워서","달아서"],"e":"「조금 싱거워서 소금을 넣었어요」。","qt":"為什麼加了鹽？"}],"lv":3},{"id":"r38","t":"한국 반찬","tz":"韓國小菜","k":"[한국] [식당]에 가면 [반찬]이 [많이] 나와요. [김치]뿐만 아니라 [콩], [감자], [오이], [무]로 만든 반찬도 있어요. [대부분] [공짜]라서 더 달라고 해도 돼요. 저는 [계란]으로 만든 반찬을 [제일] [좋아해요|좋아하다]. [반찬]은 [짜거나|짜다] [매운|맵다] 것이 [많아서|많다] [쌀밥]과 같이 먹어요. [처음]에는 [놀랐지만|놀라다] 지금은 익숙해요.","z":"去韓國餐廳會端上很多小菜。不只泡菜，還有用豆子、馬鈴薯、小黃瓜、白蘿蔔做的小菜。大部分是免費的，所以再要也可以。我最喜歡用雞蛋做的小菜。小菜很多是鹹的或辣的，所以要配白飯吃。一開始很驚訝，現在已經習慣了。","q":[{"q":"한국 식당의 반찬은 어떻습니까?","c":["대부분 공짜입니다","모두 비쌉니다","김치만 있습니다","더 먹을 수 없습니다"],"e":"「대부분 공짜라서 더 달라고 해도 돼요」。","qt":"韓國餐廳的小菜怎麼樣？"},{"q":"이 사람이 제일 좋아하는 반찬은?","c":["계란으로 만든 반찬","김치","콩으로 만든 반찬","오이로 만든 반찬"],"e":"「계란으로 만든 반찬을 제일 좋아해요」。","qt":"這個人最喜歡的小菜是？"}],"lv":2},{"id":"r39","t":"과일 가게","tz":"水果店","k":"[집] [앞] [과일] [가게]에는 [계절]마다 [다른|다르다] 과일이 있어요. [봄]에는 [딸기]가 [많고|많다] [여름]에는 [수박]과 [복숭아]가 [맛있어요|맛있다]. [가을]에는 [사과], [배], [감], [포도]를 [팔아요|팔다]. [겨울]에는 [제주도] [귤]이 [인기]가 [많아요|많다]. [바나나]와 [오렌지]는 일 년 내내 있어요. [주인] [아주머니]가 [친절해서|친절하다] [자주] 가요.","z":"家門前的水果店每個季節有不同的水果。春天草莓很多，夏天西瓜和桃子很好吃。秋天賣蘋果、梨子、柿子、葡萄。冬天濟州島的橘子很受歡迎。香蕉和柳橙一整年都有。老闆娘很親切，所以常去。","q":[{"q":"여름에 맛있는 과일은?","c":["수박과 복숭아","딸기","귤","사과와 배"],"e":"「여름에는 수박과 복숭아가 맛있어요」。","qt":"夏天好吃的水果是？"},{"q":"이 사람이 이 가게에 자주 가는 이유는?","c":["주인이 친절해서","과일이 싸서","집에서 멀어서","귤이 맛있어서"],"e":"「주인 아주머니가 친절해서 자주 가요」。","qt":"這個人常去這家店的理由是？"}],"lv":2},{"id":"r160","t":"연극 대회","tz":"話劇比賽","k":"[십일월]에 [학교]에서 연극 [대회]가 [있었어요|있다]. 우리 [반]은 [한국] [옛날] [이야기]를 [준비했어요|준비하다]. 저는 [소]를 키우는 [착한|착하다] [남자] 역할을 맡았어요. [여학생]들은 [곱게|곱다] [한복]을 [입었어요|입다]. [연습]이 [힘들었지만|힘들다] [대회] [날] 관객들이 [감동]했어요. [결과]는 [이] [등]이었지만 [모두] [기뻤어요|기쁘다]. [이때]의 [추억]은 [잊을|잊다] 수 없을 거예요.","z":"十一月學校舉辦了話劇比賽。我們班準備了一個韓國古老的故事。我演一個養牛的善良男人。女學生們穿上了漂亮的韓服。練習很辛苦，但比賽當天觀眾都很感動。結果是第二名，但是大家都很開心。這時候的回憶一定忘不了。","q":[{"q":"대회 결과는?","c":["이 등","일 등","삼 등","상을 못 받았습니다"],"e":"「결과는 이 등이었지만」。","qt":"比賽結果是？"},{"q":"이 사람은 무슨 역할을 했습니까?","c":["소를 키우는 착한 남자","소","옛날 왕","선생님"],"e":"「소를 키우는 착한 남자 역할을 맡았어요」。","qt":"這個人演什麼角色？"}],"lv":3},{"id":"r161","t":"감기약","tz":"感冒藥","k":"[겨울]이 되면 [감기]에 [걸리는|걸리다] [사람]이 [많아요|많다]. [감기]에 걸리면 [가슴]이 답답하고 [코피]가 나기도 해요. [약국]에서 [감기약]을 살 때는 [약사]의 [설명]을 [잘] 들어야 해요. [감기약]은 [식사] [후]에 먹는 것이 [알맞아요|알맞다]. [감기]가 [심하면|심하다] [약]뿐만 아니라 [병원]에 가는 것이 [필요]해요. [따뜻한|따뜻하다] [물]을 [많이] 마시고 [푹] [잠자는|잠자다] 것도 [중요]해요.","z":"到了冬天，得感冒的人很多。感冒的話胸口會悶，有時候還會流鼻血。在藥局買感冒藥時要好好聽藥師的說明。感冒藥適合在飯後吃。感冒嚴重的話，不只是吃藥，也需要去醫院。多喝熱水、好好睡覺也很重要。","q":[{"q":"감기약은 언제 먹는 것이 알맞습니까?","c":["식사 후","식사 전","자기 전","아침에만"],"e":"「감기약은 식사 후에 먹는 것이 알맞아요」。","qt":"感冒藥什麼時候吃比較適合？"},{"q":"감기에 걸렸을 때 중요한 것은?","c":["따뜻한 물을 마시고 푹 잡니다","운동을 합니다","찬 물을 마십니다","약만 먹습니다"],"e":"「따뜻한 물을 많이 마시고 푹 잠자는 것도 중요해요」。","qt":"感冒時重要的是什麼？"}],"lv":2},{"id":"r162","t":"인상 깊은 여행","tz":"印象深刻的旅行","k":"[가장] [인상] 깊은 [여행]은 [작년] [가을]에 [친구]와 [부산]을 [여행한|여행하다] [것]이에요. [해]가 [지는|지다] [바다]를 보면서 [콧노래]를 [불렀어요|부르다]. [낮]에는 [시장]에서 [생선] [요리]를 먹고 관광지를 [구경]했어요. [부산]은 [사람]들이 [친절하고|친절하다] [음식]이 [맛있어서|맛있다] [다시] [찾아오고|찾아오다] [싶어요|싶다]. [그런] [여행]을 [또] 하고 [싶어요|싶다].","z":"印象最深刻的旅行是去年秋天和朋友去釜山旅行。一邊看著夕陽西下的大海一邊哼歌。白天在市場吃了魚料理，參觀了觀光景點。釜山的人很親切，食物也很好吃，所以還想再來。想再有那樣的旅行。","q":[{"q":"이 사람은 바다를 보면서 무엇을 했습니까?","c":["콧노래를 불렀습니다","수영을 했습니다","사진을 찍었습니다","생선을 먹었습니다"],"e":"「해가 지는 바다를 보면서 콧노래를 불렀어요」。","qt":"這個人看著大海時做了什麼？"},{"q":"부산에 다시 오고 싶은 이유는?","c":["사람들이 친절하고 음식이 맛있어서","가족이 있어서","바다에서 수영하려고","일이 있어서"],"e":"「사람들이 친절하고 음식이 맛있어서」。","qt":"想再來釜山的原因是？"}],"lv":1},{"id":"r163","t":"개인 공간","tz":"個人空間","k":"[사람]마다 [개인] [공간]이 [필요]해요. [동생]과 [같은|같다] [방]을 [쓸|쓰다] 때 [가끔] [싸웠어요|싸우다]. [동생]이 제 [물건]을 [만지면|만지다] [싫었어요|싫다]. [그래서] [부모님]이 [방] [가운데]에 [가구]를 [놓아서|놓다] [방]을 [둘]로 [나눠|나누다] 주셨어요. [이제]는 각자 [공간]이 있어서 [싸우지|싸우다] [않아요|않다]. [벽]에 [좋아하는|좋아하다] [사진]도 [붙였어요|붙이다].","z":"每個人都需要個人空間。和弟弟用同一間房間時，偶爾會吵架。弟弟一碰我的東西我就討厭。所以父母在房間中間放了家具，把房間分成兩半。現在各自有空間了，就不吵架了。牆上也貼了喜歡的照片。","q":[{"q":"부모님은 어떻게 해 주셨습니까?","c":["가구로 방을 둘로 나눠 주셨습니다","새 방을 만들어 주셨습니다","동생을 혼내셨습니다","이사를 하셨습니다"],"e":"「방 가운데에 가구를 놓아서 방을 둘로 나눠 주셨어요」。","qt":"父母怎麼做了？"},{"q":"이 사람이 싫었던 것은?","c":["동생이 물건을 만지는 것","방이 작은 것","가구가 없는 것","사진을 붙이는 것"],"e":"「동생이 제 물건을 만지면 싫었어요」。","qt":"這個人討厭的是？"}],"lv":2},{"id":"r164","t":"오래된 비디오","tz":"老錄影帶","k":"창고를 [정리하다가|정리하다] 오래된 [비디오]와 [디브이디]를 [찾았어요|찾다]. [상자] [속]에 먼지가 [쌓여|쌓이다] 있었어요. [비디오]에는 제가 [애]였을 [때]의 [영상]이 있었어요. [아빠]가 [찍어|찍다] 주신 [거]예요. [영상] [속]의 저는 [공]을 [가지고|가지다] 놀고 있었어요. [가족]이 [모두] [모여서|모이다] [보면서|보다] [많이] [웃었어요|웃다]. [그때]가 그리워요.","z":"整理倉庫時找到了老錄影帶和 DVD。箱子裡積了灰塵。錄影帶裡有我還是小孩時的影片。是爸爸幫我拍的。影片裡的我正拿著球在玩。全家人聚在一起邊看邊笑了很多。好懷念那時候。","q":[{"q":"비디오에는 무엇이 있었습니까?","c":["이 사람이 어렸을 때의 영상","영화","결혼식 영상","음악"],"e":"「제가 애였을 때의 영상이 있었어요」。","qt":"錄影帶裡有什麼？"},{"q":"영상은 누가 찍었습니까?","c":["아빠","엄마","형","할아버지"],"e":"「아빠가 찍어 주신 거예요」。","qt":"影片是誰拍的？"}],"lv":3},{"id":"r165","t":"홈페이지","tz":"網站","k":"우리 [동아리]는 [홈페이지]를 [만들었어요|만들다]. [홈페이지]에서 활동 [사진]과 [모임] [날짜]를 볼 수 있어요. [새] 회원을 [초대]하는 [글]도 [썼어요|쓰다]. [처음] [페이지]에는 [동아리] [소개]와 [연락처]가 있어요. [홈페이지]를 [이용]하는 [사람]이 [늘어서|늘다] 회원이 [오십] [명]이 넘었어요. [현재] [육십] [명]이 [되는|되다] 것을 [바라고|바라다] 있어요.","z":"我們社團做了一個網站。在網站上可以看到活動照片和聚會日期。也寫了邀請新會員的文章。首頁有社團介紹和聯絡方式。使用網站的人變多了，會員超過了五十人。現在希望能達到六十人。","q":[{"q":"첫 페이지에 있는 것은?","c":["동아리 소개와 연락처","활동 사진","모임 날짜","회원 이름"],"e":"「처음 페이지에는 동아리 소개와 연락처가 있어요」。","qt":"首頁有什麼？"},{"q":"동아리 회원은 지금 몇 명이 넘었습니까?","c":["오십 명","육십 명","사십 명","백 명"],"e":"「회원이 오십 명이 넘었어요」。","qt":"社團會員現在超過幾人？"}],"lv":2},{"id":"r166","t":"김치 담그기","tz":"醃泡菜","k":"[겨울]이 오기 [전]에 [가족]이 [모여서|모이다] [김치]를 [담가요|담그다]. 배추의 [양]이 [많아서|많다] [하루] [종일] [걸려요|걸리다]. [할머니]가 [먼저] [설명]을 해 주시고 [우리]는 [따라|따르다] 해요. [고추]가루를 [붓고|붓다] [손]으로 [잘] 섞어요. [김치]가 [너무] [시면|시다] [찌개]를 [만들어|만들다] 먹어요. [김치]를 [담그는|담그다] [날]은 [힘들지만|힘들다] [가족]의 [사랑]을 [느낄|느끼다] 수 있어요.","z":"冬天來臨前，家人會聚在一起醃泡菜。白菜的量很多，所以要花一整天。奶奶會先說明，我們就跟著做。倒入辣椒粉，用手好好拌勻。泡菜太酸的話就煮成鍋物來吃。醃泡菜的日子雖然很累，但能感受到家人的愛。","q":[{"q":"김치가 너무 시면 어떻게 합니까?","c":["찌개를 만들어 먹습니다","버립니다","다시 담급니다","설탕을 넣습니다"],"e":"「김치가 너무 시면 찌개를 만들어 먹어요」。","qt":"泡菜太酸時怎麼辦？"},{"q":"김치를 담글 때 누가 설명해 줍니까?","c":["할머니","어머니","이 사람","이웃"],"e":"「할머니가 먼저 설명을 해 주시고」。","qt":"醃泡菜時誰來說明？"}],"lv":2},{"id":"r167","t":"금연과 금주","tz":"戒菸和戒酒","k":"[삼촌]은 [올해]부터 [금연]과 [금주]를 [시작]했어요. [담배]를 [피우면|피우다] [건강]에 [안] [좋다고|좋다] [의사] 선생님이 [말씀하셨대요|말씀하다]. [처음]에는 [힘들어서|힘들다] [껌]을 [씹었대요|씹다]. [삼촌]은 \"[담배]를 [그만] [피우니까|피우다] [몸]이 [가벼워졌어|가볍다].\" 하고 [말했어요|말하다]. [술]을 [안] 마시니까 [돈]도 [많이] 모았대요. [가족]들은 [삼촌]이 자랑스러워요.","z":"叔叔從今年開始戒菸和戒酒。聽說醫生說抽菸對健康不好。一開始很辛苦，所以嚼口香糖。叔叔說：「不抽菸之後身體變輕鬆了。」聽說不喝酒也存了很多錢。家人們都為叔叔感到驕傲。","q":[{"q":"삼촌은 처음에 힘들 때 무엇을 했습니까?","c":["껌을 씹었습니다","운동을 했습니다","물을 마셨습니다","잠을 잤습니다"],"e":"「처음에는 힘들어서 껌을 씹었대요」。","qt":"叔叔一開始覺得辛苦時做了什麼？"},{"q":"술을 안 마시니까 어떻게 됐습니까?","c":["돈을 많이 모았습니다","살이 쪘습니다","친구가 없어졌습니다","잠을 못 잤습니다"],"e":"「술을 안 마시니까 돈도 많이 모았대요」。","qt":"不喝酒之後怎麼樣了？"}],"lv":2},{"id":"r168","t":"무엇이 문제예요?","tz":"什麼問題？","k":"\"[누가] 이 [문]을 [닫았어요|닫다]?\" \"[내가] [닫았는데|닫다] 왜요?\" \"[바람]이 [불어서|불다] [문]이 저절로 [닫혔어요|닫히다]. [그런데] [열쇠]가 [안]에 있어요.\" \"[어], [그거] [문제]네요. [어느] [쪽] [창문]이 [열려|열리다] 있어요?\" \"[모르겠습니다]. [그쪽]으로 [가서|가다] [봐|보다] 주세요.\" \"[찾았어요|찾다]! [저쪽] [창문]으로 [들어갈|들어가다] 수 있어요.\"","z":"「誰把這扇門關上了？」「是我關的，怎麼了？」「風一吹門就自己關上了。可是鑰匙在裡面。」「咦，那可就麻煩了。哪一邊的窗戶開著？」「我不知道。請你到那邊去看看。」「找到了！可以從那邊的窗戶進去。」","q":[{"q":"무엇이 문제입니까?","c":["열쇠가 안에 있는데 문이 닫혔습니다","창문이 고장 났습니다","바람이 너무 붑니다","열쇠를 잃어버렸습니다"],"e":"「문이 닫혔어요. 그런데 열쇠가 안에 있어요」。","qt":"問題是什麼？"},{"q":"어떻게 들어갈 수 있습니까?","c":["저쪽 창문으로","문을 부숴서","열쇠를 사서","들어갈 수 없습니다"],"e":"「저쪽 창문으로 들어갈 수 있어요」。","qt":"怎麼進得去？"}],"lv":1},{"id":"r169","t":"우리 형","tz":"我哥哥","k":"[형]은 [대학원생]이고 [자동차회사]에서 연구도 해요. [전공]은 [자동차]의 [발전]과 안전에 대한 [공부]예요. [형]은 [아버지]와 [많이] [닮았어요|닮다]. [키]가 [백] [팔십] [센티미터]이고 [목소리]도 [같아요|같다]. [형]은 [일]이 [많아서|많다] [늘] [바빠요|바쁘다]. 그래도 [주말]에는 [나]와 [놀아|놀다] 줘요. [형]처럼 [자신]의 [일]을 [사랑하는|사랑하다] [사람]이 되고 싶어요.","z":"哥哥是研究生，也在汽車公司做研究。主修的是汽車的發展和安全。哥哥和爸爸長得很像。身高一百八十公分，聲音也一樣。哥哥工作很多，總是很忙。即使這樣，週末還是會陪我玩。我想成為像哥哥一樣熱愛自己工作的人。","q":[{"q":"형은 누구와 닮았습니까?","c":["아버지","어머니","이 사람","할아버지"],"e":"「형은 아버지와 많이 닮았어요」。","qt":"哥哥長得像誰？"},{"q":"형의 키는?","c":["백팔십 센티미터","백칠십 센티미터","백구십 센티미터","백육십 센티미터"],"e":"「키가 백 팔십 센티미터이고」。","qt":"哥哥的身高是？"}],"lv":3},{"id":"r170","t":"달리기 대회","tz":"跑步比賽","k":"[모레]는 [구] [킬로미터]를 [달리는|달리다] [대회]가 있는 [날]이에요. [출발]은 [아침] [일곱] 시예요. 저는 달리기가 [느린|느리다] [편]이지만 [끝]까지 [달리는|달리다] 것이 목표예요. [대회]에 [필요한|필요하다] [물]과 [수건], [타월]을 [가방]에 넣었어요. [비]가 오면 [대회]가 취소될 수도 있대요. [날씨]가 [좋기를|좋다] [바라요|바라다].","z":"後天是有九公里跑步比賽的日子。早上七點出發。我屬於跑得比較慢的，但目標是跑到終點。把比賽需要的水、手帕和毛巾放進了包包。聽說下雨的話比賽可能會取消。希望天氣會好。","q":[{"q":"대회는 몇 시에 출발합니까?","c":["아침 일곱 시","아침 아홉 시","오후 한 시","저녁 일곱 시"],"e":"「출발은 아침 일곱 시예요」。","qt":"比賽幾點出發？"},{"q":"이 사람의 목표는?","c":["끝까지 달리는 것","일 등 하는 것","빨리 달리는 것","대회를 취소하는 것"],"e":"「끝까지 달리는 것이 목표예요」。","qt":"這個人的目標是？"}],"lv":2},{"id":"r171","t":"인기 탤런트","tz":"人氣演員","k":"[요즘] [가장] [인기] 있는 [탤런트]는 연기를 [참] [잘해요|잘하다]. [그] [사람]이 나오는 [드라마]는 [매주] [화요일]에 [해요|하다]. [드라마]가 [재미없는|재미없다] [날]이 [없어요|없다]. [그] [탤런트]가 [광고]하는 [물건]은 [잘] [팔려요|팔리다]. [그] [사람]이 입은 [옷]도 [금방] [인기]가 [생겨요|생기다]. [저]는 [그] [탤런트]를 [직접] [만나는|만나다] 것이 [꿈]이에요.","z":"最近最受歡迎的演員演技真的很好。他演的電視劇每週二播出。電視劇沒有一天不好看。那位演員代言的東西都賣得很好。他穿的衣服也很快就變得熱門。親眼見到那位演員是我的夢想。","q":[{"q":"드라마는 무슨 요일에 합니까?","c":["화요일","월요일","수요일","금요일"],"e":"「매주 화요일에 해요」。","qt":"電視劇星期幾播？"},{"q":"이 사람의 꿈은?","c":["탤런트를 직접 만나는 것","탤런트가 되는 것","드라마를 만드는 것","광고에 나오는 것"],"e":"「그 탤런트를 직접 만나는 것이 꿈이에요」。","qt":"這個人的夢想是？"}],"lv":2},{"id":"r172","t":"하숙집 친구들","tz":"寄宿家庭的朋友們","k":"저는 [하숙]을 해요. [하숙집]에는 [다른] [나라]에서 온 [학생]들도 [살아요|살다]. [그들]과 [같이] [식사하면서|식사하다] [얘기하는|얘기하다] 시간이 [재미]있어요. [일본] [친구]는 [국어] [선생님]이 되는 게 [꿈]이래요. [미국] [친구]는 [기타]를 [잘] [쳐요|치다]. [저녁]마다 [기타] [소리]가 들려서 [기분]이 좋아요. [우리]는 [서로] [문화]를 [이해]하게 됐어요.","z":"我住在寄宿家庭。寄宿家庭裡也住著從其他國家來的學生。和他們一起吃飯聊天的時間很有趣。日本朋友說夢想是成為國語老師。美國朋友吉他彈得很好。每天晚上都聽得到吉他的聲音，心情很好。我們變得能理解彼此的文化。","q":[{"q":"미국 친구가 잘하는 것은?","c":["기타","피아노","노래","요리"],"e":"「미국 친구는 기타를 잘 쳐요」。","qt":"美國朋友擅長什麼？"},{"q":"일본 친구의 꿈은?","c":["국어 선생님","가수","의사","회사원"],"e":"「일본 친구는 국어 선생님이 되는 게 꿈이래요」。","qt":"日本朋友的夢想是？"}],"lv":3},{"id":"r173","t":"대화 연습","tz":"對話練習","k":"\"이건 [무엇]이에요?\" \"그건 [손수건]이에요.\" \"[이런] [손수건]은 [얼마]예요?\" \"[한] [장]에 삼천 [원]짜리예요. [두] [장]씩 [팔아요|팔다].\" \"[질]은 [어때요|어떻다]?\" \"[아주] [좋아요|좋다]. [빨아도|빨다] [괜찮아요|괜찮다].\" \"그렇습니까? [그럼] [다섯째] [줄]에 있는 걸로 [주세요|주다].\" \"[네], [맞습니다]. [이거] [말씀]이지요?\" \"[아니오], [그] [옆]의 [거]예요.\"","z":"「這是什麼？」「那是手帕。」「這樣的手帕多少錢？」「一條三千韓元。兩條兩條一起賣。」「品質怎麼樣？」「非常好。洗了也沒關係。」「是嗎？那請給我第五排的那個。」「好的，沒錯。您是說這個吧？」「不，是它旁邊那個。」","q":[{"q":"손수건은 얼마입니까?","c":["한 장에 삼천 원","두 장에 삼천 원","한 장에 오천 원","무료"],"e":"「한 장에 삼천 원짜리예요」。","qt":"手帕多少錢？"},{"q":"손님이 원하는 손수건은?","c":["다섯째 줄 옆의 것","다섯째 줄의 것","첫째 줄의 것","가게 밖의 것"],"e":"「아니오, 그 옆의 거예요」。","qt":"客人想要的手帕是？"}],"lv":1},{"id":"r174","t":"우리 동네 시설","tz":"我們社區的設施","k":"우리 [동네]에는 [여러] [시설]이 있어요. [도서관]에서는 [독서하는|독서하다] [사람]들을 [언제나] 볼 수 있어요. [수영장] [옆]에는 [샤워]실도 있어요. [공원]에는 [어린이]들이 [안전하게|안전하다] [놀|놀다] 수 있는 [곳]이 있어요. [하지만] [보도]가 [좁아서|좁다] [조금] [위험]해요. [공원] 쓰레기통과 [휴지통]은 [가끔] [더러워요|더럽다]. 그래도 [이상]한 [점]은 [별로] 없어요.","z":"我們社區有各種設施。在圖書館隨時都能看到在閱讀的人。游泳池旁邊也有淋浴室。公園裡有孩子們可以安全玩耍的地方。但是人行道很窄，所以有點危險。公園的垃圾桶偶爾很髒。即使這樣，奇怪的地方並不多。","q":[{"q":"이 동네의 문제는?","c":["보도가 좁아서 위험합니다","도서관이 없습니다","공원이 없습니다","수영장이 멉니다"],"e":"「보도가 좁아서 조금 위험해요」。","qt":"這個社區的問題是？"},{"q":"수영장 옆에 무엇이 있습니까?","c":["샤워실","도서관","공원","휴지통"],"e":"「수영장 옆에는 샤워실도 있어요」。","qt":"游泳池旁邊有什麼？"}],"lv":3},{"id":"r175","t":"비가 그쳤어요","tz":"雨停了","k":"[어제]는 [종일] [비]가 [왔는데|오다] [오늘] [아침]에 [그쳤어요|그치다]. [벌써] [가을]이라는 [생각]이 [들어요|들다]. [가을]은 [독서]의 [철]이라고 해요. [오늘]은 [월] [요일]이라서 [수업]이 [많아요|많다]. [수업]을 [마치고|마치다] [친구]와 [함께] [공원]을 [걸었어요|걷다]. [친구]가 저를 [따라오면서|따라오다] \"[자유]롭고 [좋다]!\" 하고 [웃었어요|웃다].","z":"昨天下了一整天的雨，今天早上停了。讓人覺得已經是秋天了。人家說秋天是讀書的季節。今天是星期一，所以課很多。上完課後和朋友一起在公園散步。朋友跟在我後面，笑著說：「好自由、好舒服！」","q":[{"q":"비는 언제 그쳤습니까?","c":["오늘 아침","어제 저녁","오늘 오후","어제 아침"],"e":"「오늘 아침에 그쳤어요」。","qt":"雨什麼時候停的？"},{"q":"수업을 마치고 무엇을 했습니까?","c":["친구와 공원을 걸었습니다","도서관에 갔습니다","집에서 잤습니다","책을 샀습니다"],"e":"「수업을 마치고 친구와 함께 공원을 걸었어요」。","qt":"上完課後做了什麼？"}],"lv":2},{"id":"r176","t":"시험에 붙었어요","tz":"考上了","k":"드디어 한국어 [시험] [이] [급]에 [붙었어요|붙다]! [시험] [준비] [중]에는 [친구]도 [못] [만나고|만나다] 공부만 했어요. [발음]이 [어려워서|어렵다] [매일] [삼십] [분]씩 [연습]했어요. [선생님]이 준 [프린트]를 [통해서|통하다] [문제]를 [많이] [풀었어요|풀다]. [합격] [소식]을 [듣고|듣다] [부모님]께 [전화]로 [감사] [인사]를 드렸어요. [다음]에는 [삼] [급]에 도전할 [생각]이에요.","z":"終於考上韓語檢定二級了！準備考試期間連朋友都沒見，只顧著讀書。發音很難，所以每天練習三十分鐘。透過老師給的講義解了很多題目。聽到合格的消息後，打電話向父母道謝。下次打算挑戰三級。","q":[{"q":"이 사람은 발음을 어떻게 연습했습니까?","c":["매일 삼십 분씩","매일 한 시간씩","주말마다","학원에서"],"e":"「매일 삼십 분씩 연습했어요」。","qt":"這個人怎麼練習發音？"},{"q":"다음 목표는 무엇입니까?","c":["삼 급","이 급","일 급","없습니다"],"e":"「다음에는 삼 급에 도전할 생각이에요」。","qt":"下一個目標是什麼？"}],"lv":2},{"id":"r177","t":"약속을 취소했어요","tz":"取消了約定","k":"[오늘] [친구]와 [홍차]를 마시러 가기로 했는데 [약속]을 [취소했어요|취소하다]. [아침]에 [전화]가 [울렸는데|울리다] [급한|급하다] [일]이 [생겼다고|생기다] 했어요. [친구]는 \"[미안해|미안하다]. [다른] [날] [또는] [주말]에 [만나자|만나다].\" 하고 [말했어요|말하다]. [저]는 \"[괜찮아|괜찮다], [상관]없어.\" 하고 [대답했어요|대답하다]. 사실 [오늘] [비]가 와서 [나가기|나가다] [싫었어요|싫다]. [그러니까] 오히려 잘됐다고 [생각돼요|생각되다].","z":"今天和朋友約好去喝紅茶，但取消了約定。早上電話響了，朋友說發生了急事。朋友說：「對不起。改天或週末再見吧。」我回答：「沒關係，不要緊。」其實今天下雨，我也不想出門。所以反而覺得這樣也好。","q":[{"q":"약속을 취소한 이유는?","c":["친구에게 급한 일이 생겨서","비가 와서","이 사람이 아파서","홍차가 싫어서"],"e":"「급한 일이 생겼다고 했어요」。","qt":"取消約定的原因是？"},{"q":"이 사람은 약속이 취소되어서 어떻게 생각합니까?","c":["잘됐다고 생각합니다","화가 났습니다","슬펐습니다","친구가 싫어졌습니다"],"e":"「오히려 잘됐다고 생각돼요」。","qt":"這個人對約定取消有什麼想法？"}],"lv":3},{"id":"r178","t":"관광 안내","tz":"觀光導覽","k":"[서울]을 [관광하는|관광하다] [외국인]이 [많아요|많다]. 관광 안내소에 가면 [지도]와 안내 [책]을 [무료]로 줘요. [책]에는 [영어], [중국어], [일본어]로 [쓰인|쓰이다] [내용]이 있어요. 안내소 [직원] [님]들이 [친절하게|친절하다] [길]을 [가르쳐|가르치다] 줘요. 관광객들 [중]에는 [한국] [음식]을 [싫어하는|싫어하다] [사람]도 있어서 [양식] [식당]도 [소개해|소개하다] 줘요. [저렇게] [친절한|친절하다] 안내는 [처음]이에요.","z":"在首爾觀光的外國人很多。去觀光服務處會免費提供地圖和導覽書。書裡有用英文、中文、日文寫的內容。服務處的職員們會親切地指路。觀光客之中也有不喜歡韓國食物的人，所以也會介紹西餐廳。那麼親切的導覽我還是第一次見到。","q":[{"q":"관광 안내소에서 무료로 주는 것은?","c":["지도와 안내 책","음식","표","교통 카드"],"e":"「지도와 안내 책을 무료로 줘요」。","qt":"觀光服務處免費提供什麼？"},{"q":"양식 식당을 소개해 주는 이유는?","c":["한국 음식을 싫어하는 사람도 있어서","양식이 싸서","한국 식당이 없어서","직원이 좋아해서"],"e":"「한국 음식을 싫어하는 사람도 있어서 양식 식당도 소개해 줘요」。","qt":"介紹西餐廳的原因是？"}],"lv":2},{"id":"r179","t":"이사 준비","tz":"準備搬家","k":"[새] [집]을 [구했어요|구하다]. [방]은 [두] [개]뿐이지만 [깨끗해요|깨끗하다]. [집] [앞] [길]을 [건너가면|건너가다] [바로] [지하철역]이에요. [친구]가 [걸어와서|걸어오다] [짐]을 [함께] [옮겨|옮기다] 줬어요. [상자]들을 [책상] [위]에 [올려놓고|올려놓다] 먼지가 [안] [들어가게|들어가다] 천으로 [덮었어요|덮다]. 전기가 [안] 들어와서 전구를 [교체]했어요. [고장] 난 [에어컨] [한] [대]는 [빼고|빼다] 나머지는 [다] [괜찮아요|괜찮다].","z":"找到新房子了。雖然只有兩個房間，但很乾淨。過了家門前的馬路就是地鐵站。朋友走過來一起幫我搬行李。把箱子們放到書桌上，用布蓋起來不讓灰塵跑進去。電沒來，所以換了燈泡。除了一台壞掉的冷氣，其他都沒問題。","q":[{"q":"새 집의 방은 몇 개입니까?","c":["두 개","한 개","세 개","네 개"],"e":"「방은 두 개뿐이지만」。","qt":"新家有幾個房間？"},{"q":"무엇이 고장 났습니까?","c":["에어컨 한 대","전구","책상","문"],"e":"「고장 난 에어컨 한 대는 빼고」。","qt":"什麼壞掉了？"}],"lv":3},{"id":"r180","t":"여러 가지 말","tz":"各種說法","k":"[한국어]에는 [재미있는|재미있다] [표현]이 [많아요|많다]. [가족]은 \"[우리] [가족]\"이라고 하고 [남]의 [가족]은 \"[그] [집] [가족]\"이라고 해요. [사람]을 셀 때는 \"[인]\"이나 \"[명]\"을 [써요|쓰다]. [차]는 \"[대]\", [전화]는 \"[통]\"이라고 해요. \"[적]이 있다\"는 [경험]을 [말할|말하다] 때 [써요|쓰다]. [또] [나이]가 [구십] [세]인 [분]께는 [말]을 [더] [조심해요|조심하다]. [그렇게] [하면|하다] 예의 있는 [사람]이 돼요.","z":"韓語有很多有趣的說法。自己家說「我們家」，別人的家庭說「那家人」。數人的時候用「인」或「명」。車用「대」，電話用「통」。「曾經有過」用在說經驗的時候。還有，對九十歲的長輩說話要更小心。那樣做就會成為有禮貌的人。","q":[{"q":"차를 셀 때 쓰는 말은?","c":["대","통","명","인"],"e":"「차는 '대', 전화는 '통'이라고 해요」。","qt":"數車子時用哪個詞？"},{"q":"「적이 있다」는 언제 씁니까?","c":["경험을 말할 때","사람을 셀 때","나이를 말할 때","가족을 말할 때"],"e":"「'적이 있다'는 경험을 말할 때 써요」。","qt":"「적이 있다」什麼時候用？"}],"lv":3},{"id":"r181","t":"선생님께 드리는 편지","tz":"給老師的信","k":"[선생님], [요즘] [건강]은 [어떠하십니까|어떠하다]? 저는 [오늘] [한국어] [책] [십] [과]를 [다] [배웠어요|배우다]. [책]에 나온 [사물] [이름]과 [사례]가 [많아서|많다] [도움]이 됐어요. [처음]에는 [공부]가 [잘] [안돼서|안되다] [걱정]했어요. [하지만] [선생님] [덕분]에 [하루]에 [단어]를 [열] [개][씩] 외울 수 있게 됐어요. [다음] [주]에 찾아뵙겠습니다. [안녕히] [계세요|계시다].","z":"老師，您最近身體好嗎？我今天把韓語課本第十課全部學完了。書裡有很多物品名稱和例子，很有幫助。一開始書讀不太進去，很擔心。但是託老師的福，現在一天能背十個單字了。下週會去拜訪您。祝您安好。","q":[{"q":"이 사람은 오늘 무엇을 했습니까?","c":["책 십 과를 다 배웠습니다","선생님을 만났습니다","시험을 봤습니다","편지를 받았습니다"],"e":"「오늘 한국어 책 십 과를 다 배웠어요」。","qt":"這個人今天做了什麼？"},{"q":"이 사람은 지금 하루에 단어를 몇 개씩 외웁니까?","c":["열 개","다섯 개","스무 개","세 개"],"e":"「하루에 단어를 열 개씩 외울 수 있게 됐어요」。","qt":"這個人現在一天背幾個單字？"}],"lv":3},{"id":"r182","t":"운전 연습","tz":"練習開車","k":"저는 [다음] [달]부터 [운전]을 [배우기로|배우다] [결정했어요|결정하다]. [아버지]께 [얘기]하니까 \"그렇습니까? [아니], [벌써] [운전]을 [배워|배우다]?\" 하고 [놀라셨어요|놀라다]. 제가 \"[네], [그렇습니다].\" 하고 [대답했어요|대답하다]. [학원]은 [일주일]에 [두] [번][뿐]이에요. [수업] [사이]의 [간]에는 [혼자] [연습]해야 해요. [운전] [시험]에서 [영] [점]을 받으면 [안] [되니까|되다] [열심히] 할 거예요. [차] [없이] [시골]에 가면 [불편하니까|불편하다] [꼭] [필요]해요.","z":"我決定從下個月開始學開車。跟爸爸說了之後，他很驚訝地說：「是嗎？什麼，已經要學開車了？」我回答：「是的，沒錯。」補習班一週只有兩次。課與課之間要自己練習。駕照考試不能拿零分，所以會努力的。沒有車去鄉下很不方便，所以一定需要。","q":[{"q":"운전 학원은 일주일에 몇 번입니까?","c":["두 번","한 번","세 번","매일"],"e":"「학원은 일주일에 두 번뿐이에요」。","qt":"駕訓班一週幾次？"},{"q":"운전이 필요한 이유는?","c":["차 없이 시골에 가면 불편해서","회사가 멀어서","아버지가 원해서","친구가 운전해서"],"e":"「차 없이 시골에 가면 불편하니까 꼭 필요해요」。","qt":"需要開車的原因是？"}],"lv":3},{"id":"r183","t":"동물원","tz":"動物園","k":"[주말]에 동물원에 갔어요. [돼지]와 [소], [학], [호랑이] [등] [여러] [동물][들]이 있었어요. [표]는 [어른] [만] [원][짜리], [어린이] 오천 [원]짜리였어요. [아이]들은 [새] [신]을 [신고|신다] 신나게 뛰어다녔어요. 동물원 [안]은 [깨끗해서|깨끗하다] 바닥에 [휴지] [한] [장]도 없었어요. [동물]들을 보고 있으니까 [마음]이 [이래요|이렇다]. [정말] [편해요|편하다].","z":"週末去了動物園。有豬、牛、鶴、老虎等各種動物。票價大人一萬韓元，兒童五千韓元。孩子們穿著新鞋子開心地跑來跑去。動物園裡很乾淨，地上連一張衛生紙都沒有。看著動物們，心情就是這樣——真的很平靜。","q":[{"q":"어린이 표는 얼마입니까?","c":["오천 원","만 원","삼천 원","무료"],"e":"「어린이 오천 원짜리였어요」。","qt":"兒童票多少錢？"},{"q":"동물원에 없었던 동물은?","c":["고양이","돼지","학","호랑이"],"e":"文中提到豬、牛、鶴、老虎，沒有貓。","qt":"動物園裡沒有哪種動物？"}],"lv":3},{"id":"r40","t":"중국집에서","tz":"在中餐館","k":"[점심시간]에 [회사] [근처] [중국집]에 갔어요. [메뉴]를 보고 [자장면]과 [볶음밥]을 [시켰어요|시키다]. [종업원]이 [물]과 [반찬]을 [가져다|가져오다] 줬어요. [음식]이 [빨리] 나와서 [좋았어요|좋다]. [자장면]은 [달고|달다] [맛있었지만|맛있다] [볶음밥]은 [조금] [짰어요|짜다]. [계산할|계산하다] 때 [카드]가 안 돼서 [현금]으로 [냈어요|내다].","z":"午餐時間去了公司附近的中餐館。看了菜單點了炸醬麵和炒飯。服務生拿了水和小菜來。菜上得很快，很好。炸醬麵甜甜的很好吃，但是炒飯有點鹹。結帳時不能刷卡，所以付了現金。","q":[{"q":"무엇을 시켰습니까?","c":["자장면과 볶음밥","자장면과 짬뽕","볶음밥과 만두","냉면과 만두"],"e":"「자장면과 볶음밥을 시켰어요」。","qt":"點了什麼？"},{"q":"어떻게 계산했습니까?","c":["현금으로","카드로","친구가 냈습니다","계산하지 않았습니다"],"e":"「카드가 안 돼서 현금으로 냈어요」。","qt":"怎麼結帳的？"}],"lv":2},{"id":"r41","t":"배달 음식","tz":"外送","k":"[요즘] [한국]에서는 [배달]을 [많이] [시켜요|시키다]. [밤] [늦게|늦다]도 치킨, [피자], [햄버거] 같은 [음식]을 [집]에서 [먹을|먹다] 수 있어요. [인터넷]이나 [핸드폰]으로 [주문하면|주문하다] 삼십 [분] [정도] 걸려요. [어제]는 [친구]들과 [피자]와 [콜라]를 시켰어요. 너무 [많이] 먹어서 [배]가 [불렀어요|부르다]. [편하지만|편하다] [자주] 먹으면 [건강]에 [나빠요|나쁘다].","z":"最近在韓國很多人叫外送。就算深夜也能在家吃到炸雞、披薩、漢堡之類的食物。用網路或手機點餐，大約要三十分鐘。昨天和朋友們叫了披薩和可樂。吃太多了，肚子好飽。雖然方便，但是常吃對健康不好。","q":[{"q":"배달 음식은 보통 얼마나 걸립니까?","c":["삼십 분 정도","한 시간 정도","십 분 정도","두 시간 정도"],"e":"「삼십 분 정도 걸려요」。","qt":"外送通常要多久？"},{"q":"어제 무엇을 시켰습니까?","c":["피자와 콜라","치킨과 맥주","햄버거와 사이다","자장면"],"e":"「피자와 콜라를 시켰어요」。","qt":"昨天點了什麼？"}],"lv":2},{"id":"r42","t":"카페에서","tz":"在咖啡廳","k":"[저]는 [커피]를 [좋아해서|좋아하다] [하루]에 두 [잔]을 [마셔요|마시다]. [오늘]은 [친구]와 [학교] [앞] [커피숍]에 갔어요. [저]는 [뜨거운|뜨겁다] 커피를 [시키고|시키다] [친구]는 [차가운|차갑다] [녹차]를 시켰어요. [케이크]도 하나 [시켜서|시키다] [나눠|나누다] 먹었어요. [창문] [옆] [자리]에 [앉아서|앉다] [이야기]를 [많이] 했어요. [분위기]가 [좋아서|좋다] [또] 오고 [싶어요|싶다].","z":"我喜歡咖啡，一天喝兩杯。今天和朋友去了學校前面的咖啡店。我點了熱咖啡，朋友點了冰綠茶。還點了一個蛋糕分著吃。坐在窗邊的位子聊了很多。氣氛很好，想再來。","q":[{"q":"친구는 무엇을 마셨습니까?","c":["차가운 녹차","뜨거운 커피","차가운 커피","홍차"],"e":"「친구는 차가운 녹차를 시켰어요」。","qt":"朋友喝了什麼？"},{"q":"이 글의 내용과 같은 것은?","c":["케이크를 나눠 먹었습니다","커피를 하루에 한 잔 마십니다","혼자 카페에 갔습니다","분위기가 나빴습니다"],"e":"「케이크도 하나 시켜서 나눠 먹었어요」。","qt":"下列哪一項和內容相同？"}],"lv":2},{"id":"r43","t":"여름 음식","tz":"夏天的食物","k":"한국의 [여름]은 [아주] [더워요|덥다]. [그래서] [시원한|시원하다] [음식]을 [많이] 먹어요. [냉면]은 [차가운|차갑다] [국수]라서 [여름]에 [인기]가 [많아요|많다]. [또] [삼계탕]도 [여름]에 먹어요. [뜨거운|뜨겁다] [음식]이지만 [몸]에 [좋다고|좋다] 해요. [수박]과 [아이스크림]도 빼놓을 수 없어요. 저는 [냉면]을 [제일] [좋아해요|좋아하다].","z":"韓國的夏天非常熱。所以會吃很多涼爽的食物。冷麵是冰涼的麵，所以夏天很受歡迎。另外夏天也吃人蔘雞湯。雖然是熱的食物，但據說對身體很好。西瓜和冰淇淋也少不了。我最喜歡冷麵。","q":[{"q":"삼계탕은 어떤 음식입니까?","c":["뜨겁지만 몸에 좋은 음식","차가운 국수","겨울에만 먹는 음식","매운 음식"],"e":"「뜨거운 음식이지만 몸에 좋다고 해요」。","qt":"人蔘雞湯是什麼樣的食物？"},{"q":"이 사람이 제일 좋아하는 음식은?","c":["냉면","삼계탕","수박","아이스크림"],"e":"「냉면을 제일 좋아해요」。","qt":"這個人最喜歡的食物是？"}],"lv":3},{"id":"r44","t":"겨울 음식","tz":"冬天的食物","k":"[추운|춥다] [겨울]에는 [따뜻한|따뜻하다] [국]이 먹고 [싶어요|싶다]. 저는 [설렁탕]과 [갈비탕]을 [좋아해요|좋아하다]. [친구]는 [감자탕]을 [제일] 좋아해요. [어머니]는 [겨울]마다 [된장국]을 [끓여|끓이다] 주세요. [길]에서 파는 [떡]과 [만두]도 [맛있어요|맛있다]. [뜨거운|뜨겁다] 음식을 먹으면 [몸]이 [따뜻해져요|따뜻하다].","z":"寒冷的冬天會想喝熱湯。我喜歡雪濃湯和排骨湯。朋友最喜歡馬鈴薯排骨湯。媽媽每年冬天都會煮大醬湯給我們喝。路邊賣的年糕和餃子也很好吃。吃熱的食物身體就會變暖。","q":[{"q":"친구가 제일 좋아하는 음식은?","c":["감자탕","설렁탕","갈비탕","된장국"],"e":"「친구는 감자탕을 제일 좋아해요」。","qt":"朋友最喜歡的食物是？"},{"q":"어머니가 겨울마다 만드시는 음식은?","c":["된장국","설렁탕","만두","떡"],"e":"「어머니는 겨울마다 된장국을 끓여 주세요」。","qt":"媽媽每年冬天做的食物是？"}],"lv":2},{"id":"r45","t":"빵집","tz":"麵包店","k":"우리 [동네]에 [새] [빵집]이 [생겼어요|생기다]. [밀가루]와 [설탕]을 [조금]만 쓰고 버터도 [좋은|좋다] 것을 쓴대요. [아침] 일곱 [시]에 [문]을 [열어서|열다] 출근하는 [사람]들이 [많이] 와요. 저는 [샌드위치]와 [우유]를 사서 [아침]으로 먹어요. [주말]에는 [케이크]와 [초콜릿]도 [팔아요|팔다]. [가격]도 [비싸지|비싸다] 않아서 [자주] 가요.","z":"我們社區新開了一家麵包店。聽說只用一點麵粉和糖，奶油也用好的。早上七點開門，所以很多上班族會來。我買三明治和牛奶當早餐。週末也賣蛋糕和巧克力。價格也不貴，所以常去。","q":[{"q":"빵집은 몇 시에 문을 엽니까?","c":["아침 일곱 시","아침 여덟 시","아침 아홉 시","오전 열 시"],"e":"「아침 일곱 시에 문을 열어서」。","qt":"麵包店幾點開門？"},{"q":"이 사람은 아침에 무엇을 먹습니까?","c":["샌드위치와 우유","케이크","초콜릿과 우유","빵과 커피"],"e":"「샌드위치와 우유를 사서 아침으로 먹어요」。","qt":"這個人早上吃什麼？"}],"lv":2},{"id":"r46","t":"요리 교실","tz":"烹飪教室","k":"저는 [문화] [센터]에서 [한국] [요리]를 [배워요|배우다]. [선생님]이 [재료]를 [준비해|준비하다] 주시고 [방법]을 [천천히] [설명해|설명하다] 주세요. [지난주]에는 [불고기]를 만들었어요. [소고기]를 [얇게|얇다] [썰어서|썰다] [간장], [설탕], [마늘]을 넣었어요. 그다음 [고기]를 [구웠어요|굽다]. 이번 [주]에는 잡채를 만들 거예요.","z":"我在文化中心學做韓國料理。老師會幫我們準備材料，並慢慢地說明做法。上週做了烤肉。把牛肉切薄，加入醬油、糖和大蒜。然後把肉烤熟。這週要做雜菜。","q":[{"q":"불고기에 넣지 않은 것은?","c":["고추장","간장","설탕","마늘"],"e":"加了醬油、糖、大蒜，沒有提到辣椒醬。","qt":"烤肉裡沒有放什麼？"},{"q":"재료는 누가 준비합니까?","c":["선생님","학생","이 사람","친구"],"e":"「선생님이 재료를 준비해 주시고」。","qt":"材料是誰準備的？"}],"lv":2},{"id":"r47","t":"편의점 도시락","tz":"便利商店便當","k":"[회사원]들은 [점심]을 [빨리] 먹고 [싶을|싶다] 때 편의점에 가요. 편의점에는 [김밥], [라면], [샌드위치], 도시락 같은 [음식]이 [많아요|많다]. [가격]도 [싸서|싸다] [학생]들도 [자주] 이용해요. [뜨거운|뜨겁다] [물]이 있어서 [라면]을 [바로] 먹을 수 있어요. 저는 [바쁠|바쁘다] 때 삼각김밥과 [음료수]를 사요. 하지만 [매일] 먹으면 [건강]에 [좋지|좋다] 않아요.","z":"上班族想快點吃午餐時會去便利商店。便利商店有海苔飯捲、泡麵、三明治、便當之類的很多食物。價格也便宜，所以學生也常去。有熱水，可以馬上吃泡麵。我忙的時候會買三角飯糰和飲料。但是每天吃對健康不好。","q":[{"q":"편의점에서 라면을 바로 먹을 수 있는 이유는?","c":["뜨거운 물이 있어서","가격이 싸서","사람이 없어서","라면이 맛있어서"],"e":"「뜨거운 물이 있어서 라면을 바로 먹을 수 있어요」。","qt":"在便利商店能馬上吃泡麵的原因是？"},{"q":"이 사람은 바쁠 때 무엇을 삽니까?","c":["삼각김밥과 음료수","라면과 김밥","도시락","샌드위치와 우유"],"e":"「바쁠 때 삼각김밥과 음료수를 사요」。","qt":"這個人忙的時候買什麼？"}],"lv":2},{"id":"r48","t":"옷가게에서","tz":"在服飾店","k":"[어제] [동대문시장]에 있는 [옷가게]에 갔어요. [가게]에는 [바지], [치마], [티셔츠], [스웨터] [등] [여러가지] [옷]이 있었어요. [저]는 [청바지]를 [입어|입다] 봤는데 [사이즈]가 [조금] [작았어요|작다]. [점원]이 [다른|다르다] 사이즈를 [가져다|가져오다] 줬어요. [하늘색] [와이셔츠]도 [마음]에 들었어요. [모두] 오만 원이었는데 세일해서 사만 원에 [샀어요|사다].","z":"昨天去了東大門市場的服飾店。店裡有褲子、裙子、T恤、毛衣等各式各樣的衣服。我試穿了牛仔褲，但尺寸有點小。店員拿了別的尺寸來給我。天藍色的襯衫我也很喜歡。全部是五萬韓元，但因為特價，四萬韓元就買了。","q":[{"q":"청바지는 어땠습니까?","c":["사이즈가 작았습니다","너무 비쌌습니다","색깔이 이상했습니다","사이즈가 컸습니다"],"e":"「사이즈가 조금 작았어요」。","qt":"牛仔褲怎麼樣？"},{"q":"모두 얼마에 샀습니까?","c":["사만 원","오만 원","삼만 원","육만 원"],"e":"原價五萬，特價後「사만 원에 샀어요」。","qt":"全部花多少錢買的？"}],"lv":2},{"id":"r49","t":"겨울 옷","tz":"冬天的衣服","k":"[날씨]가 [추워져서|춥다] [겨울] [옷]을 [꺼냈어요|꺼내다]. [옷장]에는 [코트], [점퍼], [재킷]이 있어요. [밖]에 나갈 때는 [장갑]을 [끼고|끼다] [모자]도 [써요|쓰다]. [두꺼운|두껍다] [양말]을 [신으면|신다] [발]이 [따뜻해요|따뜻하다]. [하지만] [집]에 [들어오면|들어오다] [바로] [코트]를 [벗어요|벗다]. 실내는 [덥기|덥다] 때문이에요.","z":"天氣變冷了，所以把冬天的衣服拿出來。衣櫃裡有大衣、外套和夾克。出門時戴上手套，也戴帽子。穿厚襪子腳就會很暖。但是一進家門就馬上脫掉大衣。因為室內很熱。","q":[{"q":"밖에 나갈 때 무엇을 합니까?","c":["장갑을 끼고 모자를 씁니다","코트를 벗습니다","얇은 양말을 신습니다","옷장을 정리합니다"],"e":"「장갑을 끼고 모자도 써요」。","qt":"出門時做什麼？"},{"q":"집에 들어오면 코트를 벗는 이유는?","c":["실내가 더워서","코트가 무거워서","코트가 더러워서","밖이 따뜻해서"],"e":"「실내는 덥기 때문이에요」。","qt":"一進家門就脫大衣的理由是？"}],"lv":2},{"id":"r50","t":"결혼식에 입을 옷","tz":"參加婚禮要穿的衣服","k":"[다음 주|다음주]에 [회사] [선배]의 [결혼식]이 있어요. [남자]들은 [보통] [양복]을 [입고|입다] [넥타이]를 [매요|매다]. [저]는 [검은색] [양복]과 [흰색] [와이셔츠]를 [준비했어요|준비하다]. [구두]도 [깨끗하게|깨끗하다] [닦았어요|닦다]. [여자] [친구]는 [노란색] [원피스]에 [목걸이]와 [반지]를 [하기로|하다] 했어요. [액세서리]를 하면 더 [예뻐요|예쁘다].","z":"下週有公司前輩的婚禮。男生通常穿西裝、打領帶。我準備了黑色西裝和白色襯衫。皮鞋也擦得很乾淨。女性朋友決定穿黃色連身洋裝，戴項鍊和戒指。戴上飾品會更漂亮。","q":[{"q":"이 사람은 무엇을 준비했습니까?","c":["검은색 양복과 흰색 와이셔츠","노란색 원피스","목걸이와 반지","새 구두"],"e":"「검은색 양복과 흰색 와이셔츠를 준비했어요」。","qt":"這個人準備了什麼？"},{"q":"결혼식은 누구의 결혼식입니까?","c":["회사 선배","친구","사촌","형"],"e":"「회사 선배의 결혼식이 있어요」。","qt":"是誰的婚禮？"}],"lv":2},{"id":"r51","t":"색깔","tz":"顏色","k":"저는 [파란색]을 [제일] [좋아해요|좋아하다]. [하늘]과 [바다]의 [색]이라서 [마음]이 [편해요|편하다]. [동생]은 [빨간색]과 [주황색] 같은 [밝은|밝다] [색깔]을 좋아해요. [아버지]는 [회색]이나 [갈색] 옷을 [자주] [입으세요|입다]. [어머니]는 [초록색]을 좋아하셔서 [집]에 [녹색] 식물이 [많아요|많다]. [여러분]은 [무슨] [색]을 좋아해요?","z":"我最喜歡藍色。因為是天空和大海的顏色，讓人心情很平靜。弟弟（妹妹）喜歡紅色和橘色這種明亮的顏色。爸爸常穿灰色或棕色的衣服。媽媽喜歡綠色，所以家裡有很多綠色植物。各位喜歡什麼顏色呢？","q":[{"q":"이 사람이 파란색을 좋아하는 이유는?","c":["하늘과 바다의 색이라서","밝은 색이라서","어머니가 좋아해서","옷이 많아서"],"e":"「하늘과 바다의 색이라서 마음이 편해요」。","qt":"這個人喜歡藍色的原因是？"},{"q":"아버지가 자주 입는 옷의 색은?","c":["회색이나 갈색","빨간색","초록색","파란색"],"e":"「아버지는 회색이나 갈색 옷을 자주 입으세요」。","qt":"爸爸常穿什麼顏色的衣服？"}],"lv":2},{"id":"r52","t":"백화점 세일","tz":"百貨公司特賣","k":"[이번] [주말]부터 [백화점]에서 [세일해요|세일하다]. [모든] [상품]을 [삼십] [퍼센트] 할인해 줘요. [그래서] [백화점]에 [사람]이 [아주] [많았어요|많다]. [저]는 [어머니] [생신] [선물]로 [가방]을 [샀어요|사다]. [점원]이 [예쁘게|예쁘다] 포장해 줬어요. [계산하다|계산하다]은 [카드]로 했고 영수증도 [받았어요|받다].","z":"這個週末開始百貨公司特賣。所有商品打七折。所以百貨公司裡人非常多。我買了包包當作媽媽的生日禮物。店員幫我包裝得很漂亮。用卡片結帳，也拿了收據。","q":[{"q":"이 사람은 무엇을 샀습니까?","c":["어머니 생신 선물로 가방","자기 옷","어머니 구두","화장품"],"e":"「어머니 생신 선물로 가방을 샀어요」。","qt":"這個人買了什麼？"},{"q":"세일은 어떻게 합니까?","c":["모든 상품을 삼십 퍼센트 할인합니다","가방만 할인합니다","오십 퍼센트 할인합니다","평일에만 합니다"],"e":"「모든 상품을 삼십 퍼센트 할인해 줘요」。","qt":"特賣是怎麼打折的？"}],"lv":2},{"id":"r53","t":"병원에 갔어요","tz":"去了醫院","k":"[며칠] [전]부터 [목]이 [아프고|아프다] [콧물]이 [났어요|나다]. [어제]는 [몸살]까지 나서 [회사]에 못 갔어요. [그래서] [집] [근처] [내과]에 갔어요. [의사] 선생님이 [감기]가 [심하다고|심하다] 하셨어요. [주사]를 맞고 [약국]에서 [약]을 [샀어요|사다]. [약사]가 [하루]에 세 [번] [식사] [후]에 [먹으라고|먹다] 했어요.","z":"幾天前開始喉嚨痛、流鼻涕。昨天連全身痠痛都出現了，所以沒能去公司。所以去了家附近的內科。醫生說感冒很嚴重。打了針，在藥局買了藥。藥師說一天吃三次，飯後吃。","q":[{"q":"이 사람은 어제 왜 회사에 못 갔습니까?","c":["몸살이 나서","콧물이 나서","병원에 가서","약국에 가서"],"e":"「어제는 몸살까지 나서 회사에 못 갔어요」。","qt":"這個人昨天為什麼沒去公司？"},{"q":"약은 어떻게 먹습니까?","c":["하루에 세 번 식사 후에","하루에 두 번 식사 전에","아침에만","자기 전에"],"e":"「하루에 세 번 식사 후에 먹으라고 했어요」。","qt":"藥要怎麼吃？"}],"lv":2},{"id":"r54","t":"축구하다가 다쳤어요","tz":"踢足球受傷了","k":"[주말]에 [친구]들과 [운동장]에서 [축구]를 했어요. 공을 [차다가|차다] [넘어져서|넘어지다] [무릎]과 [발가락]을 [다쳤어요|다치다]. [피]가 나고 [상처]가 [생겼어요|생기다]. [친구]가 저를 [데리고|데리다] [병원]에 갔어요. [의사] 선생님이 [치료해|치료하다] 주시고 [일주일] [동안] [운동]하지 [말라고|말다] 하셨어요. [다음]부터는 [조심해야|조심하다] 해요.","z":"週末和朋友們在運動場踢足球。踢球時跌倒，膝蓋和腳趾受傷了。流血還有了傷口。朋友帶我去醫院。醫生幫我治療，說一週內不要運動。下次開始要小心。","q":[{"q":"이 사람은 어디를 다쳤습니까?","c":["무릎과 발가락","손과 손가락","허리와 어깨","머리와 목"],"e":"「무릎과 발가락을 다쳤어요」。","qt":"這個人哪裡受傷了？"},{"q":"의사 선생님은 무엇이라고 하셨습니까?","c":["일주일 동안 운동하지 마세요","매일 운동하세요","입원하세요","수술하세요"],"e":"「일주일 동안 운동하지 말라고 하셨어요」。","qt":"醫生說了什麼？"}],"lv":2},{"id":"r55","t":"치과","tz":"牙科","k":"[어젯밤]부터 [이]가 [너무] [아팠어요|아프다]. [그래서] [오늘] [아침] [일찍] [치과]에 갔어요. [의사] 선생님이 [입]을 [크게|크다] 벌리라고 하셨어요. 단 것을 [많이] 먹어서 이가 [나빠졌대요|나빠지다]. [앞]으로는 [사탕]과 [초콜릿]을 [조금]만 먹을 거예요. [밥]을 먹은 [후]에는 꼭 [칫솔]과 [치약]으로 이를 [닦아야|닦다] 해요.","z":"從昨晚開始牙齒非常痛。所以今天一大早去了牙科。醫生叫我把嘴巴張大。聽說因為吃太多甜食，牙齒變差了。以後糖果和巧克力只會吃一點點。吃完飯後一定要用牙刷和牙膏刷牙。","q":[{"q":"이가 나빠진 이유는?","c":["단 것을 많이 먹어서","이를 자주 닦아서","밥을 안 먹어서","물을 많이 마셔서"],"e":"「단 것을 많이 먹어서 이가 나빠졌대요」。","qt":"牙齒變差的原因是？"},{"q":"이 사람은 앞으로 어떻게 할 겁니까?","c":["사탕과 초콜릿을 조금만 먹습니다","치과에 매일 갑니다","밥을 안 먹습니다","초콜릿을 많이 삽니다"],"e":"「사탕과 초콜릿을 조금만 먹을 거예요」。","qt":"這個人以後打算怎麼做？"}],"lv":2},{"id":"r56","t":"건강한 생활","tz":"健康的生活","k":"[건강]을 [위해서|위하다] [저]는 [몇] [가지] [습관]을 [지켜요|지키다]. [매일] [아침] [일찍] [일어나서|일어나다] [삼십] [분] [걸어요|걷다]. [물]을 [많이] [마시고|마시다] [야채]와 [과일]을 [자주] 먹어요. [술]과 [담배]는 [전혀] 안 해요. [밤]에는 열한 시 [전]에 [자려고|자다] [노력해요|노력하다]. [스트레스]를 [받으면|받다] [음악]을 [들어요|듣다].","z":"為了健康，我遵守幾個習慣。每天早上早起走路三十分鐘。多喝水，常吃蔬菜和水果。完全不喝酒也不抽菸。晚上努力在十一點前睡覺。有壓力的話就聽音樂。","q":[{"q":"이 사람이 하지 않는 것은?","c":["술을 마십니다","물을 많이 마십니다","아침에 걷습니다","음악을 듣습니다"],"e":"「술과 담배는 전혀 안 해요」。","qt":"這個人不做的事是？"},{"q":"스트레스를 받으면 무엇을 합니까?","c":["음악을 듣습니다","운동을 합니다","잠을 잡니다","친구를 만납니다"],"e":"「스트레스를 받으면 음악을 들어요」。","qt":"有壓力時做什麼？"}],"lv":2},{"id":"r57","t":"우리 몸","tz":"我們的身體","k":"[사람]의 [몸]에는 [머리], [얼굴], [목], [어깨], [팔], [다리]가 있어요. [얼굴]에는 [눈], [코], [입], [귀]가 있어요. [손]에는 [손가락]이 다섯 개 있고 [발]에도 [발가락]이 다섯 개 있어요. [오래] [앉아서|앉다] [공부하면|공부하다] [허리]와 [어깨]가 [아파요|아프다]. [그래서] [가끔] [일어나서|일어나다] [몸]을 [움직이는|움직이다] 것이 [좋아요|좋다].","z":"人的身體有頭、臉、脖子、肩膀、手臂和腿。臉上有眼睛、鼻子、嘴巴、耳朵。手上有五根手指，腳上也有五根腳趾。坐太久讀書的話，腰和肩膀會痛。所以偶爾站起來活動身體比較好。","q":[{"q":"오래 앉아서 공부하면 어디가 아픕니까?","c":["허리와 어깨","눈과 코","손가락","발가락"],"e":"「허리와 어깨가 아파요」。","qt":"坐太久讀書哪裡會痛？"},{"q":"이 글에서 좋다고 한 것은?","c":["가끔 일어나서 몸을 움직입니다","오래 앉아 있습니다","밤에 공부합니다","운동을 하지 않습니다"],"e":"「가끔 일어나서 몸을 움직이는 것이 좋아요」。","qt":"這篇文章說什麼比較好？"}],"lv":1},{"id":"r58","t":"길 찾기","tz":"問路","k":"[실례합니다|실례하다]. [서점]이 [어디]에 있어요? [여기]에서 [똑바로] 가다가 [사거리]에서 [오른쪽]으로 가세요. [그리고] [횡단보도]를 [건너면|건너다] [큰|크다] [건물]이 [보여요|보이다]. [서점]은 그 건물 [일] [층]에 있어요. [은행] [맞은편]이에요. [걸어서|걷다] 오 [분]쯤 [걸려요|걸리다]. [감사합니다]!","z":"不好意思，請問書店在哪裡？從這裡直走，在十字路口往右轉。然後過了斑馬線就會看到一棟大樓。書店在那棟大樓的一樓。在銀行對面。走路大約要五分鐘。謝謝！","q":[{"q":"서점은 어디에 있습니까?","c":["큰 건물 일 층","은행 옆","사거리 왼쪽","횡단보도 앞"],"e":"「서점은 그 건물 일 층에 있어요」，在銀行對面。","qt":"書店在哪裡？"},{"q":"사거리에서 어느 쪽으로 갑니까?","c":["오른쪽","왼쪽","뒤쪽","똑바로"],"e":"「사거리에서 오른쪽으로 가세요」。","qt":"在十字路口往哪邊走？"}],"lv":3},{"id":"r59","t":"지하철 타기","tz":"搭地鐵","k":"서울은 [지하철]이 [아주] 편리해요. [저]는 [집] [근처] [지하철역]에서 [이] [호]선을 [타요|타다]. [시청]역에서 [일] 호선으로 [갈아타고|갈아타다] [서울역]에서 [내려요|내리다]. [요금]은 [교통]카드로 [내면|내다] 더 싸요. 출근 [시간]에는 [사람]이 [많아서|많다] [자리]가 [거의] 없어요. [내릴|내리다] 때는 [출구] [번호]를 [확인해야|확인하다] 해요.","z":"首爾的地鐵非常方便。我在家附近的地鐵站搭二號線。在市政府站轉一號線，在首爾站下車。車資用交通卡付比較便宜。上班時間人很多，幾乎沒有座位。下車時要確認出口號碼。","q":[{"q":"이 사람은 어디에서 갈아탑니까?","c":["시청역","서울역","집 근처 역","강남역"],"e":"「시청역에서 일 호선으로 갈아타고」。","qt":"這個人在哪裡轉車？"},{"q":"내릴 때 무엇을 확인해야 합니까?","c":["출구 번호","요금","자리","시간"],"e":"「출구 번호를 확인해야 해요」。","qt":"下車時要確認什麼？"}],"lv":2},{"id":"r60","t":"교통사고","tz":"車禍","k":"[어제] [저녁] [집] [앞] [도로]에서 [교통사고]가 [났어요|나다]. [빨간색] [자동차]가 [너무] [빠르게|빠르다] [달리다가|달리다] [택시]와 부딪쳤어요. 다행히 [다친|다치다] [사람]은 없었어요. [곧] [경찰]이 와서 [사고]를 [조사했어요|조사하다]. [그래서] [길]이 [한] [시간] [동안] [많이] [막혔어요|막히다]. [운전할|운전하다] 때는 [항상] [조심해야|조심하다] 해요.","z":"昨天晚上家門前的馬路發生了車禍。一輛紅色汽車開得太快，撞上了計程車。幸好沒有人受傷。警察很快就來調查事故。所以路上塞了一個小時。開車時一定要小心。","q":[{"q":"누가 사고를 조사했습니까?","c":["경찰","택시 기사","의사","이 사람"],"e":"「곧 경찰이 와서 사고를 조사했어요」。","qt":"誰調查了事故？"},{"q":"이 글의 내용과 같은 것은?","c":["다친 사람은 없었습니다","택시가 너무 빨랐습니다","사고는 아침에 났습니다","길이 막히지 않았습니다"],"e":"「다행히 다친 사람은 없었어요」。","qt":"下列哪一項和內容相同？"}],"lv":2},{"id":"r61","t":"공항 가는 길","tz":"去機場的路","k":"[다음] [달]에 [일본]으로 [출장]을 가요. [인천] [공항]까지는 공항버스나 [열차]로 갈 수 있어요. [택시]는 [빠르지만|빠르다] [요금]이 [비싸요|비싸다]. [김포공항]은 [시내]에서 [가까워서|가깝다] [편해요|편하다]. [저]는 [짐]이 [무거워서|무겁다] [공항]버스를 탈 거예요. [비행기]는 [오전] [열] [시]에 [출발해요|출발하다]. [그래서] [새벽]에 [집]에서 [떠나야|떠나다] 해요.","z":"下個月要去日本出差。到仁川機場可以搭機場巴士或列車。計程車很快，但是車資很貴。金浦機場離市區很近，很方便。我行李很重，所以要搭機場巴士。飛機上午十點出發。所以凌晨就得從家裡出發。","q":[{"q":"이 사람은 무엇을 타고 공항에 갑니까?","c":["공항버스","택시","열차","자동차"],"e":"「짐이 무거워서 공항버스를 탈 거예요」。","qt":"這個人要搭什麼去機場？"},{"q":"택시의 단점은?","c":["요금이 비쌉니다","느립니다","짐을 못 넣습니다","없습니다"],"e":"「택시는 빠르지만 요금이 비싸요」。","qt":"計程車的缺點是？"}],"lv":3},{"id":"r62","t":"우리 아파트 주차장","tz":"我們公寓的停車場","k":"우리 [아파트]에는 [지하] [주차장]이 있어요. [하지만] [차]가 [많아서|많다] [저녁]에는 [주차할|주차하다] [곳]이 [거의] 없어요. [그래서] [아버지]는 [가끔] [건너편] [길]에 차를 [세우세요|세우다]. [주차장]에서 [엘리베이터]를 타면 [바로] [집]까지 [올라와요|올라오다]. [엘리베이터]가 [고장] 나면 [계단]으로 [걸어서|걷다] 가야 해요. 우리 집은 [십] [층]이라서 [힘들어요|힘들다].","z":"我們公寓有地下停車場。但是車子很多，晚上幾乎沒有地方停車。所以爸爸偶爾會把車停在對面的路邊。在停車場搭電梯就能直接上到家。電梯故障的話就得走樓梯上去。我們家在十樓，所以很累。","q":[{"q":"저녁에 주차하기 어려운 이유는?","c":["차가 많아서","주차장이 없어서","요금이 비싸서","엘리베이터가 고장 나서"],"e":"「차가 많아서 저녁에는 주차할 곳이 거의 없어요」。","qt":"晚上很難停車的原因是？"},{"q":"이 사람의 집은 몇 층입니까?","c":["십 층","지하","일 층","이십 층"],"e":"「우리 집은 십 층이라서 힘들어요」。","qt":"這個人的家在幾樓？"}],"lv":2},{"id":"r63","t":"이사한 날","tz":"搬家那天","k":"지난 [토요일]에 [새] [아파트]로 [이사]를 했어요. [부동산]에서 [소개해|소개하다] 준 [집]인데 [거실]이 [넓고|넓다] [부엌]도 [깨끗해요|깨끗하다]. [아침]부터 [짐]을 [옮겼어요|옮기다]. [소파]는 [거실] [가운데]에 [두고|두다] [식탁]과 [의자]는 [부엌]에 [놓았어요|놓다]. [냉장고]와 [세탁기]는 [무거워서|무겁다] [아저씨]들이 [도와주셨어요|도와주다]. [저녁]에는 [피곤해서|피곤하다] [바로] [잤어요|자다].","z":"上週六搬到新公寓了。是房屋仲介介紹的房子，客廳寬敞，廚房也很乾淨。從早上開始搬行李。沙發放在客廳中間，餐桌和椅子放在廚房。冰箱和洗衣機很重，所以大叔們幫忙搬。晚上太累了，馬上就睡了。","q":[{"q":"소파는 어디에 두었습니까?","c":["거실 가운데","부엌","방","현관"],"e":"「소파는 거실 가운데에 두고」。","qt":"沙發放在哪裡？"},{"q":"누가 냉장고를 옮겨 주었습니까?","c":["아저씨들","부동산 직원","가족","친구"],"e":"「냉장고와 세탁기는 아저씨들이 도와주셨어요」。","qt":"誰幫忙搬冰箱？"}],"lv":2},{"id":"r64","t":"집안일","tz":"家事","k":"우리 [가족]은 집안일을 [나눠서|나누다] 해요. [아버지]는 [주말]마다 [청소기]로 [청소를 하세요|청소]. [어머니]는 [세탁기]로 [빨래]를 하시고 [저]는 [빨래]를 [정리해요|정리하다]. [동생]은 [저녁]을 먹은 [후]에 [설거지]를 해요. [쓰레기]는 [매일] [아침]에 [제가] [버려요|버리다]. [같이] 하니까 [빨리] [끝나요|끝나다].","z":"我們家分工做家事。爸爸每個週末用吸塵器打掃。媽媽用洗衣機洗衣服，我負責整理衣服。弟弟（妹妹）吃完晚餐後洗碗。垃圾每天早上由我拿去丟。大家一起做，很快就做完了。","q":[{"q":"설거지는 누가 합니까?","c":["동생","아버지","어머니","저"],"e":"「동생은 저녁을 먹은 후에 설거지를 해요」。","qt":"誰洗碗？"},{"q":"이 사람이 하는 일은?","c":["빨래 정리와 쓰레기 버리기","청소","설거지","빨래"],"e":"我整理衣服，每天早上丟垃圾。","qt":"這個人負責做什麼？"}],"lv":2},{"id":"r65","t":"아침 준비","tz":"早上的準備","k":"[아침]에 [일어나면|일어나다] [먼저] [창문]을 [열어요|열다]. [그리고] [화장실]에서 [세수하고|세수하다] [이]를 [닦아요|닦다]. [저녁]에는 [샤워하지만|샤워하다] [아침]에는 [머리]만 [감아요|감다]. [수건]으로 [얼굴]을 [닦고|닦다] [로션]을 [발라요|바르다]. [언니]는 [거울] [앞]에서 [화장하는|화장하다] 데 [삼십] [분]이 걸려요. [아버지]는 [면도]를 하시고 [양복]을 [입으세요|입다].","z":"早上起床後先打開窗戶。然後在廁所洗臉刷牙。晚上會淋浴，但早上只洗頭。用毛巾擦臉後擦乳液。姊姊在鏡子前化妝要花三十分鐘。爸爸刮鬍子後穿上西裝。","q":[{"q":"이 사람은 아침에 무엇을 하지 않습니까?","c":["샤워","세수","머리 감기","로션 바르기"],"e":"「저녁에는 샤워하지만 아침에는 머리만 감아요」。","qt":"這個人早上不做什麼？"},{"q":"언니는 거울 앞에서 무엇을 합니까?","c":["화장합니다","면도합니다","머리를 감습니다","옷을 입습니다"],"e":"「언니는 거울 앞에서 화장하는 데 삼십 분이 걸려요」。","qt":"姊姊在鏡子前做什麼？"}],"lv":2},{"id":"r66","t":"하숙집","tz":"寄宿家庭","k":"저는 [한국]에 [와서|오다] [처음] [여섯] [개월] [동안] [하숙집]에서 [살았어요|살다]. [하숙집] [아주머니]가 [매일] [아침]과 [저녁]을 [차려|차리다] 주셨어요. [방]은 [좁았지만|좁다] [책상]과 [침대], [옷장]이 있었어요. [화장실]은 [다른|다르다] [학생]들과 [같이] [썼어요|쓰다]. [아주머니]가 [친절하셔서|친절하다] [외롭지|외롭다] 않았어요. 지금도 [가끔] [찾아가요|찾아가다].","z":"我來韓國後，最初六個月住在寄宿家庭。寄宿家庭的阿姨每天幫我們準備早餐和晚餐。房間很小，但有書桌、床和衣櫃。廁所和其他學生一起用。阿姨很親切，所以不覺得寂寞。現在也偶爾會去拜訪她。","q":[{"q":"이 사람은 하숙집에서 얼마나 살았습니까?","c":["여섯 개월","일 년","세 개월","이 년"],"e":"「처음 여섯 개월 동안 하숙집에서 살았어요」。","qt":"這個人在寄宿家庭住了多久？"},{"q":"이 글의 내용과 같은 것은?","c":["아주머니가 식사를 준비해 주셨습니다","화장실을 혼자 썼습니다","방이 넓었습니다","지금은 가지 않습니다"],"e":"「매일 아침과 저녁을 차려 주셨어요」。","qt":"下列哪一項和內容相同？"}],"lv":2},{"id":"r67","t":"우리 가족 생일","tz":"我們家人的生日","k":"우리 [가족]의 [생일]은 [모두] [달라요|다르다]. [아버지] [생신]은 [일월] [이십] [일]이고 [어머니] [생신]은 [사월] [오] 일이에요. [형]의 생일은 [유월]에 있고 [누나]는 [구월]에 [태어났어요|태어나다]. 제 생일은 [십이월] 이십오 일이라서 [크리스마스]와 같아요. [동생]은 [삼월] [삼] 일이에요. [달력]에 [날짜]를 [적어|적다] [두면|두다] [잊어버리지|잊어버리다] 않아요.","z":"我們家人的生日都不一樣。爸爸的生日是一月二十日，媽媽的生日是四月五日。哥哥的生日在六月，姊姊是九月出生的。我的生日是十二月二十五日，和聖誕節同一天。弟弟（妹妹）是三月三日。把日期寫在月曆上就不會忘記。","q":[{"q":"이 사람의 생일은 언제입니까?","c":["십이월 이십오 일","일월 이십 일","사월 오 일","삼월 삼 일"],"e":"「제 생일은 십이월 이십오 일이라서 크리스마스와 같아요」。","qt":"這個人的生日是什麼時候？"},{"q":"날짜를 잊어버리지 않는 방법은?","c":["달력에 적어 둡니다","핸드폰에 저장합니다","친구에게 물어봅니다","매일 생각합니다"],"e":"「달력에 날짜를 적어 두면 잊어버리지 않아요」。","qt":"不會忘記日期的方法是？"}],"lv":2},{"id":"r68","t":"일주일 계획","tz":"一週的計畫","k":"[이번] [주]는 [아주] [바빠요|바쁘다]. [월요일]과 [화요일]에는 [회사]에서 [회의]가 있어요. [수요일]에는 [부산]으로 [출장]을 가서 [목요일]에 [돌아와요|돌아오다]. [금요일] [저녁]에는 [친구] [결혼식] [잔치]에 가요. [토요일]에는 [종일] [집]에서 [쉬고|쉬다] [일요일]에는 [교회]에 가요. [평일]에는 [바쁘지만|바쁘다] [주말]에는 [쉴|쉬다] 수 있어서 [좋아요|좋다].","z":"這週非常忙。星期一和星期二公司有會議。星期三去釜山出差，星期四回來。星期五晚上要去朋友的婚宴。星期六整天在家休息，星期日去教會。平日很忙，但週末可以休息，很好。","q":[{"q":"이 사람은 언제 부산에 갑니까?","c":["수요일","월요일","금요일","토요일"],"e":"「수요일에는 부산으로 출장을 가서」。","qt":"這個人什麼時候去釜山？"},{"q":"토요일에는 무엇을 합니까?","c":["집에서 쉽니다","교회에 갑니다","결혼식에 갑니다","회의를 합니다"],"e":"「토요일에는 종일 집에서 쉬고」。","qt":"星期六做什麼？"}],"lv":2},{"id":"r69","t":"시장에서 장보기","tz":"在市場買菜","k":"[어머니]와 [시장]에 장을 [보러|보다] 갔어요. [사과] [다섯] [개]에 [만] [원]이었어요. [계란]은 [한] 판에 육천 원이고 [우유]는 [두] [병]을 샀어요. [돼지고기]는 오백 [그램]을 샀어요. [생선] [가게]에서 [오징어] [두] [마리]와 [새우]도 샀어요. [모두] 삼만 칠천 원을 [썼어요|쓰다]. [봉지]가 [많아서|많다] [손]이 [아팠어요|아프다].","z":"和媽媽去市場買菜。蘋果五顆一萬韓元。雞蛋一盤六千韓元，牛奶買了兩瓶。豬肉買了五百公克。在魚店也買了兩隻魷魚和蝦子。總共花了三萬七千韓元。袋子很多，手好痠。","q":[{"q":"사과는 얼마였습니까?","c":["다섯 개에 만 원","한 개에 만 원","다섯 개에 육천 원","두 개에 만 원"],"e":"「사과 다섯 개에 만 원이었어요」。","qt":"蘋果多少錢？"},{"q":"모두 얼마를 썼습니까?","c":["삼만 칠천 원","만 원","육천 원","오만 원"],"e":"「모두 삼만 칠천 원을 썼어요」。","qt":"總共花了多少錢？"}],"lv":3},{"id":"r70","t":"한국의 숫자","tz":"韓國的數字","k":"한국어에는 숫자가 [두] [가지] 있어요. [하나], [둘], [셋], [넷], [다섯]은 [나이]나 [물건]을 셀 때 써요. [일], [이], [삼], [사], [오]는 [날짜], [전화번호], [돈]을 [말할|말하다] 때 써요. 예를 들면 [스무] [살], [마흔] 살, [쉰] 살처럼 말해요. [하지만] [시간]은 조금 [달라요|다르다]. [시]는 [한] 시, [두] 시로 말하고 [분]은 [십] 분, [이십] 분으로 말해요.","z":"韓語的數字有兩種。하나、둘、셋、넷、다섯用在數年齡或東西時。일、이、삼、사、오用在說日期、電話號碼和錢時。例如說「二十歲、四十歲、五十歲」。但是時間有點不一樣。「點」用한 시、두 시說，「分」用십 분、이십 분說。","q":[{"q":"전화번호를 말할 때 쓰는 숫자는?","c":["일, 이, 삼","하나, 둘, 셋","스물, 서른","두 가지 다"],"e":"「일, 이, 삼, 사, 오는 날짜, 전화번호, 돈을 말할 때 써요」。","qt":"說電話號碼時用哪種數字？"},{"q":"「세 시 삼십 분」에서 「시」는 어떤 숫자를 씁니까?","c":["하나, 둘, 셋","일, 이, 삼","영어 숫자","한자"],"e":"「시는 한 시, 두 시로 말하고」，用固有語數字。","qt":"「三點三十分」的「點」用哪種數字？"}],"lv":2},{"id":"r71","t":"나이","tz":"年齡","k":"[우리] [가족]의 [나이]를 [소개할게요|소개하다]. [할아버지]는 [일흔] [살]이시고 [할머니]는 [예순]아홉 살이세요. [아버지]는 [쉰] 살, [어머니]는 [마흔]여덟 살이에요. [형]은 [서른] 살이고 [저]는 [스물]두 살이에요. [한국]에서는 [처음] [만난|만나다] [사람]에게 [나이]를 [자주] [물어봐요|물어보다]. [나이]에 [따라|따르다] [말]이 [달라지기|다르다] 때문이에요.","z":"我來介紹我們家人的年齡。爺爺七十歲，奶奶六十九歲。爸爸五十歲，媽媽四十八歲。哥哥三十歲，我二十二歲。在韓國常常會問第一次見面的人的年紀。因為說話方式會依年齡不同。","q":[{"q":"아버지는 몇 살입니까?","c":["쉰 살","마흔여덟 살","일흔 살","서른 살"],"e":"「아버지는 쉰 살」。","qt":"爸爸幾歲？"},{"q":"한국 사람들이 나이를 자주 물어보는 이유는?","c":["나이에 따라 말이 달라져서","생일을 알고 싶어서","선물을 주려고","친구가 되고 싶어서"],"e":"「나이에 따라 말이 달라지기 때문이에요」。","qt":"韓國人常問年齡的原因是？"}],"lv":2},{"id":"r72","t":"오래간만에 만난 친구","tz":"久別重逢的朋友","k":"[오늘] [길]에서 [고등학교] [친구]를 [만났어요|만나다]. \"[어머], 민지 씨! [오래간만이에요|오래간만]. [웬일]이에요?\" \"[어], 수진 씨! [정말] [오랜만]이에요. [잘] [지냈어요|지내다]?\" 우리는 [삼] [년] 만에 만났어요. [근처] [커피숍]에서 [이야기]를 [많이] 했어요. [다음]에 [또] 만나기로 하고 [전화번호]를 [바꿨어요|바꾸다].","z":"今天在路上遇到了高中同學。「哎呀，敏智！好久不見。怎麼會在這裡？」「咦，秀真！真的好久不見。過得好嗎？」我們隔了三年才見面。在附近的咖啡店聊了很多。約好下次再見，交換了電話號碼。","q":[{"q":"두 사람은 몇 년 만에 만났습니까?","c":["삼 년","일 년","오 년","십 년"],"e":"「우리는 삼 년 만에 만났어요」。","qt":"兩個人隔了幾年才見面？"},{"q":"헤어지기 전에 무엇을 했습니까?","c":["전화번호를 바꿨습니다","선물을 줬습니다","사진을 찍었습니다","밥을 먹었습니다"],"e":"「전화번호를 바꿨어요」＝交換了電話號碼。","qt":"分開前做了什麼？"}],"lv":3},{"id":"r73","t":"처음 만난 날","tz":"初次見面的那天","k":"\"[처음 뵙겠습니다]. 저는 김민수입니다.\" \"[안녕하십니까]? 저는 이지영이라고 합니다. [만나서|만나다] [반갑습니다].\" \"[성함]을 [다시] 한번 [말씀해|말씀하다] 주시겠어요?\" \"[네], 이지영입니다.\" \"[실례]지만 [무슨] [일]을 하세요?\" \"저는 [고등학교] [선생님]이에요.\" \"[아], [그렇구나]. 저는 [회사원]이에요.\"","z":"「初次見面，我是金民秀。」「您好，我叫李智英。很高興見到您。」「可以請您再說一次您的大名嗎？」「好的，我是李智英。」「不好意思，請問您從事什麼工作？」「我是高中老師。」「啊，原來如此。我是上班族。」","q":[{"q":"이지영 씨의 직업은?","c":["고등학교 선생님","회사원","의사","대학생"],"e":"「저는 고등학교 선생님이에요」。","qt":"李智英的職業是？"},{"q":"김민수 씨는 무엇을 다시 물어봤습니까?","c":["이름","직업","나이","전화번호"],"e":"「성함을 다시 한번 말씀해 주시겠어요?」＝大名。","qt":"金民秀又問了一次什麼？"}],"lv":1},{"id":"r74","t":"여러 가지 직업","tz":"各種職業","k":"우리 [동네]에는 [여러] [직업]을 가진 [사람]들이 [살아요|살다]. 옆집 [아저씨]는 [기자]이고 [아줌마]는 [변호사]예요. 윗집 형은 [군인]이고 [누나]는 [공무원]이에요. 앞집 [할아버지]는 [옛날]에 [대학교] [교수]셨어요. [저]는 [나중]에 [화가]가 되고 [싶어요|싶다]. [그림]을 [그리는|그리다] 것이 [제일] [즐거워요|즐겁다].","z":"我們社區住著從事各種職業的人。隔壁的大叔是記者，阿姨是律師。樓上的哥哥是軍人，姊姊是公務員。對面的爺爺以前是大學教授。我以後想當畫家。畫畫是最快樂的事。","q":[{"q":"옆집 아줌마의 직업은?","c":["변호사","기자","공무원","교수"],"e":"「아줌마는 변호사예요」。","qt":"隔壁阿姨的職業是？"},{"q":"이 사람은 무엇이 되고 싶어 합니까?","c":["화가","기자","군인","교수"],"e":"「나중에 화가가 되고 싶어요」。","qt":"這個人想成為什麼？"}],"lv":2},{"id":"r75","t":"첫 출근","tz":"第一天上班","k":"저는 [올해] [무역] [회사]에 [취직했어요|취직하다]. [오늘]은 [첫] 출근날이었어요. [아침] [여덟] 시 [반]까지 [사무실]에 갔어요. [부장]님이 [다른|다르다] [직원]들에게 저를 [소개해|소개하다] 주셨어요. [사장]님도 [인사]를 해 주셨어요. [오후]에는 [서류]를 [정리하고|정리하다] [이메일]을 [확인했어요|확인하다]. [긴장했지만|긴장되다] [모두] [친절해서|친절하다] [좋았어요|좋다].","z":"我今年在貿易公司找到了工作。今天是第一天上班。早上八點半前到了辦公室。部長把我介紹給其他職員。老闆也跟我打了招呼。下午整理文件、確認電子郵件。雖然很緊張，但大家都很親切，很好。","q":[{"q":"이 사람은 어디에 취직했습니까?","c":["무역 회사","은행","자동차 회사","학교"],"e":"「무역 회사에 취직했어요」。","qt":"這個人在哪裡找到工作？"},{"q":"오후에 무엇을 했습니까?","c":["서류를 정리하고 이메일을 확인했습니다","회의를 했습니다","출장을 갔습니다","사장님을 만났습니다"],"e":"「오후에는 서류를 정리하고 이메일을 확인했어요」。","qt":"下午做了什麼？"}],"lv":3},{"id":"r76","t":"회사 생활","tz":"公司生活","k":"[직장] [생활]은 [생각]보다 [힘들어요|힘들다]. [매일] [아침] [일찍] [출근하고|출근하다] [저녁] 늦게 [퇴근해요|퇴근하다]. [일]이 [많으면|많다] [주말]에도 [일해야|일하다] 해요. [하지만] [월급]을 [받는|받다] 날은 [기분]이 [좋아요|좋다]. 동료들과 [함께] [점심]을 먹으면서 [이야기하는|이야기하다] 것도 [즐거워요|즐겁다]. [다음] [달]에는 [휴가]를 [받아서|받다] [해외여행]을 갈 거예요.","z":"職場生活比想像的辛苦。每天一早上班，晚上很晚才下班。工作多的話週末也得上班。但是領薪水的日子心情很好。和同事們一起吃午餐聊天也很愉快。下個月要請假去國外旅行。","q":[{"q":"이 사람이 기분이 좋은 날은?","c":["월급을 받는 날","주말에 일하는 날","늦게 퇴근하는 날","일이 많은 날"],"e":"「월급을 받는 날은 기분이 좋아요」。","qt":"這個人心情好的日子是？"},{"q":"다음 달에 무엇을 할 겁니까?","c":["해외여행을 갑니다","회사를 그만둡니다","이사를 합니다","출장을 갑니다"],"e":"「휴가를 받아서 해외여행을 갈 거예요」。","qt":"下個月要做什麼？"}],"lv":2},{"id":"r77","t":"세계의 나라","tz":"世界各國","k":"[세계]에는 [많은|많다] [나라]가 있어요. [아시아]에는 [한국], [중국], [일본], [태국], [베트남], [몽골], [인도]가 있어요. [유럽]에는 [영국], [독일], [프랑스]가 있고 [러시아]는 [아주] [큰|크다] 나라예요. [미국]과 [캐나다]는 [북쪽] 아메리카에 있고 [멕시코]와 [브라질]은 [남쪽]에 있어요. [이집트]와 [요르단]은 [아프리카]와 [아시아] [사이]에 있어요. [호주]는 [섬]이 [많은|많다] 나라예요.","z":"世界上有很多國家。亞洲有韓國、中國、日本、泰國、越南、蒙古、印度。歐洲有英國、德國、法國，俄羅斯是非常大的國家。美國和加拿大在美洲北邊，墨西哥和巴西在南邊。埃及和約旦在非洲和亞洲之間。澳洲是島嶼很多的國家。","q":[{"q":"유럽에 있는 나라가 아닌 것은?","c":["몽골","영국","독일","프랑스"],"e":"蒙古在亞洲。","qt":"下列哪一個不是歐洲國家？"},{"q":"이 글의 내용과 같은 것은?","c":["러시아는 아주 큰 나라입니다","캐나다는 아시아에 있습니다","브라질은 북쪽에 있습니다","호주에는 섬이 없습니다"],"e":"「러시아는 아주 큰 나라예요」。","qt":"下列哪一項和內容相同？"}],"lv":2},{"id":"r78","t":"외국어 공부","tz":"學外語","k":"저는 [외국어]를 [배우는|배우다] 것을 [좋아해요|좋아하다]. [중학교] 때부터 [영어]를 [공부했고|공부하다] [대학교]에서는 [일본어]와 [중국어]를 배웠어요. [지금]은 [한국말]을 배우고 있어요. [한국어]는 [한자]로 된 [단어]가 [많아서|많다] [중국어]를 알면 [도움]이 돼요. [친구]는 [아랍어]를 공부하는데 [글]이 [너무] [어렵대요|어렵다]. [외국어]를 알면 [여러] 나라 [사람]들과 [이야기할|이야기하다] 수 있어요.","z":"我喜歡學外語。從國中開始學英文，大學時學了日文和中文。現在在學韓語。韓語有很多由漢字組成的單字，所以懂中文會有幫助。朋友在學阿拉伯語，聽說文字太難了。懂外語就能和許多國家的人聊天。","q":[{"q":"이 사람이 지금 배우는 언어는?","c":["한국어","일본어","중국어","아랍어"],"e":"「지금은 한국말을 배우고 있어요」。","qt":"這個人現在學的語言是？"},{"q":"중국어가 한국어 공부에 도움이 되는 이유는?","c":["한자로 된 단어가 많아서","문법이 같아서","발음이 같아서","글이 같아서"],"e":"「한자로 된 단어가 많아서 중국어를 알면 도움이 돼요」。","qt":"中文對學韓語有幫助的原因是？"}],"lv":2},{"id":"r79","t":"유학생 파티","tz":"留學生派對","k":"[어제] [학교]에서 [유학생] [파티]가 [열렸어요|열리다]. [여러] [나라]에서 온 [외국인] [학생]들이 [모였어요|모이다]. [미국], [독일], [베트남], [브라질] 친구들이 [자기] 나라 [음식]을 [가져왔어요|가져오다]. 저는 [일본] [친구]와 [같이] [일본요리]를 [만들었어요|만들다]. [국적]은 [달라도|다르다] [한국어]로 [이야기할|이야기하다] 수 있어서 [재미있었어요|재미있다]. [세계] [여러] 나라의 [문화]를 [알게|알다] 됐어요.","z":"昨天學校舉辦了留學生派對。來自許多國家的外國學生聚在一起。美國、德國、越南、巴西的朋友們帶來了自己國家的食物。我和日本朋友一起做了日本料理。雖然國籍不同，但可以用韓語聊天，很有趣。認識了世界各國的文化。","q":[{"q":"이 사람은 무엇을 만들었습니까?","c":["일본 요리","한국 음식","베트남 음식","독일 음식"],"e":"「일본 친구와 같이 일본요리를 만들었어요」。","qt":"這個人做了什麼？"},{"q":"유학생들은 무슨 말로 이야기했습니까?","c":["한국어","영어","일본어","자기 나라 말"],"e":"「한국어로 이야기할 수 있어서 재미있었어요」。","qt":"留學生們用什麼語言聊天？"}],"lv":2},{"id":"r80","t":"대한민국","tz":"大韓民國","k":"[한국]의 정식 [이름]은 [대한민국]이에요. [수도]는 [서울]이고 [인구]는 오천만 [명] [정도]예요. [한국] [사람]들은 [우리나라]를 한국이라고 [불러요|부르다]. [한국어]를 쓰는 글자는 [한글]이에요. [옛날]에는 [조선]이라는 나라가 있었어요. [북쪽]에는 [평양]이 [수도]인 [다른|다르다] 나라가 있어서 [남북]으로 나뉘어 있어요. 북쪽에서는 한국어를 [조선말] 또는 [조선어]라고 해요.","z":"韓國的正式名稱是大韓民國。首都是首爾，人口大約五千萬人。韓國人稱自己的國家為韓國。書寫韓語的文字是韓文字。以前有一個叫朝鮮的國家。北邊有另一個以平壤為首都的國家，所以分成南北。北邊把韓語叫做朝鮮話或朝鮮語。","q":[{"q":"한국의 인구는 얼마나 됩니까?","c":["오천만 명 정도","천만 명 정도","일억 명 정도","오백만 명 정도"],"e":"「인구는 오천만 명 정도예요」。","qt":"韓國的人口大約多少？"},{"q":"한국어를 쓰는 글자는?","c":["한글","한자","조선어","영어"],"e":"「한국어를 쓰는 글자는 한글이에요」。","qt":"書寫韓語的文字是？"}],"lv":3},{"id":"r81","t":"운동을 좋아해요","tz":"我喜歡運動","k":"저는 [스포츠]를 [아주] [좋아해요|좋아하다]. [봄]과 [가을]에는 [친구]들과 [야구]나 [농구]를 해요. [여름]에는 [수영장]에서 [수영]을 하고 [겨울]에는 [스케이트]를 [타요|타다]. [형]은 [태권도]를 [잘하고|잘하다] [누나]는 [배구] [선수]예요. [아버지]는 [주말]마다 [골프]를 [치세요|치다]. [어머니]는 [탁구]와 [테니스]를 [좋아하세요|좋아하다]. 우리 [가족]은 [모두] [운동하는|운동하다] 것을 좋아해요.","z":"我非常喜歡運動。春天和秋天和朋友們打棒球或籃球。夏天在游泳池游泳，冬天去溜冰。哥哥很擅長跆拳道，姊姊是排球選手。爸爸每個週末打高爾夫球。媽媽喜歡桌球和網球。我們家大家都喜歡運動。","q":[{"q":"누나는 무슨 운동을 합니까?","c":["배구","태권도","골프","테니스"],"e":"「누나는 배구 선수예요」。","qt":"姊姊做什麼運動？"},{"q":"이 사람은 겨울에 무엇을 합니까?","c":["스케이트를 탑니다","수영을 합니다","야구를 합니다","골프를 칩니다"],"e":"「겨울에는 스케이트를 타요」。","qt":"這個人冬天做什麼？"}],"lv":3},{"id":"r82","t":"월드컵","tz":"世界盃","k":"사 년마다 [월드컵]이 [열려요|열리다]. [세계] [여러] [나라]의 [축구] [팀]이 [경기]를 해요. [올림픽]처럼 [인기]가 [아주] [많아요|많다]. [한국] 팀이 [경기]를 하는 날에는 [사람]들이 [빨간색] 옷을 [입고|입다] [시청] [앞]에 [모여요|모이다]. [큰|크다] 화면으로 경기를 보면서 [박수]를 [치고|치다] [노래]도 [불러요|부르다]. [작년]에는 한국 팀이 이겨서 [모두] [기뻐했어요|기뻐하다].","z":"世界盃每四年舉辦一次。世界各國的足球隊會比賽。和奧運一樣非常受歡迎。韓國隊比賽的日子，人們會穿紅色衣服聚集在市政府前。一邊看大螢幕的比賽一邊拍手唱歌。去年韓國隊贏了，大家都很開心。","q":[{"q":"한국 팀 경기가 있는 날 사람들은 어디에 모입니까?","c":["시청 앞","경기장","학교","공원"],"e":"「시청 앞에 모여요」。","qt":"韓國隊比賽的日子人們聚集在哪裡？"},{"q":"월드컵은 얼마나 자주 열립니까?","c":["사 년마다","매년","이 년마다","십 년마다"],"e":"「사 년마다 월드컵이 열려요」。","qt":"世界盃多久舉辦一次？"}],"lv":2},{"id":"r83","t":"나의 취미 생활","tz":"我的休閒生活","k":"저는 [시간]이 있을 때 [여러] [가지] [취미] [생활]을 [즐겨요|즐기다]. [피아노]와 [바이올린]을 [칠|치다] 수 있어서 [악기] 연주를 [자주] 해요. [친구]들과 [노래방]에 가서 [노래하는|노래하다] 것도 좋아해요. [가끔] [사진기]를 [가지고|가지다] [나가서|나가다] [사진]을 [찍어요|찍다]. [옛날] [카메라]는 [필름]이 [필요해서|필요하다] [조금] [불편해요|불편하다]. [집]에서는 [만화]나 [소설]을 [읽어요|읽다].","z":"我有時間的時候會享受各種休閒生活。我會彈鋼琴和小提琴，所以常常演奏樂器。也喜歡和朋友們去 KTV 唱歌。偶爾帶著相機出門拍照。以前的相機需要底片，所以有點不方便。在家會看漫畫或小說。","q":[{"q":"이 사람이 할 수 있는 악기는?","c":["피아노와 바이올린","기타","피아노와 기타","바이올린만"],"e":"「피아노와 바이올린을 칠 수 있어서」。","qt":"這個人會的樂器是？"},{"q":"옛날 카메라가 불편한 이유는?","c":["필름이 필요해서","무거워서","비싸서","사진이 이상해서"],"e":"「필름이 필요해서 조금 불편해요」。","qt":"以前的相機不方便的原因是？"}],"lv":2},{"id":"r84","t":"텔레비전 프로그램","tz":"電視節目","k":"저는 [저녁]에 [티브이]를 [자주] 봐요. [한국드라마]와 [일본드라마]를 [좋아하고|좋아하다] [뉴스]도 [매일] 봐요. [방송국]마다 [재미있는|재미있다] [프로그램]이 [많아요|많다]. [요즘]은 [유명한|유명하다] [연예인]들이 [나오는|나오다] [음악] 프로그램이 [인기]가 있어요. 제가 [좋아하는|좋아하다] [인기스타]가 [새] [음반]을 [냈어요|내다]. [라디오]에서도 그 [노래]가 [자주] [나와요|나오다].","z":"我晚上常看電視。喜歡韓劇和日劇，也每天看新聞。每家電視台都有很多有趣的節目。最近有名藝人們出演的音樂節目很受歡迎。我喜歡的人氣明星發了新專輯。廣播裡也常常播那首歌。","q":[{"q":"요즘 인기 있는 프로그램은?","c":["음악 프로그램","뉴스","요리 프로그램","드라마"],"e":"「음악 프로그램이 인기가 있어요」。","qt":"最近受歡迎的節目是？"},{"q":"이 사람이 좋아하는 스타는 무엇을 했습니까?","c":["새 음반을 냈습니다","드라마에 나왔습니다","결혼했습니다","라디오를 합니다"],"e":"「새 음반을 냈어요」。","qt":"這個人喜歡的明星做了什麼？"}],"lv":2},{"id":"r85","t":"영화를 보러 갔어요","tz":"去看了電影","k":"[주말]에 [여자] [친구]와 [데이트]를 했어요. [영화관]에서 [유명한|유명하다] [영화배우]가 나오는 [영화]를 봤어요. [영화표]는 [인터넷]으로 [미리] [예약]했어요. 팝콘과 [콜라]를 사서 [자리]에 [앉았어요|앉다]. [영화]가 [너무] [슬퍼서|슬프다] [눈물]이 [났어요|나다]. [여자] [친구]는 [웃기는|웃기다] [영화]를 더 [좋아해서|좋아하다] 다음에는 그런 영화를 보기로 했어요.","z":"週末和女朋友約會。在電影院看了有名電影明星主演的電影。電影票事先在網路上預約好了。買了爆米花和可樂後坐到位子上。電影太悲傷了，流下了眼淚。女朋友比較喜歡好笑的電影，所以決定下次看那種電影。","q":[{"q":"영화표는 어떻게 샀습니까?","c":["인터넷으로 예약했습니다","영화관에서 샀습니다","친구가 샀습니다","전화로 예약했습니다"],"e":"「인터넷으로 미리 예약했어요」。","qt":"電影票是怎麼買的？"},{"q":"영화는 어땠습니까?","c":["너무 슬펐습니다","아주 웃겼습니다","무서웠습니다","재미없었습니다"],"e":"「영화가 너무 슬퍼서 눈물이 났어요」。","qt":"電影怎麼樣？"}],"lv":2},{"id":"r86","t":"춤과 공연","tz":"舞蹈與表演","k":"제 [동생]은 [춤추는|춤추다] 것을 좋아해서 [무용] [학원]에 [다녀요|다니다]. [학원]에서 [한국] [무용]과 현대 무용을 [배워요|배우다]. [지난달]에는 [학교] [축제]에서 [공연]을 했어요. [많은|많다] [사람]들 [앞]에서 [춤]을 [추니까|추다] [조금] [긴장됐대요|긴장되다]. [하지만] [공연]이 [끝나고|끝나다] [사람]들이 [박수]를 [쳐|치다] 줘서 [기뻤대요|기쁘다]. 저도 [동생]이 자랑스러웠어요.","z":"我弟弟（妹妹）喜歡跳舞，所以去上舞蹈補習班。在補習班學韓國舞蹈和現代舞。上個月在學校慶典上表演了。在很多人面前跳舞，聽說有點緊張。但是表演結束後大家給他拍手，他很高興。我也為他感到驕傲。","q":[{"q":"동생은 어디에서 공연을 했습니까?","c":["학교 축제","학원","공원","극장"],"e":"「학교 축제에서 공연을 했어요」。","qt":"弟弟（妹妹）在哪裡表演？"},{"q":"공연이 끝나고 동생은 어땠습니까?","c":["기뻤습니다","슬펐습니다","화가 났습니다","아팠습니다"],"e":"「사람들이 박수를 쳐 줘서 기뻤대요」。","qt":"表演結束後弟弟（妹妹）怎麼樣？"}],"lv":2},{"id":"r87","t":"박물관과 미술관","tz":"博物館和美術館","k":"[서울]에는 [박물관]과 [미술관]이 [많아요|많다]. [국립] [박물관]에서는 한국의 [역사]와 [옛날] [물건]을 볼 수 있어요. [대부분] [무료]라서 [학생]들이 [많이] 와요. [미술관]에서는 [유명한|유명하다] [화가]들의 [그림]을 [구경할|구경하다] 수 있어요. [안]에서는 [사진]을 [찍거나|찍다] [큰|크다] [소리]로 [이야기하면|이야기하다] 안 돼요. [미술] [시간]에 [배운|배우다] 그림을 [직접] 보니까 [감동했어요|감동하다].","z":"首爾有很多博物館和美術館。在國立博物館可以看到韓國的歷史和古老的物品。大部分是免費的，所以很多學生會來。在美術館可以欣賞有名畫家的畫。在裡面不可以拍照或大聲說話。親眼看到美術課學過的畫，很感動。","q":[{"q":"국립 박물관에서 볼 수 있는 것은?","c":["한국의 역사와 옛날 물건","유명한 화가의 그림","영화","공연"],"e":"「한국의 역사와 옛날 물건을 볼 수 있어요」。","qt":"在國立博物館能看到什麼？"},{"q":"미술관 안에서 하면 안 되는 것은?","c":["사진을 찍습니다","그림을 봅니다","조용히 걷습니다","설명을 듣습니다"],"e":"「사진을 찍거나 큰 소리로 이야기하면 안 돼요」。","qt":"在美術館裡不可以做什麼？"}],"lv":2},{"id":"r88","t":"기쁜 날, 슬픈 날","tz":"開心的日子，難過的日子","k":"[사람]은 [누구]나 [기쁜|기쁘다] 날과 [슬픈|슬프다] 날이 있어요. [시험]에 합격했을 때 저는 [정말] [기뻤어요|기쁘다]. [친구]들도 [같이] [기뻐해|기뻐하다] 줬어요. [하지만] [작년]에 키우던 [강아지]가 [죽었을|죽다] 때는 [너무] [슬펐어요|슬프다]. [가족] [모두] [슬퍼했어요|슬퍼하다]. [그때] [친구]가 [옆]에 있어 줘서 [힘]이 됐어요.","z":"每個人都有開心的日子和難過的日子。考試合格的時候我真的很開心。朋友們也一起為我高興。但是去年養的小狗死掉的時候，我非常難過。全家人都很傷心。那時候朋友陪在我身邊，給了我力量。","q":[{"q":"이 사람이 기뻤던 때는?","c":["시험에 합격했을 때","강아지를 샀을 때","친구를 만났을 때","생일일 때"],"e":"「시험에 합격했을 때 저는 정말 기뻤어요」。","qt":"這個人開心的時候是？"},{"q":"강아지가 죽었을 때 누가 힘이 되어 주었습니까?","c":["친구","가족","선생님","강아지"],"e":"「그때 친구가 옆에 있어 줘서 힘이 됐어요」。","qt":"小狗死掉時誰給了他力量？"}],"lv":2},{"id":"r89","t":"화가 난 날","tz":"生氣的那天","k":"[오늘] [아침]에 [동생]이 제 [옷]을 말 없이 [입고|입다] 나갔어요. [그래서] 저는 [화]가 [났어요|나다]. [동생]이 [돌아왔을|돌아오다] 때 [크게|크다] [화내고|화내다] [싸웠어요|싸우다]. [어머니]가 \"[형제]끼리 [싸우면|싸우다] 안 돼.\" 하고 [말씀하셨어요|말씀하다]. [동생]이 \"[미안해|미안하다].\" 하고 사과했어요. 저도 [너무] [화낸|화내다] 것이 [미안했어요|미안하다]. [다음]부터는 [먼저] [물어보기로|물어보다] [약속했어요|약속하다].","z":"今天早上弟弟沒說一聲就穿了我的衣服出門。所以我很生氣。弟弟回來的時候我大發脾氣，跟他吵了一架。媽媽說：「兄弟之間不可以吵架。」弟弟說「對不起」向我道歉。我也覺得自己發太大脾氣很抱歉。我們約好下次要先問一聲。","q":[{"q":"이 사람이 화가 난 이유는?","c":["동생이 말없이 옷을 입고 나가서","동생이 늦게 와서","어머니가 화를 내서","옷이 더러워져서"],"e":"「동생이 제 옷을 말없이 입고 나갔어요. 그래서 화가 났어요」。","qt":"這個人生氣的原因是？"},{"q":"두 사람은 무엇을 약속했습니까?","c":["먼저 물어보기로 했습니다","같이 쇼핑하기로 했습니다","옷을 나누기로 했습니다","싸우지 않기로 했습니다"],"e":"「다음부터는 먼저 물어보기로 약속했어요」。","qt":"兩人約定了什麼？"}],"lv":3},{"id":"r90","t":"제 성격","tz":"我的個性","k":"[사람]들은 저를 [착하고|착하다] [부지런하다고|부지런하다] 해요. 저는 [아침] [일찍] [일어나서|일어나다] [일]을 [미리] 해요. [약속] [시간]도 [절대] [늦지|늦다] 않아요. [하지만] [단점]도 있어요. [걱정]이 [많아서|많다] [작은|작다] [일]에도 긴장해요. [처음] [만난|만나다] [사람] [앞]에서는 [말]을 [잘] 못 해요. [친한|친하다] [친구] [앞]에서는 [잘] 웃고 [이야기해요|이야기하다].","z":"大家說我善良又勤勞。我早上早起，把事情提前做好。約定的時間也絕對不會遲到。但是也有缺點。我擔心的事很多，小事也會緊張。在第一次見面的人面前不太會說話。在好朋友面前就會常笑、聊天。","q":[{"q":"이 사람의 단점은?","c":["걱정이 많습니다","늦게 일어납니다","약속에 늦습니다","친구가 없습니다"],"e":"「걱정이 많아서 작은 일에도 긴장해요」。","qt":"這個人的缺點是？"},{"q":"이 글의 내용과 같은 것은?","c":["약속 시간에 늦지 않습니다","처음 만난 사람과 이야기를 잘합니다","일을 나중에 합니다","친구 앞에서 말을 안 합니다"],"e":"「약속 시간도 절대 늦지 않아요」。","qt":"下列哪一項和內容相同？"}],"lv":3},{"id":"r91","t":"비밀","tz":"秘密","k":"제 [친구]에게는 [비밀]이 있어요. [친구]는 [같은|같다] [반] [남학생]을 [좋아해요|좋아하다]. [하지만] 그 [사람]에게 [말하지|말하다] 못하고 있어요. [친구]는 [매일] 그 [사람]의 [사진]을 보면서 [웃어요|웃다]. [어제] 친구가 \"[너]만 [알아야|알다] 해. [다른|다르다] 사람에게 [절대] [말하지|말하다] 마.\" 하고 [말했어요|말하다]. 저는 [거짓말]을 못 해서 [조금] 걱정돼요.","z":"我的朋友有一個秘密。朋友喜歡同班的男同學。但是還不敢跟那個人說。朋友每天看著那個人的照片笑。昨天朋友對我說：「只有你能知道喔。絕對不要告訴別人。」我不會說謊，所以有點擔心。","q":[{"q":"친구의 비밀은 무엇입니까?","c":["같은 반 남학생을 좋아합니다","거짓말을 했습니다","전학을 갑니다","사진을 잃어버렸습니다"],"e":"「같은 반 남학생을 좋아해요」。","qt":"朋友的秘密是什麼？"},{"q":"이 사람이 걱정하는 이유는?","c":["거짓말을 못 해서","친구가 싫어서","남학생을 좋아해서","비밀을 몰라서"],"e":"「저는 거짓말을 못 해서 조금 걱정돼요」。","qt":"這個人擔心的原因是？"}],"lv":3},{"id":"r92","t":"부부","tz":"夫妻","k":"우리 [부모님]은 [결혼하신|결혼하다] 지 [삼십] [년]이 되셨어요. [아버지]는 [어머니]를 \"여보\"라고 부르시고 [어머니]는 [아버지]를 \"[당신]\"이라고 [부르세요|부르다]. 두 [분]은 [젊었을|젊다] 때 [회사]에서 [처음] 만나셨대요. [지금]도 [주말]마다 [함께] [산책]을 하세요. [저]도 나중에 [남편]과 [아내]가 서로 [사랑하는|사랑하다] 그런 [부부]가 되고 [싶어요|싶다].","z":"我的父母結婚三十年了。爸爸叫媽媽「老婆」，媽媽叫爸爸「老公」。聽說兩位年輕時是在公司第一次見面的。現在每個週末也會一起散步。我以後也想成為那樣彼此相愛的夫妻。","q":[{"q":"부모님은 어디에서 처음 만나셨습니까?","c":["회사","학교","공원","교회"],"e":"「회사에서 처음 만나셨대요」。","qt":"父母在哪裡第一次見面？"},{"q":"부모님은 주말마다 무엇을 하십니까?","c":["함께 산책을 하십니다","여행을 가십니다","회사에 가십니다","운동을 하십니다"],"e":"「지금도 주말마다 함께 산책을 하세요」。","qt":"父母每個週末做什麼？"}],"lv":1},{"id":"r93","t":"우리 학교 후배","tz":"我們學校的學弟","k":"저에게는 [착한|착하다] [후배]가 한 [명] 있어요. [중학교] 때부터 [같은|같다] [학교]에 [다녔어요|다니다]. [후배]는 [초등학생] 때 [미국]에서 [살아서|살다] [영어]를 [잘해요|잘하다]. 저는 [영어]를 [가르쳐|가르치다] 달라고 [부탁했고|부탁하다] 후배는 [수학]을 [물어봐요|물어보다]. 우리는 [서로] [도움]을 [줘요|주다]. [이번] [휴일]에는 [같이] [도서관]에 가서 [공부하기로|공부하다] 했어요.","z":"我有一個很善良的學弟。從國中開始就讀同一所學校。學弟國小時住在美國，所以英文很好。我拜託他教我英文，學弟則會問我數學。我們互相幫助。這次假日約好一起去圖書館讀書。","q":[{"q":"후배가 영어를 잘하는 이유는?","c":["초등학생 때 미국에서 살아서","영어 학원에 다녀서","부모님이 미국 사람이라서","영어를 전공해서"],"e":"「초등학생 때 미국에서 살아서 영어를 잘해요」。","qt":"學弟英文好的原因是？"},{"q":"이번 휴일에 무엇을 합니까?","c":["같이 도서관에서 공부합니다","미국에 갑니다","수학 시험을 봅니다","영화를 봅니다"],"e":"「같이 도서관에 가서 공부하기로 했어요」。","qt":"這次假日做什麼？"}],"lv":2},{"id":"r94","t":"봄 소풍","tz":"春季郊遊","k":"[사월]에 [초등학교] [동생]이 [봄] [소풍]을 갔어요. [어머니]가 [새벽]에 [일어나서|일어나다] [김밥]을 [싸|싸다] 주셨어요. [과자]와 [음료수]도 [가방]에 [넣었어요|넣다]. [공원]에는 [개나리]와 [진달래], [벚꽃]이 [많이] [피어|피다] 있었대요. [아이]들은 잔디에서 [뛰고|뛰다] [놀았어요|놀다]. [동생]은 [집]에 [돌아와서|돌아오다] [피곤해서|피곤하다] [바로] [잠]이 들었어요.","z":"四月的時候，讀國小的弟弟（妹妹）去春季郊遊了。媽媽凌晨起床幫他包了海苔飯捲。餅乾和飲料也放進了包包。聽說公園裡開了很多迎春花、杜鵑花和櫻花。孩子們在草地上跑來跑去地玩。弟弟（妹妹）回家後太累了，馬上就睡著了。","q":[{"q":"어머니는 무엇을 만들어 주셨습니까?","c":["김밥","샌드위치","과자","떡"],"e":"「어머니가 새벽에 일어나서 김밥을 싸 주셨어요」。","qt":"媽媽做了什麼？"},{"q":"공원에 핀 꽃이 아닌 것은?","c":["장미","개나리","진달래","벚꽃"],"e":"開了迎春花、杜鵑花、櫻花，沒有玫瑰。","qt":"公園裡沒有開哪種花？"}],"lv":2}];
